(window.GIM_TS=window.GIM_TS||{})["Niddah.2"]={"from":48,"a":[["\u0003גבי\u0004 \u0005[אצל]\u0006 דין \u0003בכורות\u0004 (בכורות מו,א) שהמפלת סנדל — הבא אחריו הריהו בכור לירושה, ונוטל פי שנים מאחיו, ואין הוא בכור לכהן (שהרי הסנדל נחשב כמי שפטר את רחם אמו), \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נשנה, שהרי ברור שכל הנולד אחריו איננו נחשב כפטר רחם, שהרי אף בלא הסנדל, כבר פטר הולד שעמו (שאינו סנדל) את הבא אחריו?","ומסבירים: נשנה הדבר, \u0003ל\u0004עניינו של זה ש\u0003בא אחריו\u0004 באותה לידה. שכיון שהסנדל יצא בתחילה ממעי אמו — הולד הנולד אחריו הוא אמנם \u0003בכור לנחלה ו\u0004אולם \u0003אין\u0004 הוא \u0003בכור לכהן.\u0004","ומבררים עוד: \u0003סנדל דתנן גבי\u0004 \u0005[ששנינו אצל]\u0006 דין \u0003כריתות\u0004 (כריתות ז,ב) לענין קרבן יולדת, שהיולדת סנדל מביאה קרבן יולדת, \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נשנה, שהרי אף בלא הסנדל, משום הולד שעמו צריכה היא להביא קרבן. ובקרבן זה נפטר אף הסנדל, שהיולדת מביאה קרבן אחד אף על לידת ולדות רבים.","ומשיבים: נצרך הדבר להישנות, לענין \u0003שאם תלד\u0004 את ה\u0003ולד\u0004 שעמו שלא בדרך הרגילה אלא \u0003דרך דופן\u0004 (\"ניתוח קיסרי\"), ואין מביאים קרבן יולדת אלא על לידה שבה נולד הולד דרך פתח הרחם. \u0003ו\u0004אילו את ה\u0003סנדל\u0004 ילדה \u0003דרך\u0004 ה\u0003רחם\u0004 — \u0003דמייתא\u0004 \u0005[שמביאה]\u0006 \u0003קרבן\u0004 על ה\u0003סנדל,\u0004 אף שעל הולד שנולד עמו אינה מביאה קרבן.","ושואלים: \u0003ול\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 כי הולד הנולד כ\u0003יוצא דרך דופן\u0004 — \u0003ולד מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 נחשב, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע הזכירה המשנה את הסנדל, שהרי חייבת האשה להביא קרבן יולדת משום לידת הולד שעם הסנדל?!","\u0003אמר ר'\u0004 \u0003ירמיה\u0004 בהסבר הדברים: צריך הדבר להישנות, כדי ללמדנו \u0003שאם תלד\u0004 את ה\u0003ולד בהיותה\u0004 עדיין \u0003גויה,\u0004 שאינה נוהגת בשלו טומאת לידה, והתגיירה לאחר מכן, ומעתה נוהגים בה דיני טומאת לידה, \u0003ו\u0004את ה\u0003סנדל\u0004 ילדה \u0003לאחר שנתגיירה.\u0004 \u0003דמייתא\u0004 \u0005[שמביאה,\u0006 שצריכה להביא] \u0003קרבן\u0004 על ה\u0003סנדל.\u0004","ונמסר כי \u0003אמרוה רבנן\u0004 \u0005[חכמים]\u0006 להסברים אלה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא,\u0004 ושאלוהו: \u0003ומי איתנהו להני שינויי\u0004 \u0005[והאם ישנם,\u0006 מתקיימים \u0005התירוצים הללו,\u0006 המסבירים שמדובר כשנולד הסנדל לפני הולד שעמו\u0005]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כשהן\u0004 (הסנדל והולד שעמו) \u0003יוצאין\u0004 ממעי אמם — \u0003אין\u0004 הם \u0003יוצאין אלא כרוכין\u0004 זה בזה!","\u0003אמר רב פפא: שמע מינה\u0004 \u0005[למד מכאן],\u0006 כי אין הם שוכבים זה אצל זה (שכן באופן זה לא יתכן שיצא זה קודם לזה), אלא \u0003מכרך כריך ליה\u0004 \u0005[כורך הוא]\u0006 ה\u0003ולד לסנדל אפלגיה\u0004 \u0005[על מחציתו],\u0006 שראשו של הולד תחוב כנגד טבורו של הסנדל, \u0003ומשלחיף ליה\u0004 \u0005[ודוחף\u0006 הולד \u0005אותו]\u0006 \u0003כלפי רישיה\u0004 \u0005[בראשו]\u0006 אל מחוץ למעי האם. \u0003גבי\u0004 \u0005[אצל]\u0006 זה ששנינו במסכת \u0003בכורות,\u0004 שיצא הסנדל תחילה — מדובר \u0003כגון שיצאו דרך ראשיהם,\u0004 שה\u0003סנדל קדים ונפיק\u0004 \u0005[קדם ויצא]\u0006 לפני הולד שעמו. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 זה ששנינו במסכת \u0003כריתות\u0004 — מדובר כש\u0003שיצאו דרך מרגלותיהם,\u0004 שה\u0003ולד קדים ונפיק\u0004 \u0005[קדם ויצא]\u0006 לפני הסנדל.","\u0003רב הונא בר תחליפא משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רבא אמר\u0004 הסבר אחר: \u0003אפילו\u0004 אם \u0003תימא\u0004 \u0005[תאמר]\u0006 ששניהם שוכבים זה בצד זה \u0003מצומצמין\u0004 (דחוקים יחד), אפשר להסביר את הדברים. \u0003ואיפוך שמעתתא\u0004 \u0005[והפוך\u0006 את \u0005השמועה]\u0006 שאמר רב פפא, ובדרך זו: \u0003גבי\u0004 \u0005[אצל]\u0006 זו ששנינו במסכת \u0003בכורות\u0004 — מדובר כ\u0003שיצאו דרך מרגלותיהם,\u0004 ה\u0003ולד דאית ביה חיותא\u0004 \u0005[שיש בו\u0006 רוח \u0005חיים]\u0006 — \u0003סריך\u0004 \u0005[נסרך,\u0006 אוחז בידיו\u0005]\u0006 כלפי מעלה, ואין הוא ממהר לצאת, \u0003ולא נפיק\u0004 \u0005[ואינו יוצא]\u0006 עדיין. ואילו ה\u0003סנדל, דלית ביה חיותא\u0004 \u0005[שאין בו\u0006 רוח \u0005חיים]\u0006 — הריהו \u0003שריק ונפיק\u0004 \u0005[מחליק ויוצא]\u0006 קודם לולד. ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 זו ששנינו במסכת \u0003כריתות\u0004 — מדובר כ\u0003שיצאו דרך ראשיהן,\u0004 ה\u0003ולד, דאית ביה חיותא\u0004 \u0005[שיש בו\u0006 רוח \u0005חיים]\u0006 — \u0003מ\u0004שעה \u0003דנפיק רישיה, הויא\u0004 \u0005[שהוציא ראשו, הריהי]\u0006 נחשבת כ\u0003לידה.\u0004 ואילו ה\u0003סנדל\u0004 — אין זו נחשבת כלידה אלא \u0003עד דנפיק רוביה\u0004 \u0005[שיצא רובו].\u0006","\u0003שליא\u0004 (האיבר דרכו מקבל העובר את מזונו במעי אמו, והוא נתון בו כבנרתיק) הנמצאת \u0003בבית\u0004 — \u0003הבית טמא\u0004 בטומאת אהל, כאילו הוא מאהיל על המת. ובהסברו של דין זה: \u0003לא שהשליא\u0004 נחשבת כ\u0003ולד\u0004 ובגללה נטמא הבית, \u0003אלא שאין שליא בלא ולד,\u0004 וודאי שהיה בשליה זו ולד, אלא שנימוח לאחר שיצאה השליה מן האשה, ומשום אותו ולד נטמא הבית.","\u0003ר' שמעון אומר:\u0004 אין הבית מיטמא בטומאת אהל, משום שאף שהיה ולד בשליה, הרי \u0003נימוק הולד\u0004 ונעשה לדם \u0003עד שלא\u0004 (בטרם) \u0003יצא\u0004 ממעי אמו. ואותו הדם התערב בדם הלידה, ובטל בו ברוב.","שנינו במשנה דינה של השליה, ומביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 כיצד נראית ה\u0003שליא?\u0004 ב\u0003תחלתה,\u0004 בראשית ההריון — הריהי דקה ביותר ו\u0003דומה לחוט\u0004 \u0003של ערב\u0004 (חוט הרוחב במארג, העובר בין חוטי השתי). \u0003ו\u0004ב\u0003סופה —\u0004 הריהי הולכת ומתרחבת ו\u0003דומה כתורמוס\u0004 (מסוגי הקטניות). \u0003וחלולה\u0004 היא השליה \u0003כחצוצרת.\u0004 \u0003ואין שליא\u0004 שהיא \u0003פחותה\u0004 בגודלה \u0003מטפח.\u0004 \u0003רבי שמעון בן גמליאל אומר: שליא דומה לקורקבן\u0004 (קיבת העוף הטוחנת את המזון שנאכל) \u0003של תרנגולין, ש\u0004המעיים \u0003הדקין יוצאין ממנה.\u0004","ואגב מה שאמרו בשליה, ששיעורה הינו לפחות טפח, מביאים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בפי \u0003ר' אושעיא זעירא דמן חבריא\u0004 \u0005[הקטן שבין החברים]:\u0006 \u0003חמשה\u0004 דברים \u0003שיעורן\u0004 לפחות \u0003טפח, ואלו הן:\u0004 ה\u0003שליא,\u0004 וה\u0003שופר\u0004 לתקיעה בראש השנה, וה\u0003שדרה\u0004 של הלולב לנטילת לולב בסוכות, ו\u0003דופן סוכה\u0004 כשרה, \u0003והאזוב\u0004 המשמש לטהרת המצורע, והמשמש לעשיית אפר פרה אדומה ולהזאה על טמא מת.","ומפרטים: \u0003שליא\u0004 — \u0003הא דאמרן\u0004 \u0005[\u0006כהלכה \u0005זו שאמרנו]\u0006 למעלה. \u0003שופר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003כמה יהא שיעור\u0004 ה\u0003שופר\u0004 הכשר לתקיעה בראש השנה? \u0003פירש ר' שמעון בן גמליאל:\u0004 שיהא בו \u0003כדי שיאחזנו\u0004 התוקע \u0003ב\u0004ארבע אצבעות \u0003ידו ו\u0004עוד כדי ש\u0003יראה\u0004 מן השופר \u0003לכאן ולכאן\u0004 משני צידי ידו, והרי זה לפחות כשיעור \u0003טפח.\u0004","\u0003שדרה\u0004 של לולב \u0003מה היא\u0004 עניינה? שכן \u0003אמר ר'\u0004 \u0003פרנך, אמר ר'\u0004 \u0003יוחנן: שדרו של לולב צריך שיהא יוצא מן\u0004 (מתרומם) מעל \u0003ההדס\u0004 האגוד עמו לפחות \u0003טפח.\u0004 \u0003דופן סוכה\u0004 מה עניינו? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 הסוכה הכשירה צריכה שתהיינה בה לפחות \u0003שתים\u0004 דפנות \u0003כהלכתן\u0004 (שאורכן לפחות שבעה טפחים), ואילו שיעור הדופן ה\u0003שלישית\u0004 — \u0003אפילו טפח,\u0004 ובפחות מטפח — אינה כשרה. \u0003אזוב\u0004 מה עניינו? — \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003ר' חייא: אזוב\u0004 המשמש לטהרת מצורע ולעשיית אפר פרה אדומה ולהזאה על טמא מת — שיעורו לא פחות מ\u0003טפח.\u0004","ובענין זה של חמשת הדברים הללו, \u0003אמר ר'\u0004 \u0003חנינא בר פפא\u0004 שכך \u0003דריש\u0004 \u0005[דרש]\u0006 החכם \u0003שילא איש כפר תמרתא\u0004 כסימן לדבר: \u0003תלת\u0004 \u0005[שלוש]\u0006 מההלכות הללו — \u0003מתניתא\u0004 \u0005[משניות]\u0006 הן (השליה, השופר, ודופן הסוכה), \u0003ותרתי\u0004 \u0005[שתים]\u0006 — \u0003שמעתתא\u0004 \u0005ושמועות]\u0006 הן (שדרת הלולב, והאזוב), ש\u0003שיעורא\u0004 \u0005[שיעור]\u0006 כולם הוא לפחות \u0003טפח.\u0004 ושואלים על סימן זה: \u0003תרתי\u0004 \u0005[שתיים]\u0006 הן הלכות שמועה? והלא רק \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003היא\u0004 ההלכה בשדרת הלולב, שהרי את שיעור האזוב שנה ר' חייא בברייתא! \u0003אמר אביי\u0004 בתשובה: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 גירסתך, שלא שנה ר' חייא את דין האזוב כברייתא אלא ש\u0003אמר ר'\u0004 \u0003חייא\u0004 שדין ה\u0003אזוב\u0004 לא פחות מ\u0003טפח,\u0004 ואף זו הריהי איפוא דבר שמועה.","ושואלים על דברי ר' זעירא דמן חבריה שחמישה דברים הם ששיעורם הריהו לפחות טפח: \u0003ותו ליכא\u0004 \u0005[ועוד אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 הלכה זו ששנינו במשנה במסכת אהלות בדין שיעור האהל המביא את הטומאה, שכל שיש באהל אורך \u0003טפח על\u0004 רוחב \u0003טפח על רום\u0004 (בגובה) \u0003טפח מרובע\u0004 — אם נמצא שם כדי שיעור מן המת הראוי לטמא, הרי אהל זה המאהיל עליו \u0003מביא את הטומאה\u0004 על כל הנמצא תחתיו, אף אם אינו נוגע במת, \u0003וחוצץ\u0004 (חוסם) \u0003בפני הטומאה\u0004 מלטמא את הנמצא מעל גביו של אהל זה.","ומתרצים: מנין זה של חמשת הדברים שמנינו — של דברים ששיעורם \u0003טפח\u0004 הוא ש\u0003קאמרינן\u0004 \u0005[אמרנו],\u0006 אבל דברים ששיעורם הוא \u0003טפח על טפח\u0004 — \u0003לא קאמרינן\u0004 \u0005[אמרנו].\u0006","ושואלים עוד: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 הלכה זו ששנינו במשנה במסכת כלים ש\u0003אבן היוצא\u0004 (הבולטת החוצה) \u0003מן התנור,\u0004 ומשמשת לו כעין ידית להגבהה ולטלטול, ושיעורה \u0003טפח, ו\u0004כן האבן הבולטת החוצה \u0003מן הכירה\u0004 ששיעורה הוא \u0003שלש אצבעות\u0004 — הרי אלו נחשבות יד, הנצרכת לתנור ולכיריים, ונחשב הדבר להן כ\u0003חבור\u0004 לענין זה שאם נטמא התנור — אף הן נטמאות.","ומתרצים: \u0003כי קאמרינן\u0004 \u0005[כאשר אמרנו]\u0006 אותו מנין של חמשת הדברים — הרי זה \u0003היכא דבציר\u0004 \u0005[היכן,\u0006 במקרה \u0005שפחות]\u0006 \u0003מטפח לא חזי\u0004 \u0005[אינו ראוי],\u0006 ורק משיעור טפח הריהו בכלל הלכה זו, \u0003אבל הכא\u0004 \u0005[כאן\u0006 בדין האבן היוצאת מהתנור או מהכיריים\u0005],\u0006 \u0003כל שכן\u0004 אם שיעור האבן הזו הינו \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003מטפח\u0004 — \u0003יד תנור הוא.\u0004","ועוד שואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006"],["\u0003תנורי\u0004 ה\u0003בנות\u0004 הקטנות, העשויים למשחק. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת כלים\u0005]:\u0006 ה\u0003תנור\u0004 של חרס מקבל טומאה ב\u0003תחלתו\u0004 (לאחר גמר מלאכתו) אם הוא בן \u0003ארבעה\u0004 טפחים. \u0003ו\u0004כן אם נטמא התנור, ונשבר, ויש בין \u0003שיריו\u0004 (שבריו) שבר שגודלו \u0003ארבעה\u0004 טפחים — הריהו עדיין טמא, ולא יצא מכדי טומאתו, אלו \u0003דברי ר'\u0004 \u0003מאיר,\u0004","\u0003וחכמים אומרים: במה דברים\u0004 אלה \u0003אמורים\u0004 — דווקא \u0003ב\u0004תנור \u0003גדול,\u0004 \u0003אבל ב\u0004תנור \u0003קטן,\u0004 דינו כך: ב\u0003תחלתו\u0004 הריהו מקבל טומאה אף ששיעורו \u0003כל שהוא משתגמר מלאכתו, ושיריו\u0004 — עדיין טמאים הם, עד שישבר \u0003ברובו.\u0004","\u0003ו\u0004מסבירים: \u0003כמה\u0004 הוא שיעור זה הנקרא \u0003\"כל שהוא\"? אמר ר'\u0004 \u0003ינאי: טפח, שכן\u0004 כך \u0003עושין תנורי בנות\u0004 בשיעור \u0003טפח.\u0004 הרי איפוא שיש עוד דברים, מלבד החמישה שמנה ר' אושעיה זעירא דמן חבריא, ששיעורם טפח! ומתרצים: מנין זה של חמישה דברים הריהו בדברים המוסכמים על הכל, אבל בדברים הנתונים \u0003בפלוגתא\u0004 \u0005[במחלוקת],\u0006 כגון זה בשיעור התנור — \u0003לא קמיירי\u0004 \u0005[אינו עוסק].\u0006","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שבאת לכך],\u0006 לתירוץ זה, שאין המנין כולל דברים שבמחלוקת, \u0003הא נמי\u0004 \u0005[\u0006אף \u0005זו,\u0006 בדין האבן היוצאת מן התנור \u0005גם כן]\u0006 \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003היא,\u0004 ולכן לא נכללה במנין חמשת הדברים ששיעורם טפח. ומהי מחלוקת זו? \u0003דקתני סיפא\u0004 \u0005[ש\u0006הרי \u0005הוא\u0006 התנא \u0005שונה\u0006 ב\u0005סוף המשנה\u0006 במסכת כלים\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יהודה, לא אמרו\u0004 חכמים שרק עד \u0003טפח\u0004 הריהו חיבור בתנור, \u0003אלא\u0004 רק כאשר נתונה האבן הזו בצד ש\u0003מן\u0004 (בין) \u0003התנור ולכותל.\u0004 שכן במקרה זה, כל שבולט יותר מטפח עומד להיחתך, כדי שיוכל התנור להינתן סמוך לכותל, ולכן אין הוא חיבור. אבל אם היתה האבן בולטת לצד פנים הבית, ולא לצד כתליו, אף אם שיעורה יותר מטפח הריהי נחשבת כחיבור לתנור.","וממשיכים ושואלים על דברי ר' אושעיה זעירא דמן חבריא: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 את \u0003מסגרת\u0004 שולחן לחם הפנים שבמקדש שנאמר ששיעורה \u0003טפח!\u0004 ומשיבים: \u0003ב\u0004דברים \u0003דכתיבן\u0004 \u0005[שכתובים]\u0006 שיעורם במפורש במקרא \u0003לא קא מיירי\u0004 \u0005[אין הוא מדבר].\u0006 ושואלים: \u0003והאיכא\u0004 \u0005[\u0006והרי \u0005יש]\u0006 את ה\u0003כפורת\u0004 ששיעורה \u0003טפח,\u0004 ואין שיעורה נזכר במפורש במקרא! ומתרצים: \u0003בקדשים לא קמיירי\u0004 \u0005[אינו עוסק].\u0006","ושואלים: \u0003והאיכא\u0004 \u0005[\u0006והרי \u0005יש]\u0006 הלכה בדין המבוי בשבת, לענין שמותר הטלטול בו על ידי תיקון קורה, ושנינו בה כי \u0003דיה לקורה\u0004 זו \u0003שהיא רחבה טפח\u0004 שתתיר את הטלטול במבוי! ומתרצים: \u0003ב\u0004דברים שהם מ\u0003דרבנן\u0004 \u0005[דברי חכמים]\u0006 \u0003לא קמיירי\u0004 \u0005[אינו עוסק],\u0006 \u0003אלא\u0004 רק \u0003ב\u0004דברים \u0003דכתיבן ולא מפרשי שיעורייהו\u0004 \u0005[שכתובים\u0006 בתורה, \u0005ו\u0006אולם \u0005אין מפורש שיעורם].\u0006","שנינו במשנה כי המפלת שליה הריהי יושבת ימי טומאה וימי טהרה כיולדת זכר וכיולדת נקבה. ועוד בענין זה נמסר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יצחק בר שמואל בר מרתא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב כהנא, ויתיב וקאמר\u0004 \u0005[וישב ואמר]\u0006 שכך \u0003אמר רב יהודה, אמר רב:\u0004 יצאה שליה מן האשה היולדת אם היה זה \u0003כל שלשה ימים הראשונים\u0004 שלאחר לידת הולד — \u0003תולין\u0004 (מייחסים) \u0003את השליא\u0004 הזו \u0003בולד\u0004 שנולד, שבשליה זו היה הולד נתון, ואולם אם יצאה השליה \u0003מכאן ואילך,\u0004 יותר משלושה ימים שלאחר הלידה — \u0003חוששין לולד אחר\u0004 שהיה בשליה זו, ונוהגים בה דיני האשה המפלת שליה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב יצחק: \u0003ומי\u0004 \u0005[והאם]\u0006 אכן \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב\u0004 עצמו: \u0003אין הולד\u0004 הנולד שני \u0003מתעכב\u0004 במעי אמו ל\u0003אחר\u0004 לידת \u0003חבירו\u0004 (העובר שקדם לו) \u0003כלום! אישתיק\u0004 \u0005[שתק]\u0006 רב יצחק בר שמואל, ולא השיב על שאלה זו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא לרב יצחק בר שמואל: ו\u0003דלמא\u0004 \u0005[שמא]\u0006 אין זו סתירה בין דברי רב, שכן ניתן לומר ש\u0003כאן\u0004 שאמר רב שיש שהולד השני יוצא אף לאחר שלושה ימים מלידת קודמו — הרי זה \u0003בנפל,\u0004 שלא נולד בתחילה ולד בן קיימא. ואילו \u0003כאן\u0004 שאמר רב שאין הולד השני מתעכב אחר לידת הולד שקדם לו — הרי זה \u0003ב\u0004שנולד בתחילה \u0003בן קיימא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק בר שמואל לרב כהנא: וכי \u0003את אמרת לשמעתתיה\u0004 \u0005[אתה האומר את שמועתו]\u0006 זו של \u0003רב,\u0004 ומפרשה לפי סברתך? \u0003בפירוש אמר רב הכי\u0004 \u0005[כך]:\u0006 \u0003הפילה נפל ואחר כך הפילה שליא\u0004 — \u0003כל שלשה ימים תולין את השליא בולד, מכאן ואילך\u0004 — \u0003חוששין לולד אחר.\u0004 \u0003ילדה\u0004 בן קיימא, \u0003ואחר כך הפילה שליא\u0004 — \u0003אפילו מכאן ועד עשרה ימים אין חוששין לולד אחר.\u0004","בענין זה מסופר: \u0003שמואל, ותלמידי רב, ורב יהודה הוו יתבי\u0004 \u0005[היו יושבים].\u0006 \u0003חליף ואזיל\u0004 \u0005[חלף והלך]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מנשיא מ\u0004המקום \u0003דויל לאפייהו באלי ואתי\u0004 \u0005[לקראתם\u0006 כשהוא \u0005ממהר ובא],\u0006 \u0003אמר\u0004 שמואל: הנה \u0003אתי לן גברא\u0004 \u0005[בא אלינו אדם]\u0006 \u0003דרמינן ליה בגילא דחטתא\u0004 \u0005[שרואים אותו נופל בקש החיטה,\u0006 כלומר, בדבר קל\u0005] ומרמי ומדחי\u0006 \u0005[\u0006\u0005ו\u0006הוא \u0005נופל ונדחה],\u0006 כלומר אינו יכול להשיב אף על קושיה קלה,","\u0003אדהכי אתא\u0004 \u0005[בתוך כך\u0006 הוא \u0005בא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל: מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 חידוש \u0003אמר רב ב\u0004ענין המפלת \u0003שליא? אמר ליה\u0004 \u0005[לן]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב:\u0004 הפילה האשה ולד ולאחר מכן הפילה שליה, \u0003אין תולין את השליא\u0004 בולד, \u0003אלא ב\u0004אופן שהולד הוא \u0003דבר של קיימא\u0004 (שהיה יכול לחיות אם היו מסתיימים ימי עיבורו), אבל אם לא היה הולד בר קיימא (שאם היו מסתיימים ימי הריונו של הולד לא היה חי) — יש לחשוש שמא ולד אחר היה בשליה. \u0003שיילינהו\u0004 \u0005[שאל אותם]\u0006 \u0003שמואל לכל תלמידי רב\u0004 שהיו נוכחים במקום, האם אכן כך אמר רב, \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]:\u0006 אכן \u0003הכי\u0004 \u0005[כך]\u0006 אמר רב. \u0003הדר\u0004 \u0005[החזיר\u0006 פניו\u0005] שמואל\u0006 \u0003חזייה\u0004 \u0005[התבונן]\u0006 ב\u0003רב יהודה בישות\u0004 \u0005[שלא בטובה],\u0006 שכן אף רב יהודה מתלמידי רב היה, והקפיד עליו שמואל על שלא מסר דברים אלה לשמואל רבו, לאחר פטירת רב.","ועוד בענין האשה המפלת, \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יוסי בן שאול מרבי: המפלת דמות עורב ושליא מהו\u0004 דינה, האם יש לייחס את השליה לדמות עורב זו, או שמא יש לחשוש לולד אחר שהיה בשליה זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין תולין אלא בדבר שיש במינו שליא,\u0004 וכיון שאין בעורב שליה, אין לייחס לו שליה זו.","הוסיף ר' יוסי בן שאול ושאל: היתה השליה \u0003קשורה בו\u0004 בדמות העורב \u0003מהו\u0004 דינה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דבר שאינו\u0004 בנמצא כלל \u0003שאלת.\u0004 \u0003איתיביה\u0004 \u0005[הקשה עליו]\u0006 ר' יוסי בן שאול: והרי שנינו: \u0003המפלת מין בהמה\u0004 או \u0003חיה ו\u0004כן \u0003עוף ושליא עמהן,\u0004 \u0003בזמן שהשליא קשורה עמהן\u0004 — \u0003אין חוששין לולד אחר,\u0004 ובזמן ש\u0003אין\u0004 ה\u0003שליא קשורה עמהן\u0004 — \u0003חוששין לולד אחר,\u0004 ובמקרה זה \u0003הריני מטיל עליהן\u0004"],["\u0003חומר\u0004 (חומרות) \u0003שני ולדות, ש\u0004כיון שאין השליה קשורה בהם, יש מקום לומר שהיה ולד נוסף. ומעתה מן הספק \u0003אני אומר\u0004 כי שני חששות הם: האחד, \u0003שמא\u0004 היה ולד נוסף ו\u0003נמוח\u0004 ה\u0003שפיר\u0004 (הקרום המשמש כנרתיק לעובר המתפתח) \u0003של\u0004 ה\u0003שליא\u0004 זו שלפנינו, ונמוח העובר בה. והשני, שמא היתה שליה נוספת ובה עובר, \u0003ונמוח שליא של שפיר.\u0004 ויש איפוא לחשוש שהיו שתי שליות, ובהן שני ולדות. ועוד זאת, שמא הולד האחד היה זכר והשני היה נקבה. הרי שיש איפוא מצב שכזה, שבו עוף קשור בשליה, והרי זו קושיה לרבי שאמר שאין דבר כזה מתרחש כלל. ומסכמים: אכן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה].\u0006","ועוד בענין שליה היוצאת לאחר זמן לידת ולד, \u0003אמר רבה בר שילא, אמר רב מתנה, אמר שמואל: מעשה\u0004 כגון זה היה, \u0003ותלו\u0004 (ייחסו) \u0003את השליא\u0004 הזו \u0003בולד\u0004 שנולד לפניה. וזהו דווקא אם יצאה השליה \u0003עד עשרה ימים\u0004 מאז הלידה. ומוסיף עוד שמואל בדין זה: \u0003ולא אמרו\u0004 חכמים ש\u0003תולין\u0004 את השליה בולד שכבר נולד, \u0003אלא\u0004 דווקא \u0003בשליא הבאה אחר הולד,\u0004 אבל שליה שיצאה קודם לידת הולד — אין מייחסים אותה לולד זה.","\u0003אמר רבה בר בר חנה, אמר ר'\u0004 \u0003יוחנן: מעשה\u0004 היה \u0003ותלו\u0004 חכמים \u0003את השליא\u0004 שיצאה \u0003בולד\u0004 שנולד קודם לכן, \u0003עד\u0004 שעברו \u0003עשרים ושלשה ימים\u0004 מאז הלידה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 בתיקון הדברים: \u0003עד עשרים וארבעה\u0004 מאז לידת הולד \u0003אמרת לן\u0004 \u0005[לנו]\u0006 בפעם אחרת.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של רב עוירא, אמר רב יצחק: מעשה היה וילדה אשה תאומים, \u0003ונשתהה הולד\u0004 השני מלצאת ממעי אמו \u0003אחר חבירו שלשים ושלשה יום.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 בתיקון מסורת זו: \u0003שלשים וארבעה\u0004 ימים \u0003אמרת לן\u0004 \u0005[לנו]\u0006 בפעם אחרת.","ושואלים על דברים אלה של רב יצחק: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שהאשה ה\u0003יולדת לתשעה\u0004 חודשי הריונה, יש ו\u0003יולדת\u0004 היא גם \u0003למקוטעין\u0004 (בשלב מוקדם מכך של ההריון), שכן \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 של לידת תאומים בהפרש כה רב בין לידה ללידה. שהולד ה\u0003אחד\u0004 (הראשון) \u0003נגמרה צורתו לסוף שבעה\u0004 חודשי הריון, ואז הוא נולד. \u0003ו\u0004אילו ה\u0003אחד\u0004 (הנולד אחריו) \u0003נגמרה צורתו לתחלת תשעה\u0004 חודשי הריון, ואז הוא נולד. וכך יש בין לידה זו ללידה שאחריה שלושים וארבעה ימים. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי האשה ה\u0003יולדת לתשעה אינה יולדת למקוטעין,\u0004 אלא הריהי משלימה הריון של תשעה חודשים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומתרצים: \u0003איפוך שמעתתא\u0004 \u0005[הפוך\u0006 את \u0005השמועה],\u0006 וגרוס בה כך: מנין זה של \u0003שלשים ושלשה\u0004 ימים לאחר הלידה הקודמת — הרי זה \u0003ל\u0004ענין ה\u0003שליא\u0004 שיצאה לאחר לידת הולד, ומנין זה של \u0003עשרים ושלשה\u0004 שמייחסים ללידה הקודמת — הרי זה \u0003ל\u0004ענין ה\u0003ולד\u0004 שנולד לאחר לידת ולד קודם לו.","\u0003אמר ר'\u0004 \u0003אבין בר רב אדא, אמר רב מנחם איש כפר שערים, ואמרי לה\u0004 \u0005[ויש האומרים\u0006 בגירסת \u0005אותה\u0006 שמועה\u0005]\u0006 שהיה מכפר \u0003בית שערים: מעשה\u0004 היה \u0003ונשתהה ולד אחד\u0004 מלהיוולד \u0003אחר חבירו שלשה חדשים, והרי הם\u0004 שני הילדים הללו שנולדו \u0003יושבים לפנינו בבית המדרש.\u0004 \u0003ומאן נינהו\u0004 \u0005[ומי הם]?\u0006 \u0003יהודה וחזקיה בני ר'\u0004 \u0003חייא.\u0004","ושואלים על כך: כיצד יכלה אימם של אלו להתעבר פעמיים, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין אשה מתעברת וחוזרת ומתעברת! אמר אביי:\u0004 שניהם נוצרו מהריון אחד, ובאותו הריון \u0003טיפה\u0004 זרע \u0003אחת היתה ונתחלקה לשתים,\u0004 ה\u0003אחד\u0004 מהם \u0003נגמרה צורתו בתחלת שבעה\u0004 חודשים להריון, \u0003ו\u0004ה\u0003אחד\u0004 נגמרה צורתו \u0003בסוף תשעה\u0004 חודשים להריון, וכך היה הפרש שלושה חודשים בין לידותיהם.","שנינו במשנתנו שאם היתה \u0003שליא בבית\u0004 — \u0003הבית טמא\u0004 בטומאת אהל. ובענין זה שנינו עוד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 היתה \u0003שליא בבית\u0004 — \u0003הבית טמא.\u0004 ו\u0003לא\u0004 משום \u0003שהשליא\u0004 נחשבת כ\u0003ולד, אלא\u0004 משום \u0003שאין שליא שאין ולד עמה,\u0004 ומשום אותו ולד נטמא הבית בטומאת אהל. אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 ואילו \u0003ר' יוסי ור' יהודה ור' שמעון מטהרין\u0004 את הבית שנמצאה בו שליה.","\u0003אמרו לו\u0004 חכמים אלו \u0003לר' מאיר:\u0004 וכי \u0003אי\u0004 (אין) \u0003אתה מודה שאם הוציאוהו\u0004 את השליה הזו כשהיא נתונה כולה \u0003ב\u0004כלי כגון \u0003ספל\u0004 ממקום זה \u0003לבית\u0004 (לחדר) \u0003החיצון\u0004 שבבית, \u0003שהוא\u0004 אותו חדר \u0003טהור? אמר להן: אבל\u0004 (אמנם כן). \u0003ולמה?\u0004 — \u0003לפי שאינו,\u0004 שעם הטילטול של השליה ממקומה, שוב אין בה עוד מן הולד שהיה בה, שנמק ובטל בה.","\u0003אמרו לו\u0004 חכמים אלו: אם כך, \u0003כשם שאינו\u0004 כשהוא \u0003בבית החיצון\u0004 משום שנימוק על ידי שטולטל ממקומו, \u0003כך\u0004 גם אינו כשהוא עדיין \u0003בבית הפנימי,\u0004 כיון שנימוק בטילטולו ממעי אמו למקום זה שבבית! \u0003אמר להן: אינו דומה\u0004 זה שנתון במקום זה שהרי \u0003נמוק פעם אחת\u0004 בלבד, \u0003ל\u0004זה שטולטל ממקום זה למקום אחר, ובכך \u0003נמוק שתי פעמים.\u0004","ונמסר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב פפא\u0004 בבית המדרש \u0003אחורי רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב המנונא\u0004 רבם, \u0003ויתיב וקאמר\u0004 \u0005[וישב\u0006 רב המנונא \u0005ואמר]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 במשנתנו ובברייתא כי בית שנמצאת בו שליה טהור מטומאת אהל, משום ש\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003כל טומאה שנתערב בה ממין אחר\u0004 — \u0003בטלה,\u0004 והרי נתערב הולד שנימוח בדם הלידה, ובטל בכך מלטמא.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 לרב ביבי שהיה גדול ממנו ולרב המנונא רבו: \u0003היינו נמי טעמייהו\u0004 \u0005[זהו גם כן טעמם]\u0006 של \u0003ר' יהודה ור' יוסי\u0004 המובאים בברייתא זו, שאחזו כשיטת ר' שמעון. \u0003אחיכו עליה\u0004 \u0005[חייכו,\u0006 צחקו \u0005עליו],\u0006 ואמרו: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מה חידוש בדבריך\u0005]?\u0006 והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדבר!","\u0003אמר רב פפא\u0004 בעקבות מעשה זה: \u0003אפילו כי הא מילתא\u0004 \u0005[כמו דבר זה]\u0006 שפשוט הוא — \u0003לימא איניש\u0004 \u0005[שיאמר אדם],\u0006 \u0003ולא נשתוק קמיה רביה\u0004 \u0005[ולא ישתוק לפני רבו],\u0006 אף שייתכן וילעגו על דבריו. \u0003משום שנאמר: \"אם נבלת בהתנשא ואם זמות יד לפה\"\u0004 (משלי ל, לב). שאם מתבזה אדם (\"נבלת\") על דברי תורה — סופו בא לידי גדולה, ומשמיע דבריו ברבים (\"בהתנשא\"). ואולם אם הוא עוצר בעדו מלומר דברים (\"ואם זמות\") — סופו בא לידי היאלמות, שאין בידו להשיב לשואליו (\"יד לפה\").","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' שמעון\u0004 הסבור ששליה הנמצאת בבית אינה מטמאת את הבית בטומאת אהל, משום שכל טומאה שהתערב בה ממין אחר, הרי היא בטלה, \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מלא תרוד\u0004 (כף גדולה המשמשת לרוב לבחישת המתבשל) \u0003רקב\u0004 (רקבובית המת), שהוא השיעור המטמא באהל, \u0003שנפל לתוכו עפר כל שהו\u0004 — \u0003טמא\u0004 הבית שנמצא בו רקב זה, שהרי יש בו שיעור טומאה באהל. \u0003ו\u0004אילו \u0003ר' שמעון מטהר.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ר' שמעון? אמר רבה: \u0003אשכחתינהו לרבנן דבי\u0004 \u0005[מצאתי את חכמי בית\u0006 המדרש\u0005]\u0006 של \u0003רב דיתבי וקאמרי\u0004 \u0005[שישבו והיו אומרים]\u0006 בטעם שיטתו: משום שלאחר שנפל לתוך הרקב מעט עפר, \u0003אי אפשר שלא\u0004 יהיה מצב שבו במקום מסויים בתערובת זו \u0003ירבו שתי פרידות\u0004 (גרגרי) \u0003עפר על פרידה אחת של רקב,\u0004 והתבטל איפוא אותו גרגיר של רקב, \u0003ו\u0004נמצא איפוא ש\u0003חסיר ליה\u0004 \u0005[וחסר לו]\u0006 מהשיעור של מלוא תרוד הנדרש לטמא באהל.","\u0003ואמינא להו\u0004 \u0005[ואמרתי להם]\u0006 בתשובה לדבר: \u0003אדרבה\u0004 (להיפך), יש לומר באופן הפוך, ש\u0003אי אפשר שלא ירבו שתי פרידות רקב על\u0004"],["\u0003פרידה\u0004 \u0005[גרגיר]\u0006 \u0003אחת עפר,\u0004 ומתבטלת בכך פרידת העפר ומצטרפת לשיעור הרקב, ובכך \u0003(ונפיל) ליה שיעורא\u0004 \u0005[(ויפול),\u0006 וירבה \u0005לו השיעור]\u0006 של הרקב!","\u0003אלא אמר רבה: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' שמעון,\u0004 שאנו אומרים שיהא דין \u0003סופו\u0004 של הרקב \u0003כ\u0004דין \u0003תחלתו,\u0004 כשאך החל הרקב להיעשות. ומעתה, \u0003מה\u0004 ב\u0003תחלתו\u0004 — אם התערב דבר אחר, שאינו מגוף המת עם גוף המת — \u0003נעשה לו דבר אחר\u0004 זה \u0003גנגילון\u0004 (ביטול) לרקב המת, שכן אין רקב המת מטמא אלא אם כן נעשה מן המת בלבד, \u0003אף\u0004 ב\u0003סופו\u0004 שכבר יש רקב המת, אם נתערב בו דבר אחר — \u0003נעשה לו דבר אחר\u0004 זה \u0003גנגילון.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה שנסמך עליה לימוד זה, שאין רקב המת נחשב אלא לעצמו, ובלא תערובת? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003איזהו מת שיש לו רקב\u0004 (שהרקב שלו מטמא), \u0003ואיזהו מת שאין לו רקב\u0004 (שהרקב שלו אינו מטמא)? אם \u0003נקבר\u0004 המת כשהוא \u0003ערום בארון של שיש, או על גבי רצפה של אבנים,\u0004 וכיוצא באלו שאין דבר חיצוני המגיע אליו מבעד לארון של שיש או רצפה של אבנים — \u0003זהו מת שיש לו רקב.\u0004","\u0003ואיזהו מת שאין לו רקב?\u0004 זה ש\u0003נקבר בכסותו, או בארון של עץ, או על גבי רצפה של לבנים,\u0004 שבכל אלו מתערב ברקבון הגופה דבר שאינו מגוף המת — \u0003זהו מת שאין לו רקב.\u0004 \u0003ו\u0004עוד בהגדרה ההלכתית של רקב המת: \u0003לא אמרו\u0004 חכמים שנוהג דין \u0003רקב\u0004 המת \u0003אלא למת\u0004 מעצמו \u0003בלבד,\u0004 ובא הדבר ללמדנו כי יש \u0003למעוטי\u0004 \u0005[למעט]\u0006 מכלל דין זה את ה\u0003הרוג\u0004 שיצא מקצת מדמו כשנהרג. שכיון שאין הוא מת שלם, שהרי נחסר מגופו, \u0003לא.\u0004","עתה דנים בברייתא שהובאה קודם לצורך בירור שיטת ר' שמעון, ל\u0003גופא\u0004 \u0005[גופה,\u0006 לעצמה\u0005]\u0006 ובהרחבה. שיעור \u0003מלא תרוד רקב\u0004 המת, שהוא השיעור המטמא בטומאת אוהל, \u0003שנפל לתוכו עפר כל שהוא\u0004 — טמא, ור' שמעון מטהר. \u0003מלא תרוד רקב שנתפזר בבית,\u0004 והריהו נמצא עתה במקומות שונים בבית — \u0003הבית טמא,\u0004 שהרי יש באוהל כשיעור המטמא אותו, אף שאינו במקום אחד. \u0003ו\u0004אילו \u0003ר' שמעון מטהר\u0004 אף במקרה זה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני הדינים הללו. משום \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאם השמיע לנו\u0006 שנחלקו רק בדין \u0005הראשון]\u0006 — הייתי אומר כי דווקא \u0003בההיא קאמרי רבנן\u0004 \u0005[באותו\u0006 מקרה הוא ש\u0005אמרו חכמים]\u0006 שהבית טמא — \u0003משום דמכניף\u0004 \u0005[שכנוס]\u0006 הוא רקב המת במקום אחד. \u0003אבל\u0004 אם \u0003נתפזר\u0004 רקב המת — \u0003אימא מודו\u0004 \u0005[אמור\u0006 ש\u0005מודים]\u0006 \u0003לו לר' שמעון\u0004 שאינו מטמא באהל, משום \u0003אין מאהיל וחוזר ומאהיל,\u0004 שאין הדבר המאהיל על רקב שאין בו כדי שיעור המטמא מצטרף לדבר המאהיל אף הוא על רקב שאין בו כדי שיעור.","\u0003ו\u0004כמו כן מצד שני, \u0003אי אשמעינן בהא\u0004 \u0005[אם היה משמיענו\u0006 רק \u0005בזה,\u0006 בנתפזר הרקב\u0005]\u0006 — הייתי אומר כי דווקא \u0003בהא\u0004 \u0005[בזה]\u0006 \u0003אמר ר'\u0004 \u0003שמעון\u0004 שהבית טהור, משום ש\u0003אין מאהיל וחוזר ומאהיל, אבל בהא\u0004 \u0005[בזה,\u0006 בנפילת עפר לתוך רקב\u0005]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה\u0004 ר' שמעון \u0003להו לרבנן\u0004 \u0005[להם לחכמים]\u0006 שהבית טמא, לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני המקרים.","ועוד במחלוקות ר' שמעון וחכמים בדין רקב המת, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 משנה \u0005אחרת\u0006 במסכת אהלות\u0005]:\u0006 היה בבית שיעור \u0003מלא תרוד ועוד\u0004 של \u0003עפר בית הקברות\u0004 — הרי הבית \u0003טמא\u0004 באוהל, \u0003ור' שמעון מטהר.\u0004 ומבררים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים\u0006 המטמאים\u0005]?\u0006 \u0003לפי שאי אפשר למלא תרוד ועוד עפר בית הקברות שאין בו\u0004 כדי שיעור \u0003מלא תרוד רקב,\u0004 והרי יש בו איפוא כשיעור רקב המטמא באוהל.","ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת\u0004 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' שמעון\u0004 המטהר את הבית מטומאת אוהל ברקב המת שהתערב בו עפר \u0003משום סופו כתחלתו,\u0004 אם כן \u0003גבי\u0004 \u0005[אצל,\u0006 בדין\u0005]\u0006 \u0003שליא\u0004 הנמצאת בבית שר' שמעון מטהר בה משום טומאת אהל, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר ר'\u0004 \u0003יוחנן: משום בטול ברוב נגעו בה,\u0004 שכן הולד שנימוח בתוך השליה בטל בדמי הלידה המרובים.","ומסבירים את שיטת ר' יוחנן: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו, לשיטתו],\u0006 שכך \u0003אמר ר'\u0004 \u0003יוחנן: ר'\u0004 \u0003שמעון ור' אליעזר בן יעקב אמרו דבר אחד.\u0004 ומפרט: \u0003ר' שמעון\u0004 — \u0003הא דאמרן\u0004 \u0005[\u0006כהסבר \u0005זה שאמרנו]\u0006 שבטל מיחוי הולד בדם הלידה המרובה ממנו, ואילו \u0003ר' אליעזר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 משנה במסכת בכורות\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: בהמה גסה\u0004 כגון פרה, שלא ילדה עד כה ולד, \u0003ששפעה\u0004 (שהפילה) \u0003חררת\u0004 (חתיכת) \u0003דם\u0004 — \u0003הרי זו\u0004 החתיכה \u0003תקבר,\u0004 שנוהגים בה כבקדושת בכור, \u0003ופטורה\u0004 בהמה זו \u0003מן הבכורה\u0004 בולד הבא שיוולד לה.","\u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003ר' חייא עלה\u0004 \u0005[עליה,\u0006 על משנה זו\u0005]:\u0006 חתיכת דם זו \u0003אינה מטמאה לא במגע ולא במשא,\u0004 שאין אנו חוששים שהיה בחתיכה זו ולד המטמא באלו. ודנים בדברי ר' חייא: \u0003ו\u0004כי \u0003מאחר ש\u0004חתיכת דם זו \u0003אינה מטמאה לא במגע ולא במשא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003תקבר?\u0004 ומשיבים: אף שאין בה באמת קדושת בכורה, עושים כן \u0003כדי לפרסמה שהיא פטורה מן הבכורה\u0004 בולד הבא שיוולד לה.","ושואלים על תירוץ זה: אם אכן חתיכת דם זו פוטרת מן הבכורה, \u0003אלמא\u0004 \u0005[נסיק מכאן]\u0006 כי \u0003ולד מעליא\u0004 \u0005[מעולה,\u0006 שלם\u0005]\u0006 \u0003הוא, ו\u0004אם כן \u0003אמאי תני\u0004 \u0005[מדוע שנה]\u0006 \u0003ר' חייא\u0004 ש\u0003אינה מטמאה לא במגע ולא במשא? אמר ר'\u0004 \u0003יוחנן\u0004 בתשובה: זה שאין החתיכה מטמאה באלו, אינו משום שאינה ולד, אלא שמיחוי ולד זה התערב בדם החתיכה, ו\u0003משום בטול ברוב נגעו בה.\u0004","ודנים עוד בשיטת ר' שמעון המטהר מטומאת האוהל את הבית שנמצאת בו שליה, \u0003אמר ר'\u0004 \u0003אמי\u0004 שכך \u0003אמר ר'\u0004 \u0003יוחנן: ומודה ר'\u0004 \u0003שמעון שאמו טמאה לידה.\u0004","\u0003אמר ההוא סבא\u0004 \u0005[זקן,\u0006 חכם \u0005אחד]\u0006 \u0003לר' אמי: אסברא\u0004 \u0005[אסביר]\u0006 \u0003לך\u0004 את \u0003טעמא\u0004 \u0005[טעם]\u0006 דבריו אלה של \u0003ר' יוחנן,\u0004 שכן \u0003אמר קרא\u0004 בדין טומאת לידה: \u0003\"אשה כי תזריע וילדה זכר\u0004 וטמאה שבעת ימים כימי נדת דוותה תטמא\" (ויקרא יב, ב) — \u0003אפילו לא ילדה אלא כעין שהזריעה,\u0004 שהיה הולד שנמחה כזרע בלבד — \u0003טמאה לידה.\u0004","ועוד בדין הולד הנימוח לענין טומאת אוהל, \u0003ריש לקיש אמר:\u0004 ה\u0003שפיר\u0004 (העובר) הנתון במי השפיר \u0003שטרפוהו\u0004 (שטלטלוהו בחוזקה ומחוהו) \u0003במימיו\u0004 (שנמחקה) \u0003צורתו,\u0004 והרי הוא כמי שאינו קיים עוד, ואינו מטמא באוהל. \u0003אמר\u0004","\u0003ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש:\u0004 ו\u0003מת שנתבלבלה צורתו מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא \u0003טהור? אילימא\u0004 \u0005[אם תאמר]\u0006 שנלמד הדבר \u0003מהא\u0004 \u0005[מ\u0006דבר \u0005זה]\u0006 ש\u0003אמר ר'\u0004 \u0003שבתאי\u0004 שכך \u0003אמר ר'\u0004 \u0003יצחק מגדלאה, ואמרי לה\u0004 \u0005[ויש האומרים אותה]\u0006 ש\u0003אמר\u0004 זאת ר' \u0003יצחק מגדלאה\u0004 שכך \u0003אמר ר'\u0004 \u0003שבתאי: מת שנשרף ושלדו קיימת\u0004 — \u0003טמא.\u0004 ו\u0003מעשה\u0004 שכזה \u0003היה, וטמאו לו\u0004 (מחמתו) את הנמצא תחת ה\u0003פתחים\u0004 ה\u0003גדולים\u0004 בבית שהיה בו מת זה, שכן ראויים הם להוציא דרכם את המת אל מחוץ לבית."],["\u0003וטהרו לו\u0004 שאין מטמאים ה\u0003פתחים\u0004 ה\u0003קטנים\u0004 מארבעה טפחים. \u0003וקא\u0004 \u0005[והרי]\u0006 \u0003דייקת מינה\u0004 \u0005[ממנה]:\u0006 \u0003טעמא\u0004 \u0005[הטעם דווקא]\u0006 שמטמאים את הפתחים הגדולים הוא משום שאותו מת שנשרף \u0003שלדו קיימת, הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא כך]\u0006 הוא, שאין השלד קיים (\"התבלבלה צורתו\") — \u0003טהור.\u0004","ויש לדחות: \u0003אדרבה\u0004 (להיפך), \u0003דוק מינה להאי גיסא\u0004 \u0005[דייק ממנה לצד זה]:\u0006 דווקא במקרה זה של המת שנשרף, משום ש\u0003שלדו קיימת\u0004 — \u0003הוא\u0004 ש\u0003טהרו לו פתחים קטנים,\u0004 שאין ראוי להוציא את המת הזה אלא דרך הפתחים הגדולים, ומכאן נסיק: \u0003הא לאו הכי\u0004 \u0005[הרי,\u0006 אם \u0005לא כך]\u0006 הוא, שאף השלד אינו קיים — \u0003פתחים קטנים נמי\u0004 \u0005[גם כן]\u0006 \u0003טמאין,\u0004 משום ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מהפתחים הללו הריהו \u0003חזי לאפוקי חד חד\u0004 \u0005[ראוי להוציא\u0006 דרכו \u0005אחד אחד]\u0006 \u0003אבר,\u0004 ואין איפוא מכאן ראיה לשיטת ריש לקיש!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ר'\u0004 \u0003יוחנן\u0004 ש\u0003אמר\u0004 כי המת שהתבלבלה צורתו מטמא באוהל. \u0003כ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 מן התנאים אמר את שיטתו זו — \u0003כ\u0004שיטת ר' אליעזר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת אהלות\u0005],\u0006 \u0003אפר\u0004 אנשים \u0003שרופין,\u0004 שאין בו אלא מגופות האנשים, בלא שהתערב בהם אפרם של עצים, מהו שיעורו לענין שיטמא באהל? \u0003ר' אליעזר אומר: שיעוריה\u0004 \u0005[שיעורו]\u0006 לטמא באהל הוא \u0003ברובע\u0004 הקב. הרי שסובר ר' אליעזר שאף המת שהתבלבלה צורתו (כגון אפר הנשרפים) מטמא באוהל, וכמותו סובר ר' יוחנן.","ומבררים את דברי המשנה הללו: \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]\u0006 מצב זה של \u0003מת שנשרף ושלדו קיימת? אמר אביי: כגון ששרפו על גבי קטבלא\u0004 (עור מעובד וקשה, שאינו נשרף עם המת שעליו), שאף אם נשרף המת עליו צורתו וחיתוך איבריו ניכרים, \u0003רבא אמר: כגון ששרפו על גבי אפודרים\u0004 (אבן שיש). \u0003רבינא אמר: כגון\u0004 שלא נשרף ממש, אלא \u0003דאיחרכי אחרוכי\u0004 \u0005[שנחרך]\u0006 המת, ולא נעשה אפר ממש, והשלד נשאר קיים.","ועוד בענין דין המפלת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]: המעוברת\u0006 \u0003המפלת\u0004 צורת \u0003יד חתוכה\u0004 (שאצבעותיה חתוכות, מופרדות וניכרות) \u0003ו\u0004כן אם הפילה \u0003רגל חתוכה\u0004 — \u0003אמו טמאה לידה\u0004 ככל היולדת עובר שנגמרה צורתו. \u0003ואין חוששין שמא מגוף אטום\u0004 (שלא נגמרה צורתו, שאין בו חלוקת איברים) \u0003באו\u0004 חתיכות אלה, והאשה טהורה. משום שרוב הנשים יולדות עובר שנגמרה צורתו, ואף במקרה זה יש לומר שבאה היד או הרגל החתוכה מולד שהיה שלם, ונמחה בלידה.","ובדינה של זו \u0003רב חסדא ורבה בר רב הונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 אף שיושבת היא ימי טומאה, כשאר יולדות, \u0003אין נותנין לה ימי טוהר\u0004 כשאר יולדות, שאם ראתה בהם דם הריהי טהורה. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — אף שמניחים אנו כי באו החתיכות הללו מולד שהיה שלם, ואולם מאחר שאין אנו יודעים אם הפילה איברים נוספים מאותו ולד, ומתי הפילתם. וכלל הוא שאין ימי הטומאה והטהרה הניתנים ליולדת מתחילים אלא לאחר שהפילה רוב איבריו של העובר, משום כך \u0003אימא\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 כי \u0003הרחיקה לידתה\u0004 שכבר מזמן מרובה הסתיימה לידתה זו שהפילה רוב איברי העובר, וכבר הסתיימו להם ימי הטהרה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 מן המשנה להלן: \u0003המפלת ואין ידוע מה הפילה\u0004 — \u0003תשב\u0004 ימי טומאה וימי טהרה כמו \u0003ל\u0004יולדת \u0003זכר ולנקבה.\u0004 \u0003ואי סלקא דעתך,\u0004 \u0005[ואם עולה בדעתך]\u0006 לומר שב\u0003כל\u0004 מקרה \u0003כהאי גוונא אימא\u0004 \u0005[כעין זה\u0006 יש \u0005לומר]: הרחיקה לידתה\u0006 — \u0003לתני\u0004 \u0005[שישנה]\u0006 התנא במשנה זו מלבד שמחמירים בה ויושבת מן הספק ימי טומאה כיולדת נקבה (שבועיים) וימי טהרה כיולדת זכר (שלושים ושלושה ימים בלבד), \u0003ו\u0004גם שמחמירים בה כאילו לא ילדה כלל ויהא דינה אם רואה דם בימי טהרה אלה ככל \u0003נדה,\u0004 שהרי אפשר שילדה מזמן, וכבר הסתיימו ימי טהרה. \u0003אמר\u0004","\u0003אביי\u0004 בתשובה: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 גם שמחמירים בה \u0003לנדה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכיון שמחמירים בה כנדה מן הספק, הרי זה איפוא משום שחוששים שמא לא ילדה כלל. ואם כן אף שהיא אכן \u0003מביאה\u0004 מן הספק הזה \u0003קרבן\u0004 ככל יולדת, \u0003ו\u0004אולם יהא דינו של קרבן זה מן הספק ש\u0003אינו נאכל\u0004 שמא לא ילדה כלל ואינה חייבת בו. והרי חטאת העוף הבאה לקרבן יולדת נמלקת היא, ואם אין זה קרבן של חיוב, הרי זו נבילה האסורה באכילה. לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 בכך ששמט מלהזכיר שמחמירים בה כנדה, שמביאה קרבן יולדת ודאי, שוודאי ילדה ולד, וקרבן זה דינו ש\u0003נאכל.\u0004","\u0003אמר רב הונא: הוציא\u0004 ה\u0003עובר את ידו\u0004 ממעי אמו, ושב \u0003והחזירה\u0004 — הוצאת יד זו נחשבת כלידה, ו\u0003אמו טמאה\u0004 בה טומאת \u0003לידה\u0004 כיולדת ולד שלם. וטעמו של דבר, \u0003ש\u0004כן \u0003נאמר\u0004 בתמר אשת יהודה: \u0003\"ויהי בלדתה ויתן יד\"\u0004 (בראשית לח, כח).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יהודה\u0004 ממה ששנינו: \u0003הוציא\u0004 ה\u0003עובר את ידו\u0004 ממעי אמו — \u0003אין אמו חוששת\u0004 בשל כך לנהוג כיולדת \u0003לכל דבר!\u0004 \u0003אמר רב נחמן\u0004 כהסבר לדברי רב הונא אלה: \u0003לדידי מיפרשא לי מיניה\u0004 \u0005[לי עצמי מתפרש לי ממנו,\u0006 מדברי\u0005]\u0006 \u0003רב הונא,\u0004 שזו כוונת דבריו: \u0003לחוש\u0004 לנהוג כיולדת לענין ימי טומאה — אמנם \u0003חוששת,\u0004 ואולם אף לתת לה \u0003ימי טוהר\u0004 שתנהג כיולדת על סמך הוצאה זו — \u0003לא יהבינן לה\u0004 \u0005[אין אנו נותנים]\u0006 \u0003לה\u0004 \u0003עד דנפיק רוביה\u0004 \u0005[שיצא רובו]\u0006 של הולד ממעי אמו.","ושואלים על הסבר זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"אין אמו חוששת לכל דבר\" קאמר\u0004 \u0005[\u0006רב הונא \u0005אמר],\u0006 ומשמע שאף לענין ימי טומאה אמר כן! \u0003אמר אביי\u0004 הסבר זה בדברי רב הונא: אשה זו אמנם \u0003אינה חוששת לכל דבר\u0004 — \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אבל מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 — הריהי \u0003חוששת.\u0004 ושואלים על כך: \u0003והא קרא קאמר\u0004 \u0005[והרי מקרא הוא\u0006 רב הונא \u0005אמר]\u0006 להביא ראיה לשיטתו שנחשבת זו ללידה! ומתרצים: \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 הוא, \u0003וקרא\u0004 \u0005[והמקרא]\u0006 — \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד]\u0006 הוא.","האשה \u0003המפלת\u0004 או היולדת \u0003טומטום\u0004 (שאין נראים בו סימני מין, של זכר או של נקבה) \u0003ו\u0004כן המפלת \u0003אנדרוגינוס\u0004 (שמצויים בו סימני מין של זכר ושל נקבה), כיצד תנהג בדין ימי טומאה וטהרה? — הריהי מחמירה לנהוג בעצמה הן כיולדת זכר והן כיולדת נקיבה, ו\u0003תשב\u0004 ימי טהרה כמו \u0003ל\u0004יולדת \u0003זכר,\u0004 שלושים ושלושה ימים בלבד, \u0003ו\u0004אולם \u0003ל\u0004ענין ימי טומאה תשב כיולדת \u0003נקבה,\u0004 שבועיים.","וכמו כן האשה היולדת תאומים, הולד האחד \u0003טומטום\u0004 (שאין מינו ברור) \u0003ו\u0004הולד השני \u0003זכר\u0004 ודאי, וכן אם ילדה ולד אחד שהוא \u0003אנדרוגינוס ו\u0004ולד שני שהוא \u0003זכר\u0004 ודאי — תחמיר ו\u0003תשב\u0004 ימי טומאה וימי טהרה כמו \u0003ל\u0004יולדת \u0003זכר ולנקבה.\u0004 אבל אם ילדה האשה תאומים שהאחד מהם הוא \u0003טומטום ו\u0004השני הוא \u0003נקבה,\u0004 וכן אם ילדה תאומים שהאחד הוא \u0003אנדרוגינוס ו\u0004השני הוא \u0003נקבה\u0004 — \u0003תשב נקבה בלבד,\u0004 שהרי אף אם הטומטום והאנדרוגינוס הינם זכרים, נכללים שבעת ימי טומאתם בתוך ארבעה עשר ימי טומאה שנוהגת בהם כיולדת נקבה, ושלושים ושלושת ימי טהרתם נכללים בתוך ששים וששה ימי הטהרה הנוהגים ביולדת נקבה.","\u0003יצא\u0004 הוולד מן הרחם \u0003מחותך\u0004 (בשלבים), לא שלם אלא איבר אחר איבר, \u0003או\u0004 שיצא כשהוא שלם אבל \u0003מסורס\u0004 (הפוך), לא דרך ראשו אלא דרך רגליו. משיצא רובו — \u0003הרי הוא\u0004 נחשב \u0003כילוד\u0004 לענין טומאת לידה. ואם הולד \u0003יצא כדרכו\u0004 של ולד רגיל, דרך ראשו — אינו נחשב כילוד \u0003עד שיצא רוב ראשו.\u0004 \u0003ואיזהו\u0004 (ומהו) \u0003רוב ראשו?\u0004 — \u0003משיצא פדחתו\u0004 (מצחו).","שנינו במשנתנו שאם הפילה האשה טומטום או אנדרוגינוס הריהי נוהגת לחומרא, כיולדת כזכר לענין ימי טהרה וכיולדת נקבה לענין ימי טומאה. וכן הדין ביולדת תאומים כשאחד מהם הוא טומטום או אנדרוגינוס. ושואלים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 בענין היולדת \u0003טומטום לחודיה\u0004 \u0005[לבד]\u0006 \u0003ו\u0004כן היולדת \u0003אנדרוגינוס לחודיה\u0004 \u0005[לבד]\u0006 \u0003אמר\u0004 התנא במשנתנו ש\u0003תשב לזכר ולנקבה,\u0004 הדין גם ביולדת תאומים שאחד מהם הוא \u0003טומטום ו\u0004האחר \u0003זכר,\u0004 או ביולדת תאומים שהאחד מהם הוא \u0003אנדרוגינוס ו\u0004האחר \u0003זכר מיבעיא\u0004 \u0005[נצרך]\u0006 לומר?","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 לומר זאת, משום ש\u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 היה מקום לומר כך: \u0003הואיל ואמר ר'\u0004 \u0003יצחק:\u0004 אם בשעת הזיווג ה\u0003אשה מזרעת תחלה\u0004 — \u0003יולדת זכר,\u0004 ואם ה\u0003איש\u0004 \u0003מזריע תחלה\u0004 — \u0003יולדת נקבה,\u0004 ומעתה \u0003אימא\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 ביולדת תאומים שאחד מהם טומטום (או אנדרוגינוס) והשני זכר: \u0003מ\u0004תוך \u0003דהאי\u0004 \u0005[שזה]\u0006 הוא \u0003זכר\u0004 הרי הוכחה שהאשה היא שהזריעה תחילה, ואם כן יש מקום לומר ש\u0003האי נמי\u0004 \u0005[זה\u0006 הולד הנוסף, הטומטום, הוא \u0005גם כן]\u0006 \u0003זכר,\u0004 ותנהג איפוא האשה כדין יולדת זכר, לכן \u0003קא משמע לן\u0004 \u0005[הוא\u0006 תנא חוזר ו\u0005משמיע לנו]\u0006 שאין אנו אומרים כן, אלא \u0003אימא\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 ש\u0003שניהם,\u0004 הבעל והאשה, \u0003הזריעו בבת אחת, זו\u0004 האשה שהזריעה גרמה לכך שיוולד הולד שמינו \u0003זכר, וזה\u0004 הבעל שהזריע גרם לכך שיוולד הטומטום שמינו הוא \u0003נקבה,\u0004 ולכן נוהגת האשה במקרה זה כיולדת זכר ונקבה.","ועוד בדיני הטומטום והאנדרוגינוס. \u0003אמר רב נחמן אמר רב:\u0004 ה\u0003טומטום ו\u0004ה\u0003אנדרוגינוס\u0004 שספק הוא מה מינם, אם זכר או נקבה, \u0003שראו\u0004 זיבה שצבעה \u0003לובן\u0004 הדומה לקרי, שהאיש נטמא בה, \u0003או\u0004 שראו זיבה שצבעה \u0003אודם\u0004 כדם נדות, שהאשה נטמאת בה, אם נכנסו למקדש — \u0003אין חייבין על\u0004 כך להביא קרבן (אם נכנסו בשוגג) או מלקות (אם התרו בהם ונכנסו במזיד) משום איסור \u0003ביאת מקדש\u0004 בטומאה, שהרי יתכן שלפי מינם טהורים הם. \u0003ו\u0004כן אם נגעו בתרומה — \u0003אין שורפין עליהם את התרומה\u0004 כדין כל תרומה שנטמאה, שהרי ספק הוא.","ואם הטומטום או האנדרוגינוס \u0003ראו לובן ואודם כאחד\u0004 — \u0003אין חייבין על ביאת מקדש, אבל שורפין עליהם את התרומה,\u0004 שהרי ודאי טמאים הם משום אחד מהמראות. וטעם הדבר שאין חייבים על ביאת מקדש, אף שבודאי טמאים הם, משום \u0003שנאמר\u0004 במצוה זו: \u0003\"מזכר ועד נקבה\u0004"],["\u0003תשלחו\u0004 אל מחוץ למחנה תשלחום ולא יטמאו את מחניהם אשר אני שוכן בתוכם\" (במדבר ה, ג), ומן הפירוט \"מזכר ועד נקבה\" למדים אנו שנוהג דין שילוח הטמאים מן המקדש דווקא במי שהוא \u0003זכר ודאי,\u0004 ובמי שהיא \u0003נקבה ודאית, ולא\u0004 במי שאינו כן, כגון \u0003טומטום ואנדרוגינוס.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 לדברי רב אלו ממה ששנינו בברייתא: \u0003טומטום ואנדרוגינוס שראו\u0004 זיבה שמ ראה \u0003לובן או\u0004 שמראה \u0003אודם\u0004 ונכנסו למקדש קודם שנטהרו או אכלו קדשים — \u0003אין חייבין על ביאת מקדש\u0004 ולא על אכילת קדשים, \u0003ואין שורפין עליהם את התרומה\u0004 אם נגעו בה. ואולם אם \u0003ראו\u0004 זיבה שמראה \u0003לובן ואודם כאחת\u0004 — אף ש\u0003אין חייבין על ביאת מקדש, אבל שורפין עליהם את התרומה,\u0004 שהרי הם בודאי טמאים, בין אם הם זכר בין אם נקבה.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של הלכה זו שבברייתא שאין חייבים על ביאת מקדש, אף שבודאי טמאים הם? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום שנאמר \"מזכר ועד נקבה תשלחו\"\u0004 — דווקא ב\u0003זכר ודאי,\u0004 ו\u0003נקבה ודאית, ולא\u0004 ב\u0003טומטום ואנדרוגינוס,\u0004 והרי זה כשיטת רב. \u0003אמר עולא: לא,\u0004 אין מכאן סיוע לשיטת רב, שכן \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' אליעזר היא,\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת שבועות\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר בענין החייבים קרבן עולה ויורד: \"או נפש אשר תגע בכל דבר טמא... או בנבלת \u0003שרץ\u0004 טמא \u0003ונעלם ממנו\"\u0004 (ויקרא ה, ב) ויש לדייק: \u0003על העלם\u0004 ידיעה לאחר שנגע ב\u0003שרץ\u0004 ונטמא וידע שנטמא, ובעת שנכנס למקדש נשכח ממנו הדבר \u0003הוא חייב\u0004 קרבן עולה ויורד בטומאת מקדש וקדשיו, \u0003ואינו חייב\u0004 קרבן \u0003על העלם מקדש\u0004 שעמד להכנס למקדש מתוך ידיעה שזה מקדש, וכשנכנס נעלם ממנו שזה מקדש וכשיצא נזכר.","ובדומה לכך \u0003ר' עקיבא אומר:\u0004 נאמר \u0003\"ונעלם ממנו והוא טמא\"\u0004 (שם) — להדגיש: \u0003על העלם טומאה הוא חייב\u0004 קרבן, \u0003ואינו חייב על העלם מקדש.\u0004","\u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 בבירור שיטות אלה: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם],\u0006 שהרי שניהם מסכימים להלכה אחת? \u0003ואמר חזקיה:\u0004 כשהיו לפניו \u0003שרץ ונבלה\u0004 ונגע באחד מהם ואינו יודע במי \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. ובכך נחלקו, ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 שכדי לחייבו בקרבן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003עד\u0004 ש\u0003ידע\u0004 תחילה בבירור \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבילה איטמי\u0004 \u0005[נטמא],\u0006 ואם אינו יודע — אינו מביא קרבן זה. \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 שכיון שידע שנטמא \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שידע בדיוק באיזו טומאה נטמא.","ומכאן נסיק, \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003אמר ר'\u0004 \u0003אליעזר התם\u0004 \u0005[שם]\u0006 בענין ידיעת טומאה כי כדי לחייבו קרבן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 ש\u0003ידע אי\u0004 \u0005[אם]\u0006 \u0003בשרץ איטמי\u0004 \u0005[נטמא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בנבלה איטמי\u0004 \u0005[נטמא],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין חיוב קרבן כשרואה הטומטום או האנדרוגינוס זיבה \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 ש\u0003ידע אי\u0004 \u0005[אם]\u0006 \u0003בלובן איטמי\u0004 \u0005[נטמא],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003באודם איטמי\u0004 \u0005[נטמא].\u0006 ולכן אינו חייב אף בראיית לובן ואודם כאחת, לשיטת ר' אליעזר.","\u0003אבל ל\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר\u0004 ש\u0003משום\u0004 ידיעת ה\u0003טומאה\u0004 כשלעצמה \u0003מיחייב\u0004 \u0005[מתחייב],\u0006 אף שאינו יודע בדיוק איזו טומאה היא זו, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לעניין ראיית לובן ואודם כאחת, \u0003משום טומאה מיחייב\u0004 \u0005[מתחייב],\u0006 אף שאינו יודע אם משום טומאת נקיבה או משום טומאת זכר.","ושואלים: \u0003ו\u0004לשיטת \u0003רב\u0004 שאינו חייב קרבן על ביאת מקדש ואכילת קדשים בראיית אודם ולובן, ואולם שורפים את התרומה שנגע בה, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003ביאת מקדש\u0004 ש\u0003לא\u0004 מתחייב בה קרבן — משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מזכר ועד נקבה תשלחו\"\u0004 — \u0003זכר ודאי, נקבה ודאית, ולא טומטום ואנדרוגינוס.\u0004","\u0003אי הכי\u0004 \u0005[אם כך],\u0006 את ה\u0003תרומה\u0004 שנגע בה \u0003נמי\u0004 \u0005[גם כן]\u0006 ש\u0003לא נשרוף\u0004 אף לדעתו, שכך נדרוש לענין מגע תרומה של טומטום ואנדרוגינוס באופן דומה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין הטמאים: \"זאת תורת הזב ואשר תצא ממנו שכבת זרע לטמאה בה. והדוה בנדתה \u0003והזב את זובו לזכר ולנקבה\"\u0004 (ויקרא טו, לב—לג) והרי פירוט זה בא ללמד שאין דינים אלה נוהגים אלא במי שהוא \u0003זכר ודאי,\u0004 ובמי שהיא \u0003נקבה ודאית, ולא\u0004 במי שהוא \u0003טומטום\u0004 או אנדרוגינוס!","ומשיבים: המקרא \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004לימוד אחר, ו\u0003כ\u0004דרשתו של \u0003ר' יצחק,\u0004 שכן \u0003אמר ר'\u0004 \u0003יצחק:\u0004 הכתוב \u0003\"לזכר\"\u0004 — בא \u0003לרבות את המצורע\u0004 שהריהו מטמא באב הטומאה אדם וכלים אף \u0003למעינותיו\u0004 (מקורות נוזלים שבו, כרוקו ומי רגליו). וכן הכתוב \u0003\"ולנקבה\"\u0004 — בא \u0003לרבות את המצורעת למעינותיה.\u0004","\u0003ושואלים:\u0004 \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 שבפרשת טומאת מקדש וקדשיו \"מזכר עד נקבה תשלחו\" שדרש בו רב שאין חייבים על כך אלא זכר ודאי ונקבה ודאית ולא טומטום ואנדרוגינוס, \u0003נמי מבעי ליה\u0004 \u0005[גם כן נצרך לו]\u0006 לדרשה אחרת, והיא: שאין דין שילוח טמאים מן המקדש נוהג אלא \u0003במי שיש לו טהרה במקוה, פרט לכלי חרס\u0004 שנטמא שאין לו טהרה במקוה, אלו \u0003דברי ר'\u0004 \u0003יוסי,\u0004 ואין מקום לדרשתו של רב מאותו כתוב!","ומשיבים: \u0003אם כן\u0004 שהכתוב בא להשמיענו רק דרשת ר' יוסי, \u0003נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003\"אדם\u0004 תשלחו\", שדי בו כדי ללמדנו שאין כלי חרס בכלל שילוח. ומתוך שהרחיבה ואמרה \"מזכר עד נקבה\" הרי זה בא ללמדנו אף את דינו של רב.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 לדחות זאת: \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 בלשון \u0003\"אדם\u0004 תשלחו\" \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאף \u0003כלי מתכות\u0004 שנטמאו \u0003לא\u0004 משולחים מן המקדש, שהרי לא אמר הכתוב דין זה אלא באדם, יש להשיב על כך: אף אם היה נאמר בכתוב \"אדם תשלחו\" לא הייתי ממעט כלי מתכות מדין שילוח, משום שדינם לענין זה \u0003מ\u0004הכתוב בפסוק הקודם בפרשה זו: \"וישלחו מן המחנה כל צרוע וכל זב ו\u0003כל טמא לנפש\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 ואם כן פירוט זה האמור בפסוק הבא \u0003\"זכר\" ו\"\u0004 \u0003נקבה\" למה לי,\u0004 שהרי יכול היה הכתוב לומר בכללות \"אדם\" — הרי זה בא \u0003ל\u0004השמיענו \u0003כ\u0004דרשתו של \u0003רב,\u0004 שאין טומטום ואנדרוגינוס בכלל זה.","\u0003ו\u0004שואלים מעתה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003כוליה\u0004 \u0005[כל]\u0006 הכתוב רק \u0003ל\u0004השמיענו \u0003כ\u0004דרשתו של \u0003רב הוא דאתא\u0004 \u0005[שבא],\u0006 ואין מקום לדרשתו של ר' יוסי! ומשיבים: אילו הכתוב בא רק לדרשתו של רב, \u0003אם כן, נכתוב\u0004 \u0005[תכתוב]\u0006 התורה \u0003\"זכר נקבה\u0004 תשלחו\", \u0003מאי\u0004 \u0005[מה]\u0006 מלמדנו הכתוב \u0003\"מזכר ועד נקבה\"\u0004 — התוספת \u0003\"עד\"\u0004 באה ללמדנו ש\u0003כל דבר\u0004 טמא מזכר ועד נקבה, כל \u0003שיש לו טהרה במקוה,\u0004 הרי הוא בכלל מצות שילוח.","ודנים בעיקר דינו של רב: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין הטומטום והאנדרוגינוס בכלל המשולחים מהמקדש בטומאתם, ואין הם חייבים קרבן על כניסה למקדש בטומאה, \u0003כי איטמי\u0004 \u0005[כאשר נטמאו]\u0006 הטומטום והאנדרוגינוס לא רק בזיבה, אלא אף \u0003בשאר טומאות,\u0004 וכגון בטומאת שרץ או בטומאת מת, שגם אז \u0003לא לישלחו\u0004 \u0005[לא ישולחו]\u0006 מהמקדש, ולא יתחייבו קרבן על כניסה בטומאתם למקדש. שהרי בפרשה זו ממנה למד רב את דינו, נזכרו טומאות שונות, כאמור: \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש. מזכר ועד נקבה תשלחו אל מחוץ למחנה! ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפירוט \u0003\"מזכר\"\u0004 — ללמדנו שאין הדברים אמורים אלא \u0003מטומאה הפורשת מן הזכר,\u0004 שהיא הזיבה.","ושואלים עוד על דרשתו של רב: \u0003וכל היכא דכתיב\u0004 \u0005[מקום שנאמר]\u0006 \u0003\"מזכר עד נקבה\" למעוטי\u0004 \u0005[למעט]\u0006 \u0003טומטום ואנדרוגינוס הוא דאתא\u0004 \u0005[שבא]\u0006 \u0003והא גבי\u0004 \u0005[והרי אצל]\u0006 פרשת \u0003ערכין, דכתיב\u0004 \u0005[שנאמר]\u0006 \"והיה ערכך \u0003\"הזכר...\u0004 חמשים שקל בשקל הקודש.","ואם נקבה היא והיה ערכך שלשים שקל\" (ויקרא כז, ג—ד), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"הזכר\"\u0004 — \u0003ולא טומטום ואנדרוגינוס.\u0004 \u0003יכול לא יהא\u0004 הטומטום והאנדרוגינוס \u0003בערך איש\u0004 שהוא חמישים שקל, \u0003אבל יהא בערך אשה\u0004 שהוא שלושים שקל? \u0003תלמוד לומר: \"הזכר...\u0004 \u0003ואם נקבה\"\u0004 — דינים אלו אמורים דווקא במי שהוא \u0003זכר ודאי,\u0004 ובמי שהיא \u0003נקבה ודאית, ולא\u0004 ב\u0003טומטום ו\u0004ב\u0003אנדרוגינוס.\u0004","ויש לדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 למעט טומטום ואנדרוגינוס הוא משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשה זו \u0003\"הזכר...\u0004 \u0003ואם נקבה\",\u0004 שלכל אחת מהמלים הללו תוספת הבאה ללמד (שנאמר \"הזכר\" ולא \"זכר\" בלבד, וכן \"ואם נקבה\" ולא \"נקבה\" בלבד), \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003מ\u0004המלים \u0003\"זכר\" ו\u0004כן \u0003\"נקבה\"\u0004 כשלעצמן — הכתוב \u0003לא ממעט!\u0004 ומשיבים: אין לדייק כן מדרשה זו שבפרשת ערכין, משום שדי ב\"זכר\" ו\"נקבה\" כשלעצמן ללמדנו שאין טומטום ואנדרוגינוס בכלל, אלא שבפרשת ערכין אין למדים מהן כשלעצמן משום שהכתוב \u0003ההוא מבעי ליה\u0004 \u0005[נצרך לו]\u0006 לעצם דין הערכין,"],["שיש \u0003לחלק בין ערך איש לערך אשה.\u0004","שנינו במשנתנו שאם \u0003יצא\u0004 הולד מרחם אמו כשהוא \u0003מחותך\u0004 (איברים איברים) \u0003או\u0004 שהוא שלם אבל \u0003מסורס\u0004 (הפוך, שיצא דרך רגליו ולא דרך ראשו) דינו הוא שמשעה שיצא רובו הריהו נחשב לענין טומאת לידה כילוד. ובהגדרת \"רובו\" של היוצא מחותך, נחלקו חכמים. שכן \u0003אמר ר'\u0004 \u0003אלעזר: אפילו\u0004 אם יצא \u0003הראש עמהן\u0004 עם שאר האיברים, ולא יצא עדיין רובו — אינו נחשב כילוד.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר: לא שנו\u0004 במשנתנו שהולד נחשב כילוד רק אם יצא רובו \u0003אלא\u0004 בזמן \u0003שאין הראש עמהן\u0004 עם האיברים שיצאו, \u0003אבל\u0004 אם יצא \u0003הראש עמהן\u0004 — \u0003הראש פוטר\u0004 (לענין בכורה), והריהו נחשב כילוד, אף שלא יצאו עדיין רוב איבריו.","ומציעים: \u0003לימא\u0004 \u0005[אמור]\u0006 ש\u0003ב\u0004שיטת \u0003שמואל קמיפלגי\u0004 \u0005[הם חולקים],\u0006 שכן \u0003אמר שמואל\u0004 בדין קדושת בכור: היולדת תאומים, והוציא האחד תחילה את ראשו וחזר למעי אמו — \u0003אין הראש\u0004 שיצא \u0003פוטר\u0004 את הולד הבא אחריו מן הבכורה, ואמורים הדברים דווקא \u0003בנפלים,\u0004 שהולד הראשון שהוציא את ראשו היה נפל, והבא אחריו הריהו ולד בן קיימא. ואולם בלידת ולדות שאינם נפלים, לידת הראש הריהי נחשבת לידה. ומעתה נאמר, כי ר' אלעזר סבור כשמואל, שאין הוצאת הראש בנפלים נחשבת כלידה, ואילו ר' יוחנן סבור כי הוצאת הראש נחשבת לידה אף בנפלים, שלא כשמואל.","ודוחים: אין להסיק כן, שהרי אפשר לומר כי \u0003ב\u0004נפל הנולד כשהוא \u0003שלם\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[כולם,\u0006 הן ר' אלעזר והן ר' יוחנן \u0005אינם חולקים]\u0006 שהוצאת הראש נחשבת ללידה, וחלוקים שניהם על שמואל. ו\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003ב\u0004נפל שנולד \u0003מחותך.\u0004 ובכך נחלקו, ש\u0003מר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 כי דווקא \u0003ב\u0004נולד כשהוא \u0003שלם הוא דקחשיב\u0004 \u0005[שהוא נחשב]\u0006 לידת הראש כלידה, אבל \u0003במחותך\u0004 — \u0003לא קחשיב\u0004 \u0005[נחשב].\u0006 \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003במחותך נמי חשיב\u0004 \u0005[גם כן נחשב].\u0006","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 נשנית בסוגיה זו, ובאופן זה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין בהוצאת הראש כשלעצמו להחשיבו כלידה אם לא יצא רובו, הריהו דווקא בנפל ש\u0003יצא מחותך או מסורס, הא\u0004 \u0005[הרי]\u0006 אם היה \u0003כתקנו\u0004 (שלם ויצא בדרך הרגילה) — \u0003הראש פוטר,\u0004 ונמצא ש\u0003תרוייהו לית להו\u0004 \u0005[שניהם אין להם,\u0006 אינם סבורים\u0005]\u0006 כדעת \u0003שמואל,\u0004 שכן \u0003אמר שמואל: אין הראש פוטר\u0004 כלל \u0003בנפלים.\u0004","\u0003איכא דמתני לה להא שמעתתא באפי נפשה\u0004 \u0005[יש ששונים אותה, את השמועה הזו, בפני עצמה],\u0006 ולא כמתייחסת אל משנתנו, ובאופן זה, \u0003אמר ר'\u0004 \u0003אלעזר: אין\u0004 יציאת \u0003הראש\u0004 של הנפל נחשבת \u0003כ\u0004יציאת \u0003רוב אברים, ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 יציאת \u0003הראש\u0004 נחשבת כיציאת \u0003רוב אברים,\u0004 והריהו כילוד. \u0003ו\u0004מסבירים את מחלוקתם, \u0003קמיפלגי\u0004 \u0005[חלוקים הם]\u0006 \u0003ב\u0004שיטת \u0003שמואל,\u0004 שר' אלעזר סבור כשיטת שמואל, ור' יוחנן אינו סבור כמותה.","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003יצא מחותך או מסורס, משיצא רובו\u0004 — \u0003הרי הוא כילוד.\u0004 ויש לדייק בלשון זו: \u0003מדקאמר\u0004 \u0005[מ\u0006מה \u0005שאמר]\u0006 התנא \"מחותך או \u0003מסורס\" מכלל\u0004 הדברים אתה למד שה\u0003מחותך\u0004 הנדון במשנתנו הוא שנולד איברים איברים, אבל אופן הלידה כשלעצמו היה \u0003כתקנו,\u0004 שיצא תחילה הראש, \u0003וקאמר\u0004 \u0005[והוא\u0006 התנא \u0005אמר]\u0006 בדינו של זה שרק \u0003משיצא רובו\u0004 — \u0003הרי זה כילוד.\u0004 הרי זה איפוא \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 הסבור שביציאת הראש נחשב כילוד!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0005לך ר' י\u0006 \u0003וחנן\u0004 בתשובה לשאלה זו: \u0003אימא\u0004 \u0005[אמור,\u0006 בהבנת משנתנו\u0005]:\u0006 \u0003\"יצא מחותך ומסורס\",\u0004 אבל אילו יצא מחותך ואינו מסורס, שראשו יצא תחילה — די בכך, כדי להחשיבו כילוד, אף שלא יצאו רוב איברים.","ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 \"מחותך \u0003או\u0004 מסורס\" \u0003קתני\u0004 \u0005[שנינו]\u0006 במשנתנו, ולא \"מחותך ומסורס\"! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת דברי התנא\u0005]: יצא\u0006 כשהוא \u0003מחותך\u0004 (איברים איברים) \u0003או\u0004 בגוף \u0003שלם,\u0004 \u0003וזה וזה,\u0004 בשני מקרים אלה, מדובר כשיצא \u0003מסורס\u0004 — דינו הוא שרק \u0003משיצא רובו הרי זה כילוד.\u0004 ואולם אם יצא ראשו — די בכך להחשיבו כילוד.","ועוד במחלוקת זו של ר' אלעזר ור' יוחנן, \u0003אמר רב פפא:\u0004 מחלוקת זו של האמוראים הריהי \u0003כ\u0004מחלוקת שנחלקו בה \u0003תנאי\u0004 \u0005[תנאים].\u0006 שכך שנינו: \u0003יצא מחותך או מסורס\u0004 — \u0003משיצא רובו הרי הוא כילוד.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: משיצא כתקנו.\u0004 ויש לדון בדברי ר' יוסי, \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 שמדבריו נראה שרק משיצא כתקנו הריהו נחשב כילוד, ואם לא יצא כתקנו אינו נחשב כילוד ואפילו יצאו רוב איבריו.","\u0003אמר רב פפא, הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת דברי התנאים\u0005]:\u0006 \u0003יצא מחותך ומסורס\u0004 — \u0003משיצא רובו הרי הוא כילוד,\u0004 וכל זאת משום שיצא מסורס, ומכאן נסיק לשיטת חכמים: \u0003הא\u0004 \u0005[הרי]\u0006 מכאן שאם יצא \u0003כתקנו,\u0004 וראשו יצא תחילה — \u0003הראש פוטר\u0004 את הבא אחריו מקדושת בכורה. ועל כך בא \u0003ר' יוסי\u0004 ו\u0003אומר:\u0004 אין המחותך נחשב כילוד אלא \u0003משיצא רובו, כתקנו.\u0004 ומעתה נמצאנו איפוא למדים, לשיטת רב פפא זו, כי מחלוקת ר' אלעזר ור' יוחנן הריהי כמחלוקת תנאים זו. ששיטת ר' יוחנן הריהי כשיטת חכמים שאפילו הנולד מחותך, יציאת הראש מחשיבתו כילוד. ואילו שיטת ר' אלעזר הריהי כשיטת ר' יוסי שכל שנולד מחותך, אפילו יצא הראש בתחילה (כתקנו) אינו נחשב בכך כילוד.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הבנה זו של רב פפא\u0005]\u0006 \u0003רב זביד:\u0004 זה שאמר ר' יוסי שאין המחותך נחשב כילוד אלא אם כן יצאו רוב איבריו כתקנו, \u0003מכלל\u0004 הדברים אתה למד ש\u0003ב\u0004נולד \u0003מסורס,\u0004 שאין ראשו יוצא בתחילה — \u0003רובו נמי\u0004 \u0005[גם כן]\u0006 \u0005לא פוטר, וקשה, שכן\u0006 \u0003הא קיימא לן\u0004 \u0005[הרי\u0006 כלל \u0005קיים לנו]\u0006 כי \u0003רובו\u0004 של דבר הריהו נחשב \u0003ככולו,\u0004 ואף כאן צריך להיחשב כילוד, כיון שיצאו רוב איבריו, אף שנולד כשהוא מחותך ומסורס!","\u0003אלא אמר רב זביד, הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת דבריהם\u0005]:\u0006 \u0003יצא מחותך ומסורס\u0004 — \u0003משיצא רובו הרי זה כילוד,\u0004 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם נולד \u0003כתקנו\u0004 — ביציאת \u0003הראש\u0004 כשלעצמו הריהו \u0003פוטר\u0004 את הבא אחריו מן הבכורה. ואילו \u0003ר' יוסי אומר:\u0004 אף בנולד כתקנו, אין יציאת הראש מחשיבתו כילוד, אלא \u0003משיצא כתקנו לחיים,\u0004 אבל הנולד שלא לחיים, כנולד מחותך באיברים איברים, אינו פוטר ביציאת הראש, אלא רק ביציאת רוב איבריו.","ומביאים ראיה להסברו של רב זביד, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטת הסבר זו: \u0003יצא מחותך (או) מסורס\u0004 — \u0003משיצא רובו הרי זה כילוד, הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם יצא \u0003כתקנו\u0004 — \u0003הראש פוטר.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: משיצא כתקנו לחיים.\u0004","ומעתה נדון: \u0003ואיזהו\u0004 הנולד שהוא בכלל הגדרה זו של \"\u0003כתקנו לחיים\"\u0004 — \u0003משיצא רוב ראשו.\u0004 \u0003ואיזהו רוב ראשו? ר'\u0004 \u0003יוסי אומר: משיצאו צדעיו\u0004 (רקותיו). \u0003אבא חנן משום\u0004 (בשם) \u0003ר' יהושע אומר: משיצא פדחתו\u0004 (החלק הקדמי של הגולגולת, המצח). \u0003ויש אומרים: משיראו קרני ראשו\u0004 (גובה ראשו שבצד העורף).","\u0003המפלת\u0004 ולד, \u0003ו\u0004אולם \u0003אין ידוע מהו\u0004 מינו, אם זכר או נקבה — \u0003תשב\u0004 ימי טהרה שלושים ושלושה ימים, כדין \u0003ל\u0004יולדת \u0003זכר, ו\u0004תשב ימי טומאה ארבעה עשר ימים, כדין \u0003ל\u0004יולדת \u0003נקבה.\u0004 האשה המפלת ו\u0003אין ידוע\u0004 מה הפילה, \u0003אם ולד היה\u0004 ואפשר שהיה זכר או נקבה, ו\u0003אם לאו\u0004 \u0005[לא],\u0006 שלא היה זה כלל ולד אלא רוח — \u0003תשב\u0004 ימי טהרה \u0003לזכר ו\u0004ימי טומאה \u0003לנקבה, ולנדה\u0004 שאם תראה לאחר שבועיים של ימי טומאה, הרי היא טמאה טומאת נדה, שאין לה ימי טהרה.","שנינו במשנתנו דינה של האשה המפלת ולד ואינה יודעת מה הפילה, אם זכר או נקבה או רוח, לענין ימי טומאה וימי טהרה. ובענין זה \u0003אמר ר'\u0004 \u0003יהושע בן לוי: עברה\u0004 האשה ב\u0003נהר והפילה\u0004 שם, ואין ידוע מה היה טיבו של הולד שהפילה — הריהי נוהגת ככל יולדת ו\u0003מביאה קרבן\u0004 יולדת, ואין חוששים שמביאה חולין לעזרה, \u0003ו\u0004קרבן זה \u0003נאכל\u0004 ככל קרבן יולדת ודאי. וטעם הדבר: משום ש\u0003הלך\u0004 (לך) בדין \u0003אחר רוב\u0004 ה\u0003נשים, ורוב\u0004 ה\u0003נשים ולד מעליא ילדן\u0004 \u0005[מעולה\u0006 הן \u0005יולדות].\u0006","ודנים בדבריו: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 שהמפלת ו\u0003אין ידוע אם ולד היה\u0004 — \u0003תשב לזכר ולנקבה ולנדה.\u0004 ומעתה יש מקום להקשות על ר' יהושע בן לוי: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תשב לנדה? לימא\u0004 \u0005[אמור]:\u0006 \u0003הלך אחר רוב נשים, ורוב נשים ולד מעליא ילדן\u0004 \u0005[מעולה יולדות],\u0006 ויש לה איפוא ימי טהרה (לאחר שתשב ארבעה עשר של ימי טומאה כיולדת נקבה), ככל יולדת ולד שלם, ומדוע אם ראתה דם לאחר ימי טומאה הריהי טמאת נדה?","ומשיבים: אין להקשות ממשנתנו, שכן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 עוסקת \u0003ב\u0004מקרה \u0003שלא הוחזקה\u0004 האשה כ\u0003עוברה\u0004 (הרה), \u0003וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003ר' יהושע בן לוי,\u0004 הרי זה דווקא \u0003כשהוחזקה עוברה.\u0004","ודנים עוד בשיטת ר' יהושע בן לוי, \u0003תא שמע\u0004 \u0005[בא\u0006 ושמע] ממה ששנינו בברייתא: \u0003בהמה\u0004 טהורה שטרם המליטה, והעובר הראשון שתמליט יהיה בקדושת בכור, \u0003שיצאה\u0004 מן הדיר אל מקום המרעה כשהיא \u0003מלאה\u0004 (מעוברת), \u0003ו\u0004לאחר מכן, באותו יום \u0003באה\u0004 (חזרה) כשהיא \u0003ריקנית\u0004 (ללא עובר במעיה), ואין ידוע מה הפילה, אם ולד (ואין הולד הבא אחריו בכור) או רוח (והנולד אחריו הריהו בכור) — \u0003הבא אחריו\u0004 הריהו \u0003בכור מספק.\u0004","\u0003ו\u0004לשיטת ר' יהושע בן לוי יש לשאול: \u0003אמאי\u0004 \u0005[מדוע\u0006 כן הדין]? והרי יש לנהוג לפי הכלל: \u0003הלך אחר רוב בהמות, ורוב בהמות ולד מעליא ילדן\u0004 \u0005[מעולה יולדות],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 שהפילה היה ולד שלם, והבא אחריו \u0003פשוט\u0004 (שאינו בכור) \u0003הוא!\u0004","\u0003אמר רבינא\u0004 בתירוץ לשאלה זו: \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 ש\u0003רוב בהמות\u0004 אכן \u0003יולדות\u0004 ולד שלם שהוא \u0003דבר הפוטר מבכורה\u0004 את הנולד אחריו, \u0003ו\u0004אולם \u0003מעוטן יולדות דבר שאינו פוטר מבכורה.\u0004 \u0003ו\u0004אולם על כך יש להוסיף גורם נוסף, שכן \u0003כל\u0004 הבהמות \u0003היולדות\u0004 — \u0003מטנפות\u0004 (מפרישות לכלוכים שונים) לפני ההמלטה, \u0003ו\u0004אילו הבהמה ה\u0003זו\u0004 שיצאה אל המרעה, \u0003הואיל ולא טנפה\u0004 לפני שיצאה, בכך \u0003אתרע לה רובא\u0004 \u0005[התקלקל,\u0006 נחלש \u0005לו הרוב],\u0006 ויש לנהוג איפוא בבהמה זו כבספק, והבא אחריו הריהו בכור מספק.","ושואלים על דברי רבינא אלו: \u0003אי\u0004 \u0005[אם]\u0006 כדבריו ש\u0003כל היולדות מטנפות\u0004 לפני הלידה, אם כן יש להסיק כי \u0003הא\u0004 \u0005[זו]\u0006 הבהמה \u0003מ\u0004זה ש\u0003לא מטנפה\u0004 \u0005[טנפה],\u0006 ראיה היא שלא ילדה ולד ממש, והבא אחריו \u0003בכור מעליא\u0004 \u0005[מעולה,\u0006 שלם\u0005]\u0006 \u0003הוא! אלא אימא\u0004 \u0005[אמור]\u0006 כך בדברי רבינא, ש\u0003רוב\u0004 ה\u0003יולדות מטנפות, וזו הואיל ולא טנפה\u0004 — \u0003אתרע לה רובא\u0004 \u0005[התקלקל לו הרוב].\u0006","ועוד בשיטת ר' יהושע בן לוי, נמסר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר: מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' יוסי בר' חנינא\u0004 על שיטת ר' יהושע בן לוי מענין \u0003טועה, ו\u0004הוסיף רבין ואמר: ואולם \u0003לא ידענא מאי תיובתא\u0004 \u0005[אין אני יודע מה הקושיה],\u0006 ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה קושיה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006"],["\u0003אשה שיצתה\u0004 (שיצאה) מביתה כשהיא \u0003מלאה\u0004 (הרה), \u0003ו\u0004לאחר זמן רב \u0003באה\u0004 (חזרה) כשהיא \u0003ריקנית,\u0004 והרי שילדה בתוך תקופה זו, ואולם אין היא יודעת דבר באשר ללידה זו, מתי ילדה ומה ילדה. \u0003והביאה\u0004 (ומזמן שבאה) \u0003לפנינו\u0004 חלפו עליה \u0003שלשה שבועין\u0004 (שבועות) \u0003טהורין\u0004 (שלא ראתה בהם כל דם). \u0003ו\u0004לאחר שלושת השבועות הללו עברו עליה \u0003עשרה שבועות,\u0004 שבהם היה שבוע \u0003אחד טמא\u0004 (שראתה בו בכל יום ויום) \u0003ו\u0004שבוע \u0003אחד טהור\u0004 (שלא ראתה בו כלל), מה דינה של זו?","\u0003משמשת\u0004 עם בעלה רק \u0003לאור\u0004 (בליל) בתחילת היום \u0003השלשים וחמש\u0004 לבואה, שהוא סוף השבוע החמישי, ושוב אינה משמשת. \u0003ומטבילין אותה תשעים וחמש טבילות\u0004 של מצוה, אלו \u0003דברי בית שמאי.\u0004 \u0003ובית הלל אומרים:\u0004 דיה ב\u0003שלשים וחמש\u0004 טבילות. \u0003ר' יוסי בר' יהודה אומר: דיה לטבילה\u0004 אחת \u0003שתהא באחרונה.\u0004","ומעתה לשיטתו זו של ר' יהושע בן לוי שהאשה שהוחזקה כהרה, הולכים בדינה אחר רוב יולדות היולדות ולד שלם, יש לשאול: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 מדוע האשה הזו ב\u0003שבוע ראשון לא משמשת\u0004 עם בעלה, אף שלא ראתה בשבוע זה — שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 \u0003יולדת זכר היא,\u0004 וילדה אותו סמוך מאד לחזרתה לכאן, ושבוע ראשון זה הריהו משבעת ימי טומאה ליולדת זכר. וכמו כן מובן גם כן מדוע אינה משמשת עם בעלה ב\u0003שבוע\u0004 ה\u0003שני\u0004 לחזרתה לכאן — שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 \u0003יולדת נקבה היא,\u0004 ושמא שבועיים אלה הינם בכלל שבועיים ימי טומאה של יולדת נקבה.","וכמו כן מובן מדוע אינה משמשת עם בעלה גם ב\u0003שבוע\u0004 ה\u0003שלישי\u0004 לחזרתה לכאן — שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 \u0003יולדת נקבה בזוב\u0004 (שהיתה זבה שלושה ימים לפני הלידה, ולא בגלל צער הלידה) \u0003היא,\u0004 שצריכה למנות שבעה נקיים רק לאחר שבועיים של ימי טומאה הנוהגים בלידת נקבה.","\u0003אלא שבוע רביעי, אף על גב דקא חזיא\u0004 \u0005[אף על פי שהיא רואה]\u0006 בו \u0003דם,\u0004 מדוע לא \u0003תשמש\u0004 בו עם בעלה, \u0003דהא\u0004 \u0005[שהרי]\u0006 ודאי \u0003דם טהור הוא,\u0004 שהרי אם הולכים אנו רוב נשים היולדות ולד שלם, אף אשה זו יש לה ימי טהרה כשאר יולדות, ובשבוע הרביעי הריהי בתוך ימים אלה! \u0003לאו\u0004 \u0005[האם לא]\u0006 נסיק מכאן שטעם הדבר הוא \u0003משום דלא אזלינן בתר רובא\u0004 \u0005[שאין אנו הולכים אחר רוב],\u0006 וקשה לשיטת ר' יהושע בן לוי.","\u0003אלא\u0004 מעתה יש להסביר את דברי רבין, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005] \"לא ידענא מאי תיובתא\"\u0006 \u0005[\"איני יודע מה הקושיה\"]?\u0006 שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 אכן הולכים אחר רוב הנשים היולדות ולד מעולה, ואשה זו בחזקת מי שילדה, ואולם אין הוכחה שילדה ביום שלפני בואה, ואפשר ש\u0003הרחיקה לידתה,\u0004 שהיה יום לידתה בזמן מרוחק הרבה לפני חזרתה לביתה, והסתיימו להם ימי טהרה זה מכבר.","ושבים לדון בברייתא זו לגופה. לאחר שהוסבר מדוע אינה משמשת עם בעלה בארבעת השבועות הראשונים מאז חזרתה, יש לברר: \u0003הך\u0004 \u0005[זה]\u0006 ה\u0003שבוע\u0004 ה\u0003חמישי\u0004 ש\u0003טהור הוא\u0004 — \u0003תשמש\u0004 בו, ומדוע הותרה לשמש רק בליל יום השלושים וחמישה, שהוא סופו של שבוע זה.","ומסבירים: טעם הדבר משום ש\u0003הך\u0004 \u0005[זה]\u0006 ה\u0003שבוע\u0004 ה\u0003רביעי,\u0004 שראתה בו בכל יום, ב\u0003כל יומא ויומא\u0004 \u0005[יום ויום]\u0006 שבו \u0003מספקין\u0004 \u0005[מסופקים אנו]\u0006 מה טיבה של ראייה זו שראתה, שמא חלה \u0003בסוף\u0004 תקופת ימי טוהר \u0003לידה ו\u0004הריהי איפוא \u0003בתחלת\u0004 ימי \u0003נדה,\u0004 וצריכה למנות שבעה ימי נדה מיום זה. \u0003ו\u0004משום כך אף ביום \u0003עשרין ותמניא גופיה\u0004 \u0005[עשרים ושמונה עצמו],\u0006 כלומר, ביום האחרון של השבוע הרביעי מאז חזרה האשה, יש להסתפק בו ו\u0003אימר\u0004 \u0005[ואמור,\u0006 נאמר] שמא כל ראיותיה עד יום זה היו בימי טהרה של לידה, וראייה זו \u0003תחלת נדה היא, ו\u0004לכן \u0003בעיא למיתב\u0004 \u0005[צריכה לשבת]\u0006 \u0003שבעה\u0004 ימים \u0003לנדתה\u0004 בשבוע הבא, השבוע החמישי לחזרתה. ולכן רק בליל היום השלושים וחמישה מותרת לשמש עם בעלה.","ושואלים עוד: מדוע אסורה לשמש בכל שלושת השבועות הראשונים מאז בואה, והרי האיסור עליה לשמש בשבוע האחרון אינו אלא משום החשש של לידה בזוב, ואולם הזבה יכולה להיטהר ביום השביעי לספירתה, ולטבול בו, ונמצאת איפוא ש\u0003ב\u0004יום ה\u0003עשרים וחד\u0004 \u0005[ואחד]\u0006 בבוקר יכולה היא ש\u0003תשמש\u0004 (אחר שתטבול)!","ומשיבים: ברייתא זו כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: אסור לעשות כן,\u0004 לשמש לאחר הטבילה ביום השביעי, וטעם הדבר: \u0003שמא תבא\u0004 האשה לאחר ששימשה מבעוד יום \u0003לידי ספק,\u0004 שתראה מבעוד יום, ונסתר בכך מנין שבעת הנקיים שספרה, ונמצא ששימשה באיסור. ושואלים: אם כן אל תשמש בבוקר של יום העשרים ואחד, ואולם \u0003לאורתא\u0004 \u0005[בערב]\u0006 של יום זה \u0003תשמש,\u0004 שהרי לא ראתה במשך היום דבר שיסתור את מנין שבעת ימי הנקיים שמנתה! ומשיבים: מדובר בברייתא זו \u0003כשראתה בערב.\u0004","\u0003ו\u0004דנים עוד בדברי הברייתא. שנינו בה כי לשיטת בית שמאי \u0003מטבילין אותה תשעים וחמש טבילות.\u0004 והסבר הדבר: \u0003שבוע קמא\u0004 \u0005[ראשון]\u0006 — \u0003מטבילין אותה\u0004 כל יום \u0003בלילותא\u0004 \u0005[בלילות],\u0006 שכן כיון שאין אנו יודעים את זמן הלידה ולא את מין הוולד, \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 \u0003יולדת זכר היא\u0004 זו, ובכל לילה יש מקום לומר שבו הסתיימו שבעת ימי הטומאה של יולדת זכר, וצריכה היא לטבול ככל המסיימת ימי טומאה.","ב\u0003שבוע שני\u0004 — \u0003מטבילין אותה\u0004 כל יום ויום \u0003בלילותא\u0004 \u0005[בלילות],\u0006 שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 באופן דומה לזה שנאמר ביחס לשבוע הראשון, שמא \u0003יולדת נקבה היא\u0004 זו, ובכל יום ויום בשבוע זה הסתיימו ארבעה עשר ימי הטומאה של יולדת נקבה, וצריכה היא לטבול בלילה טבילה זו של מצוה. ומלבד טבילות אלה של לילה שטובלת בשבוע השני, טובלת היא בו אף \u0003ביממא\u0004 \u0005[בימים,\u0006 בבקרים\u0005],\u0006 שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 שמא אשה זו \u0003יולדת זכר בזוב היא,\u0004 ובכל אחד מימי השבוע הראשון יש לומר שבו הסתיימו שבעת ימי טומאה של היולדת זכר והחלו שבעת ימי נקיות של היולדת זכר בזוב ומסתיימים במהלך השבוע השני. ומשום כך, בכל יום בבוקרו של השבוע השני צריכה היא לטבול טבילת זבה, שדינה לטבול בבוקר.","וכמו כן ב\u0003שבוע שלישי מטבילין לה ביממא\u0004 \u0005[אותה בימים]\u0006 מאותה סיבה שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 ש\u0003יולדת נקבה בזוב היא,\u0004 והסתיימו ימי טומאתה בשבוע השני, והחלה ספירת ימי נקיים של זבה לאחריהם, ומסתיימים הם במהלך השבוע השלישי, וטובלת היא בבוקרו של כל יום בשבוע זה משום זבה.","וגם \u0003בלילותא\u0004 \u0005[בלילות]\u0006 טובלת שכן \u0003בית שמאי לטעמייהו\u0004 \u0005[לטעמם,\u0006 לשיטתם\u0005],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בסוף מסכת נדה כי \u0003טבולת יום ארוך\u0004 (לאחר שהשלימה ששים וששה ימי טהרה הבאים לאחר ארבעה עשר ימי טומאה שלאחר לידת נקבה) \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003טבילה,\u0004 ולכן גם בכל לילה מלילי השבוע השלישי צריכה היא לטבול, שמא בדיוק בלילה זה הסתיימו שמונים הימים הללו. נמצא מספר הטבילות לחשבון זה שלושים וחמישה, וכן מוסיפה היא לטבול בלילות הבאים עד לכדי תשעים וחמש טבילות, מחשש שמא דווקא בלילות הבאים מסתיימים."],["ושואלים: \u0003מכדי\u0004 \u0005[הרי],\u0006 \u0003ימי טהרה\u0004 אלו שיש לחשוש שאולי הסתיימו עתה וצריכה לטבול במלאת שמונים הימים ללידה, לשיטת בית שמאי, \u0003כמה הוו\u0004 \u0005[הינם]\u0006 — \u0003שתין ושיתא\u0004 \u0005[ששים וששה],\u0006 \u0003דל\u0004 \u0005[הפחת]\u0006 ממנין הימים הללו את מנין שבע הטבילות ב\u0003שבוע\u0004 ה\u0003שלישי,\u0004 שהרי כבר נמנו טבילות אלה שכן \u0003אטבלינן לה\u0004 \u0005[מטבילים אנו אותה]\u0006 בהם בשל החשש שיולדת נקבה בזוב היא, אם כן \u0003פשו להו שתין נכי חדא\u0004 \u0005[נשארו להם ששים פחות אחת,\u0006 חמישים ותשע\u0005]\u0006 טבילות, ואולם אם נצרף את \u0003שתין נכי חדא\u0004 \u0005[ששים חסר אחת]\u0006 הטבילות הללו \u0003ותלתין וחמשא\u0004 \u0005[ושלושים וחמש]\u0006 הטבילות האחרות שטובלת בשלושת השבועות הללו, נמצא שכלל כל הטבילות — \u0003תשעין וארבע הויין\u0004 \u0005[הינן],\u0006 \u0003תשעין וחמש מאי עבידתייהו\u0004 \u0005[תשעים וחמש\u0006 טבילות שאמרו בית שמאי \u0005מה מעשיהם,\u0006 מה טיבם\u0005]?\u0006","\u0003אמר רב ירמיה מדפתי\u0004 בתשובה: מדובר כאן ב\u0003כגון שבאת\u0004 (שבאה) אשה זו \u0003לפנינו\u0004 בשעה שהיא \u0003בין השמשות,\u0004 שהוא ספק יום ספק לילה, \u0003דיהבינן\u0004 \u0005[שנותנים,\u0006 שמחייבים, \u0005אנו]\u0006 \u0003לה טבילה יתירתא\u0004 \u0005[נוספת]\u0006 בשל החשש שאולי שעה זו שבאה היא כבר יום המחר.","\u0003ו\u0004\u0003שואלים:\u0004 \u0003לבית הלל דאמרי\u0004 \u0005[שאומרים]\u0006 הם ש\u0003טבולת יום ארוך לא בעי\u0004 \u0005[אינה צריכה]\u0006 \u0003טבילה, תלתין וחמשא מאי עבידתייהו\u0004 \u0005[שלושים וחמש\u0006 טבילות \u0005מה מעשיהם,\u0006 מה טיבם\u0005]?\u0006","ומשיבים: \u0003עשרים ותמניא\u0004 \u0005[ושמונה]\u0006 טבילות — הרי אלו \u0003כדאמרן\u0004 \u0005[כמו שאמרנו]\u0006 בהסבר שיטת בית שמאי, משום החששות השונים: ליולדת זכר, ליולדת נקבה, ליולדת זכר בזוב, וליולדת נקבה בזוב. ואילו \u0003הך\u0004 \u0005[זה]\u0006 ה\u0003שבוע חמישי מטבלינן\u0004 \u0005[מטבילים אנו\u0006 אותה\u0005]\u0006 \u0003כל ליליא וליליא\u0004 \u0005[לילה ולילה],\u0006 שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]:\u0006 \u0003סוף נדה היא.\u0004","עוד שנינו בברייתא כי אשה זו שבשלושת השבועות הראשונים לבואה לא ראתה כל דם, ולאחר מכן עברו עשרה שבועות שבהם היה שבוע אחד טמא, שראתה בו כל יום, ושבוע אחד טהור שלא ראתה בו כלל, מצריכים אותה לטבול תשעים וחמש טבילות. ודנים בדבר, \u0003עשרה שבועין\u0004 \u0005[שבועות]\u0006 ששנינו, כדי ללמדנו כיצד בית שמאי הגיעו למנין תשעים וחמש טבילות, \u0003למה לי? בתמניא ופלגא סגי\u0004 \u0005[בשמונה וחצי מספיק],\u0006 שהרי לכשנצרף שמונה וחצי שבועות לשלושת השבועות הראשונים, הרי לפנינו כבר שמונים ימים, שבהם צריכה היא לטבול בכל יום בשל החשש שמא זה היום המסיים את שמונים הימים מאז ילדה!","ומשיבים: אכן די היה לשנות בברייתא רק שמונה וחצי שבועות נוספים, ואולם \u0003איידי דתנא פלגא\u0004 \u0005[מתוך ששנה מחצית]\u0006 \u0003שבוע, מסיק ליה\u0004 \u0005[השלים אותו]\u0006 כבר לשבוע שלם, והרי זה איפוא עולה לתשעה שבועות. \u0003ואיידי דתנא\u0004 \u0005[ומתוך ששנה]\u0006 בדבריו \u0003\"שבוע טמא\"\u0004 שהוא השבוע התשיעי, \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003\"שבוע טהור\",\u0004 שהוא השבוע העשירי.","ודנים עוד בדברי הברייתא, ושואלים: לשיטת בית הלל שאין אשה זו טובלת אלא שלושים וחמש טבילות, וכפי שהוסברו הדברים, \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד טבילות, שהן \u0003טבילת\u0004 ה\u0003זבה,\u0004 שהרי היא בגדר ספק זבה למן השבוע הששי, שכן אינה יודעת אם ראיית השבוע הרביעי היא דם טהרה וראיית השבוע השישי היא ראיית נדה, או שראיית השבוע הרביעי היא ראיית נדה וראיית השבוע הששי היא אם כן ראיית זיבה, וצריכה לטבול עליה בסוף השבוע השביעי. וכיוצא בדבר, בשבוע השמיני, ובשבוע העשירי. ונמצא איפוא שיש לה ארבע טבילות נוספות, שבסוף השבוע השביעי, ובסוף השבוע התשיעי, ובסוף השבוע האחד עשר ובסוף השבוע השלושה עשר!","ומשיבים: רק טבילה ש\u0003לפני\u0004 ה\u0003תשמיש\u0004 שמותרת בו ביום, השלושים וחמישה \u0003קחשיב\u0004 \u0005[הוא\u0006 התנא בשיטת בית הלל מחשיב] במנין הטבילות, ואילו טבילה ש\u0003לאחר\u0004 יום ה\u0003תשמיש\u0004 הזה — \u0003לא קחשיב\u0004 \u0005[אין הוא מחשיב].\u0006","ושואלים: \u0003ול\u0004שיטת \u0003בית שמאי, דחשיב\u0004 \u0005[שמחשיבים]\u0006 הם בכלל תשעים וחמש הטבילות שטובלת אשה זו אף טבילות ש\u0003לאחר\u0004 יום ה\u0003תשמיש, ניחשוב נמי\u0004 \u0005[נחשיב גם כן]\u0006 \u0003טבילת זבה,\u0004 והרי איפוא ארבע טבילות נוספות למניינם! ומשיבים: \u0003ב\u0004טבילות הקשורות ל\u0003לידה\u0004 — \u0003קמיירי\u0004 \u0005[מדובר],\u0006 ואילו בטבילות אחרות, וכגון \u0003בזיבה\u0004 — \u0003לא קמיירי\u0004 \u0005[מדובר].\u0006","ושואלים על כך: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 בכלל מנין הטבילות שמנו בית שמאי \u0003יולדת בזוב,\u0004 הרי שאף טבילת זבה נכללת במנין הטבילות הללו! ומתרצים: טבילת \u0003יולדת בזוב\u0004 — \u0003קחשיב\u0004 \u0005[הוא\u0006 התנא לשיטת בית שמאי \u0005מונה]\u0006 במנין הטבילות, שטבילה זו נדחתה עד לאחר גמר מנין ימי טומאה של הלידה, וקשורה ללידה, ואולם טבילה משום \u0003זיבה גרידתא\u0004 \u0005[כשלעצמה]\u0006 — \u0003לא קחשיב\u0004 \u0005[אין הוא מונה].\u0006","ועוד בבירור דברי הברייתא. למדנו כי בשבוע הראשון מטבילים אותה בכל לילה מימי השבוע בשל החשש שיולדת זכר היא והסתיימו בלילה זה שבעת ימי טומאה. ושואלים: \u0003שבועתא קמא דאתיא לקמן\u0004 \u0005[\u0006באותו \u0005שבוע ראשון שבאה לפנינו],\u0006 מלבד הטבילות שטובלת בלילות, \u0003ליטבלה ביומא\u0004 \u0005[שתטבול\u0006 גם \u0005בימים]\u0006 \u0003דילמא\u0004 \u0005[שמא]\u0006 ב\u0003כל יומא ויומא\u0004 \u0005[יום ויום]\u0006 בשבוע זה, \u0003שלימו\u0004 \u0005[מלאו]\u0006 \u0003לה ספורים\u0004 (ספירת שבעת ימי נקיים של הזבה, הטובלת ביום) \u0003דידה\u0004 \u0005[שלה]\u0006 שכן אפשר שהיתה זבה קודם שבאה לפנינו, ומלאו ימיה בשבוע הראשון. ועם טבילות אלה יתווספו למנין הטבילות שהיא טובלת עוד שבע טבילות!","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו ימי ספירת הנקיים של הזבה \u0003ספורים בפנינו,\u0004 שהיא זבה בודאות, וזו אין אנו יודעים אם היתה זבה קודם שבאה לפנינו.","ושואלים עוד: ב\u0003סוף שבוע קמא\u0004 \u0005[הראשון],\u0006 ולאחר שספרה בפנינו שבעה נקיים, \u0003ליטבלה\u0004 \u0005[שיטבילוה]\u0006 כזבה בבוקר היום השביעי, והרי לפנינו עוד טבילה נוסף למנין הנזכר! ומשיבים: בטבילה של \u0003חד\u0004 \u0005[\u0006יום \u0005אחד]\u0006 \u0003בשבוע לא קמיירי\u0004 \u0005[מדובר].\u0006","ושואלים עוד: ב\u0003יומא קמא דאתיא לקמן, ליטבלה\u0004 \u0005[יום ראשון שבאה לפנינו, שיטבילוה]\u0006 משום \u0003דילמא\u0004 \u0005[שמא]\u0006 היא זבה קטנה (שראתה זיבה יום או יומיים בלבד) שדינה ש\u0003שומרת יום כנגד יום היא!\u0004 ומשיבים: \u0003בזבה גדולה\u0004 (שראתה בימי זיבתה שלושה ימים רצופים), שהיא סופרת שבעה נקיים — \u0003קמיירי\u0004 \u0005[מדובר],\u0006 ואילו \u0003בזבה קטנה\u0004 — \u0003לא קמיירי\u0004 \u0005[לא מדובר].\u0006","ובסופו של בירור דברי הברייתא הזו, מסכמים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מכלל הדיונים \u0003תלת\u0004 \u0005[שלוש]\u0006 מסקנות: האחת, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ברייתא זו כשיטת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: בעינן\u0004 \u0005[צריכים אנו]\u0006 בזבה שיהיו שבעת ימי הנקיים \u0003ספורים בפנינו.\u0004","\u0003ו\u0004עוד \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי ברייתא זו כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר:\u0004 אף שרשאית הזבה לשמש ביום השביעי, לאחר שטבלה בבוקרו, \u0003אבל אמרו חכמים\u0004 ש\u0003אסור לעשות כן,\u0004 משום החשש \u0003שמא תבא\u0004 במהלך היום השביעי \u0003לידי ספק\u0004 בראיית דם, ונמצאת איפוא ששימשה בזבות.","\u0003ו\u0004עוד \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טבילה בזמנה\u0004 הריהי \u0003מצוה,\u0004 ומשום כך טובלת היא בכל יום, אף שאסורה לשמש. \u0003ו\u0004אילו \u0003ר' יוסי בר' יהודה אומר: דיה לטבילה באחרונה\u0004 לכשתהיה מותרת לשמש עם בעלה, \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 שטבילה \u0003בזמנה מצוה,\u0004 ולשיטת ר' יוסי בר' יהודה טובלת רק טבילה אחרונה זו.","האשה \u0003המפלת ליום\u0004 ה\u0003ארבעים\u0004 לטבילתה, שבו שימשה עם בעלה — \u0003אינה חוששת ל\u0004שמא היה זה \u0003ולד\u0004 ונטמאה בהפלתו, שאין גמר יצירתו של הולד במעי אמו אלא לסוף ארבעים יום משעה שנזרעה. ואולם המפלת \u0003ליום\u0004 ה\u0003ארבעים ואחד\u0004 לטבילתה — יש לחשוש שהיה זה ולד, וכיון שאין ידוע מה מינו, \u0003תשב\u0004 ימי טהרה כמו \u0003ל\u0004יולדת \u0003זכר\u0004 (שבעה ימי טומאה ושלושים ושלושה ימי טהרה), \u0003ו\u0004שבועיים ימי טומאה כמו \u0003ל\u0004יולדת \u0003נקבה, ולנדה\u0004 שאם תראה לאחר שבועיים של ימי טומאה דם, הרי היא נידה, שאין לה לענין זה ימי טהרה.","\u0003ר' ישמעאל אומר:\u0004 המפלת ב\u0003יום ארבעים ואחד\u0004 מטבילתה — \u0003תשב\u0004 ימי שבעת ימי טומאה בלבד, כמו \u0003ל\u0004כל היולדת \u0003זכר.\u0004 \u0003ול\u0004ענין שאם תראה לאחר מכן דם, הריהי טמאה ככל \u0003נדה.\u0004 ואם הפילה ב\u0003יום שמונים ואחד\u0004 מטבילתה — \u0003תשב לזכר ולנקבה ולנדה.\u0004 וטעמו של דבר, \u0003ש\u0004כן \u0003הזכר נגמר\u0004 מעשה יצירתו \u0003לארבעים ואחד\u0004 יום, \u0003ו\u0004אילו מעשה יצירתה של \u0003הנקבה\u0004 נגמר \u0003לשמונים ואחד\u0004 יום, ואם הפילה לפני כן, אין לה לחשוש שמא היתה זו נקבה. \u0003וחכמים אומרים: אחד בריית\u0004 (בריאת) \u0003הזכר ואחד בריית הנקבה\u0004 — \u0003זה וזה ארבעים ואחד.\u0004","שנינו במשנתנו כי המפלת ביום הארבעים ואחד לטבילתה עליה לנהוג כיולדת זכר וכיולדת נקבה, וגם כמי שלא ילדה כלל ולד (לענין טומאת נדה). ושואלים: אם ראתה דם לאחר ימי טומאה של היולדת נקבה, שהם ארבעה עשר, הריהי טמאת נדה, אם כן \u0003למה הוזכר\u0004 שנוהגת כיולדת \u0003זכר?\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין שבעת \u0003ימי טומאה\u0004 — \u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 שנוהגת כיולדת \u0003נקבה,\u0004 ובכלל ארבעה עשר ימי טומאה גם שבעה ימים לזכר, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003ל\u0004ענין \u0003ימי טהרה,\u0004 שאין לה אלא ארבעים יום כשאר יולדת זכר —"],["\u0003הא קתני\u0004 \u0005[הרי שנה]\u0006 \u0003נדה,\u0004 שיש לה לחשוש בכל ראיית דם שתראה, לנהוג בטומאת נדה, שאין לה כלל ימי טהרה!","ומשיבים: הוזכר במשנתנו שנוהגת אף כיולדת זכר, לענין זה \u0003שאם תראה\u0004 דם ב\u0003יום\u0004 ה\u0003שלושים וארבעה\u0004 מאז שהפילה, \u0003ותחזור ותראה\u0004 שוב דם ב\u0003יום\u0004 ה\u0003ארבעים ואחד\u0004 מאז שהפילה — דינה הוא ש\u0003תהא מקולקלת\u0004 (פסולה, ואסורה בטבילה ובתשמיש) \u0003עד\u0004 יום ה\u0003ארבעים ושמונה\u0004 מאז ההפלה. שאף שנוהגת מן הצד האחד לחומרא בראיית היום השלושים וארבעה כנדה, יש גם לחשוש שראיית יום השלושים וארבעה (אף שנוהגת מן הצד האחד לחומרא, כנדה) חלה בימי טהרה שלה כיולדת זכר שאין ראייה זו מטמאתה, ולא נטמאה בטומאת נדה אלא בראיית היום הארבעים ואחד, ואינה טובלת איפוא אלא ביום הארבעים ושמונה משהסתיימו שבעת ימי נדות אלה.","\u0003וכן\u0004 בדומה לכך קיים חשש זה גם \u0003לענין\u0004 שנוהגת כיולדת \u0003נקבה, שאם תראה\u0004 ב\u0003יום\u0004 ה\u0003שבעים וארבעה\u0004 להפלה, \u0003ותחזור ותראה\u0004 שוב ב\u0003יום\u0004 ה\u0003שמונים ואחד\u0004 להפלה — יש לחשוש, שראיית יום השבעים וארבעה (אף שנוהגת מן הצד האחד לחומרא, כנדה) חלה בימי טהרה שלה כיולדת נקבה, ואין היא טמאת נדה אלא בראיית יום השמונים ואחד, ו\u0003תהא\u0004 איפוא \u0003מקולקלת\u0004 (מנועה) מלטבול ולשמש \u0003עד\u0004 יום ה\u0003שמונים ושמונה\u0004 משיסתיימו שבעה ימי נדות אלה.","שנינו במשנתנו כי \u0003ר' ישמעאל אומר\u0004 שהיולדת ב\u0003יום ארבעים ואחד תשב לזכר ולנדה\u0004 ולא לנקבה, שיצירת הזכר נגמרת לארבעים יום, ואילו יצירת הנקבה נגמרת לשמונים יום. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0005ר' ישמעאל אומר:\u0006 \u0003הכתוב\u0004 \u0003טימא\u0004 (נתן ימי טומאה שבעה ימים), \u0003וטיהר\u0004 (נתן ימי טהרה שלושים ושלושה ימים) \u0003ב\u0004יולדת \u0003זכר,\u0004 ובכללם הם ארבעים יום. \u0003ו\u0004כמו כן הכתוב \u0003טימא\u0004 ארבעה עשר ימי טומאה \u0003וטיהר\u0004 ששים וששה ימי טהרה \u0003ב\u0004יולדת \u0003נקבה,\u0004 ובכללם הם שמונים יום.","ויש להשוות ביניהם: \u0003מה כשטימא וטיהר בזכר\u0004 ארבעים יום אלו — משך ימי \u0003יצירתו\u0004 \u0003כיוצא בו,\u0004 ארבעים יום, \u0003אף כשטימא וטיהר בנקבה\u0004 שמונים הימים הללו — משך ימי \u0003יצירתה כיוצא בה,\u0004 שמונים יום. \u0003אמרו לו\u0004 חכמים: \u0003אין למדין\u0004 משך ימי \u0003יצירה מ\u0004משך ימי \u0003טומאה,\u0004 ואף יצירת הנקבה הריהי בארבעים יום.","ועוד ראיה לדבריהם, \u0003אמרו לו\u0004 חכמים \u0003לר' ישמעאל: מעשה בקליאופטרא מלכת אלכסנדרוס שנתחייבו שפחותיה\u0004 מסיבה כל שהיא \u0003הריגה למלכות.\u0004 וכיון שכך, נמצאה לה הזדמנות לבדוק מהו זמן יצירתו של העובר. זיווגה אותן, ולאחר מכן פתחו את בטנן, \u0003ובדקן\u0004 את מצב העוברים, \u0003ומצאן זה וזה,\u0004 זכר ונקבה, שנגמרה יצירתם \u0003לארבעים ואחד\u0004 יום מן הזיווג! \u0003אמר להן: אני מביא לכם ראייה מן התורה, ואתם מביאין לי ראייה מן השוטים?\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 איזו\u0005]\u0006 \u0003ראיה מן התורה\u0004 הביא להם ר' ישמעאל, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונתו ללימוד זה שהזכיר כי \u0003טימא וטיהר בזכר וטימא וטיהר בנקבה\u0004 — \u0003הא קאמרי ליה\u0004 \u0005[הרי אמרו לו]\u0006 בתשובה לדבר כי \u0003אין דנין יצירה מטומאה!\u0004","ומסבירים: הכוונה לדרשה אחרת: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ביולדת \"אשה כי תזריע וילדה זכר... ואם נקבה \u0003תלד\"\u0004 (ויקרא יב, ב—ה) — \u0003הוסיף לה הכתוב\u0004 לשון \u0003לידה אחרת\u0004 (נוספת על זו האמורה בזכר) \u0003בנקבה\u0004 ללמד שימי יצירתה של הנקבה הנולדת כפולים מזה של הזכר.","\u0003ו\u0004עוד מבררים, \u0003מאי\u0004 \u0005[\u0006ב\u0005מה]\u0006 ראיה זו שהביאו חכמים ממעשה קליאופטרה המלכה הריהו לדעת ר' ישמעאל \u0003ראיה מן השוטים?\u0004 — שכן \u0003אימר\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 כי ה\u0003נקבה\u0004 שנמצאה במעי השפחה לאחר ארבעים יום מזיווגה, \u0003קדים ואיעבור ארבעין יומין קמי\u0004 \u0005[קדמה והתעברה ארבעים יום לפני]\u0006 שנזרע העובר ה\u0003זכר,\u0004 ולא היתה יצירתה לארבעים יום, אלא לשמונים יום.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על טענה זו? — לדעתם לא כך היה, משום שהמלכה קליאופטרה \u0003סמא דנפצא אשקינהו\u0004 \u0005[סם ניפוץ השקתה אותן]\u0006 לפני זיווגן זה, ואילו היתה מעוברת לפני כן, היה העובר מושמד על ידי סם זה. ושואלים: \u0003ור' ישמעאל\u0004 מה משיב הוא על טענה זו? \u0003איכא גופא\u0004 \u0005[יש גוף]\u0006 ש\u0003לא מקבל סמא\u0004 \u0005[סם]\u0006 שכזה, שאין סם זה משפיע עליו, ויתכן איפוא שכבר היתה מעוברת לפני כן בעובר נקבה, והסם לא פגע בה.","ועוד ברייתא שנינו בנוסח אחר: \u0003אמר להם ר'\u0004 \u0003ישמעאל\u0004 לחכמים, כראיה לשיטתו: \u0003מעשה\u0004 היה \u0003בקלפטרא מלכת יוונית שנתחייבו שפחותיה הריגה למלכות, ובדקן\u0004 (ערכה בהן ניסוי) לדעת מהו משך יצירת הולד, \u0003ומצאן\u0004 שנוצר עובר \u0003זכר לארבעים ואחד\u0004 יום מיום הזיווג, \u0003ו\u0004העובר שמינו \u0003נקבה\u0004 נוצר \u0003לשמונים ואחד\u0004 יום, והרי איפוא ראיה שמשך יצירתה של הנקבה הוא בשמונים ואחד יום! \u0003אמרו לו\u0004 חכמים בתשובה לכך: \u0003אין מביאין ראיה מן השוטים.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שזו היא ראיה מן השוטים? — לדעתם \u0003הך\u0004 \u0005[זה]\u0006 העובר שמינו \u0003נקבה\u0004 כך נוצר: שבתחילה אמנם זיווגו את אמו, ואולם היא לא נתעברה מזיווג זה, ולאחר מכן \u0003אייתרה ארבעין יומין\u0004 \u0005[המתינה ארבעים ימים],\u0006 \u0003והדר איעבר\u0004 \u0005[וחזרה\u0006 והזדווגה שוב ורק אז \u0005התעברה],\u0006 ונמצא איפוא שבשעה שהרגוה ומצאו את העובר הנקבה שבמעיה, אף זה נגמרה יצירתו בארבעים ואחד יום.","ושואלים: \u0003ור' ישמעאל,\u0004 מה משיב הוא לטענה זו? — לדעתו אין לומר כן, משום ש\u0003לשומר מסרינהו\u0004 \u0005[מסרו אותן,\u0006 את השפחות הללו\u0005],\u0006 ולא יכלו להיבעל בתוך תקופת הניסיון שלהן. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה משיבים לדברים אלו? — אין בשמירתו של השומר להבטיח שלא נזדווגה בתוך התקופה הזו, שכן \u0003אין אפוטרופוס\u0004 (משגיח) נאמן \u0003לעריות,\u0004 ו\u0003אימא\u0004 \u0005[אמור,\u0006 הנח] כי ה\u0003שומר גופיה\u0004 \u0005[עצמו]\u0006 \u0003בא עליה\u0004 בתוך הזמן.","וחוזרים ושואלים על שיטת ר' ישמעאל: \u0003ודילמא אי קרעוהו להך\u0004 \u0005[ושמא אם היו קורעים אותו את\u0006 העובר \u0005הזה]\u0006 שנמצא \u0003נקבה\u0004 לפני כן, \u0003בארבעין וחד\u0004 \u0005[ב\u0006מלאת \u0005ארבעים ואחד]\u0006 יום מאז הזיווג גם כן \u0003הוה משתכחא\u0004 \u0005[היה נמצא]\u0006 שמינו נקבה, והרי איפוא שמשך יצירת הנקבה \u0003כ\u0004משך יצירת ה\u0003זכר? אמר אביי:\u0004 אין לומר כן, משום שכשנמצאו שני העוברים הללו, הזכר והנקבה, ביום הארבעים ואחד לזיווג השני, וזה ביום השמונים ואחד לזיווג השני, נמצאו \u0003בסימניהון\u0004 \u0005[בסימניהם]\u0006 המלמדים על גילם (כגון שערותיהם וצפורניהם) \u0003שוין.\u0004 ומתוך שסימניה של הנקבה ביום השמונים ואחד היו כסימניו של הזכר ביום הארבעים ואחד, הרי זה מורה שאז נוצרו.","שנינו במשנתנו, \u0003וחכמים אומרים: אחד בריית זכר ואחד בריית נקבה,\u0004 זה וזה לארבעים ואחד יום. ושואלים: שיטת \u0003חכמים היינו תנא קמא\u0004 \u0005[זהו\u0006 כשיטת \u0005התנא הראשון],\u0006 ומה הוסיפו בדבריהם!?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שחזרו ונכתבו הדברים במשנה כדי \u0003למסתמא רישא כרבנן\u0004 \u0005[ל\u0006הורות שדעת תנא קמא \u0005הסתומה,\u0006 ללא שם אומרו, שב\u0005תחילת\u0006 המשנה אינה דעת יחיד, אלא הריהי \u0005כ\u0006דעת \u0005חכמים]\u0006 הרבים, \u0003ו\u0004כלל הוא: \u0003יחיד ורבים\u0004 — \u0003הלכה כרבים,\u0004 אין לומר כן שזה טעם הדבר, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שהלכה כתנא קמא, שכן כלל הוא בכל מקום, שהלכה כתנא קמא כנגד דעת יחיד, ואין סיבה לחזור ולשנות שדעת תנא קמא הריהי כדעת חכמים!","ומשיבים: היה צריך במשנתנו לחזור ולומר שדעת תנא קמא כדעת חכמים, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מסתברא טעמא\u0004 \u0005[מסתבר הטעם]\u0006 של \u0003ר' ישמעאל, דקמסייע ליה קראי\u0004 \u0005[ש\u0006כן \u0005מסייעים לו מקראות],\u0006 ותהא הלכה כמוהו. לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שדעת תנא קמא כדעת חכמים, ויחיד ורבים הלכה כרבים.","ועוד בעניין העובר במעי אמו, \u0003דרש ר' שמלאי: למה הולד דומה\u0004 בהיותו \u0003במעי אמו\u0004 — \u0003לפנקס שמקופל.\u0004 \u0003ומונח\u0004 העובר כש\u0003ידיו על שתי צדעיו\u0004 (רקותיו), \u0003שתי אציליו\u0004 (הזרוע העליונה, שמן המרפק עד השכם) \u0003על שתי ארכובותיו\u0004 (ברכיו), \u0003ושני עקביו על שתי עגבותיו\u0004 (עכוזיו, אחוריו), \u0003וראשו מונח לו בין ברכיו.\u0004 \u0003ופיו סתום, וטבורו פתוח.\u0004 \u0003ואוכל ממה שאמו אוכלת, ושותה ממה שאמו שותה, ואינו מוציא רעי\u0004 (צואה) \u0003שמא יהרוג את אמו.\u0004 \u0003וכיון שיצא לאויר העולם\u0004 — \u0003נפתח הסתום\u0004 (פיו), \u0003ונסתם הפתוח\u0004 (טבורו), \u0003שאלמלא כן אינו יכול לחיות אפילו שעה אחת.\u0004","\u0003ונר דלוק לו על ראשו, וצופה ומביט מסוף העולם ועד סופו, שנאמר: \"בהלו נרו עלי ראשי לאורו אלך חשך\"\u0004 (איוב כט, ב). \u0003ואל תתמה\u0004 כיצד ניתן לראות מסוף העולם ועד סופו, \u0003שהרי אדם ישן כאן\u0004 במקום זה, \u0003ורואה חלום\u0004 המתרחש במקום רחוק, כגון \u0003באספמיא.\u0004","\u0003ואין לך ימים שאדם שרוי\u0004 בהם \u0003בטובה יותר מאותן הימים\u0004 שבהיותו עובר במעי אמו, \u0003ש\u0004כן \u0003נאמר\u0004 בפסוק קודם לכן בפי איוב: \u0003\"מי יתנני כירחי קדם כימי אלוה ישמרני\"\u0004 (שם א), שלא היו לו בימי חייו ימים טובים כימים אלה. \u0003ו\u0004מנין שבימי ההריון הכתוב מדבר — שכן \u0003איזהו ימים שיש בהם ירחים ואין בהם שנים\u0004 — \u0003הוי אומר: אלו ירחי לידה.\u0004","\u0003ומלמדין אותו,\u0004 את העובר במעי אמו, את \u0003כל התורה כולה, ש\u0004כן \u0003נאמר: \"וירני ויאמר לי יתמך דברי לבך שמר מצו‍תי וחיה\"\u0004 (משלי ד, ד), \u0003ואומר\u0004 עוד: \u0003\"בסוד אלוה עלי אהלי\"\u0004 (איוב שם, ד).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"ואומר\",\u0004 ומדוע לא די בפסוק מספר משלי? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין ללמוד מפסוק זה לכל אדם, כיון ש\u0003נביא הוא דקאמר\u0004 \u0005[שאמר],\u0006 ואין הדברים אמורים אלא בו ובשכמותו, לכך \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה מהפסוק האמור באיוב: \u0003\"בסוד אלוה עלי אהלי\".\u0004","\u0003וכיון שבא\u0004 העובר \u0003לאויר העולם, בא מלאך וסטרו על פיו, ומשכחו כל התורה כולה, ש\u0004כן \u0003נאמר: \"לפתח חטאת רבץ\"\u0004 (בראשית ד, ז), שעם היציאה לעולם (\"לפתח\") כבר אורבת החטאת (\"חטאת רובץ\") הנובעת מאי ידיעת התורה.","\u0003ואינו יוצא משם עד שמשביעין אותו, ש\u0004כן \u0003נאמר: \"כי לי תכרע כל ברך תשבע כל לשון\"\u0004 (ישעיה מה, כג). וכך נדרש הכתוב: \u0003\"כי לי תכרע כל ברך\"\u0004 — \u0003זה יום המיתה, שנאמר\u0004 בו: \u0003\"לפניו יכרעו כל יורדי עפר\"\u0004 (תהלים כב, ל), \u0003\"תשבע כל לשון\"\u0004 — \u0003זה יום הלידה.\u0004 \u0003ש\u0004כן \u0003נאמר\u0004 בשבחיו של איש המעלה: \u0003\"נקי כפים ובר לבב אשר לא נשא לשוא נפשו ולא נשבע למרמה\"\u0004 (תהלים כד, ד), שעמד בשבועתו שנשבע.","\u0003ומה היא\u0004 אותה \u0003השבועה שמשביעין אותו\u0004 — \u0003תהי צדיק ואל תהי רשע, ואפילו כל העולם כולו אומרים לך \"צדיק אתה\"\u0004 — \u0003היה בעיניך כרשע.\u0004 \u0003והוי יודע שהקדוש ברוך הוא טהור, ומשרתיו טהורים, ונשמה שנתן בך\u0004 — \u0003טהורה היא.\u0004 \u0003אם אתה משמרה בטהרה\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הריני נוטלה ממך.\u0004","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם ב\u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל: משל לכהן שמסר תרומה לעם הארץ, ואמר לו אם אתה משמרה בטהרה\u0004 — \u0003מוטב, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הריני שורפה לפניך.\u0004","\u0003אמר ר'\u0004 \u0003אלעזר:\u0004"],["\u0003מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמדנו שמשביעים אותו ביום הלידה? \"עליך נסמכתי מבטן \u0003ממעי אמי אתה גוזי\"\u0004 (תהלים עא, ו). ומבררים: \u0003מאי\u0004 \u0005[מה,\u0006 כיצד\u0005]\u0006 \u0003משמע דהאי\u0004 \u0005[ש\u0006לשון \u0005זו]\u0006 \u0003\"גוזי\" לישנא דאשתבועי\u0004 \u0005[לשון שבועה]\u0006 \u0003הוא? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גזי נזרך והשליכי\"\u0004 (ירמיה ז, כט).","\u0003ו\u0004עוד בעניינו של העובר במעי אמו, \u0003אמר ר'\u0004 \u0003אלעזר: למה ולד דומה במעי אמו?\u0004 — \u0003לאגוז\u0004 ה\u0003מונח בספל של מים, אדם נותן אצבעו עליו\u0004 — \u0003שוקע לכאן ולכאן.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה חדשים הראשונים\u0004 של ההריון — ה\u0003ולד דר במדור התחתון,\u0004 בשלושת החודשים ה\u0003אמצעיים\u0004 — ה\u0003ולד דר במדור האמצעי,\u0004 ואילו בשלושת החודשים ה\u0003אחרונים\u0004 של ההריון — ה\u0003ולד דר במדור העליון.\u0004 \u0003וכיון שהגיע זמנו לצאת\u0004 — \u0003מתהפך ויוצא, וזהו\u0004 המכונה \u0003\"חבלי אשה\",\u0004","\u0003והיינו דתנן\u0004 \u0005[וזהו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חבלי\u0004 לידה \u0003של נקבה מרובין מ\u0004חבלי לידה \u0003של זכר.\u0004","\u0003ואמר ר'\u0004 \u0003אלעזר: מאי קרא\u0004 \u0005[מה המקרא]\u0006 המלמדנו כן? \u0003\"אשר עשיתי בסתר רקמתי בתחתיות ארץ\"\u0004 (תהלים קלט, טו). ולדיוק הכתוב: \u0003\"דרתי\u0004 בתחתיות ארץ\", \u0003לא נאמר, אלא \"רקמתי\u0004 בתחתיות ארץ\". הרי שבראשית יצירתו של העובר, בעודו נרקם (\"רוקמתי\") הריהו שרוי במדור התחתון (\"תחתיות ארץ\").","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונים,\u0006 מיוחדים\u0005]\u0006 הם \u0003חבלי נקבה\u0004 שהם \u0003מרובין משל זכר?\u0004 — \u0003זה\u0004 הזכר \u0003בא\u0004 (נולד) \u0003כדרך תשמישו,\u0004 וכשם שדרך התשמיש הזכר מפנה פניו כלפי מטה, אף בשעת לידתו הריהו כן. \u0003וזה\u0004 הנקבה אף הוא \u0003בא כדרך תשמישו,\u0004 שכשם שבשעת תשמיש פניה כלפי מעלה, אף בשעת לידתה הריהי כן. ומשום כך, \u0003זו\u0004 הנקבה נצרכת שתהיה \u0003הופכת פניה\u0004 בשעת לידתה, \u0003ו\u0004אילו \u0003זה\u0004 הזכר \u0003אין הופך פניו\u0004 בשעת לידתו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ב\u0003שלשה\u0004 ה\u0003חדשים הראשונים\u0004 של ההריון — ה\u0003תשמיש קשה\u0004 (מכביד ומזיק) \u0003לאשה וגם קשה לולד.\u0004 בשלושת החודשים ה\u0003אמצעיים\u0004 של ההריון — התשמיש \u0003קשה לאשה ויפה לולד.\u0004 ואילו בשלושת החודשים ה\u0003אחרונים\u0004 של ההריון — התשמיש \u0003יפה לאשה ויפה לולד, שמתוך כך נמצא הולד מלובן ומזורז.\u0004","ועוד בענין זה של התשמיש בזמן ההריון, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003המשמש מטתו ליום תשעים\u0004 לתחילת ההריון — \u0003כאילו שופך דמים.\u0004 ותוהים: \u0003מנא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע]\u0006 שיום זה הוא יום התשעים להריון? \u0003אלא אמר אביי:\u0004 הריהו \u0003משמש והולך\u0004 (וממשיך כדרכו), \u0003ו\"שמר פתאים ה' \"\u0004(תהלים קטז, ו).","ועוד בענין הלידה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה שותפין יש ב\u0004יצירת האדם, והם: \u0003הקדוש ברוך הוא, ואביו, ואמו.\u0004 ובדרך זה חלקו של כל אחד ואחד: \u0003אביו\u0004 — \u0003מזריע הלובן, שממנו\u0004 נוצרים ה\u0003עצמות, ו\u0004ה\u0003גידים, ו\u0004ה\u0003צפרנים, ו\u0004ה\u0003מוח שבראשו, ו\u0004חלק ה\u0003לובן שבעין.\u0004 \u0003אמו\u0004 — \u0003מזרעת אודם, שממנו\u0004 נוצרים ה\u0003עור, ו\u0004ה\u0003בשר, ו\u0004ה\u0003שערות, ו\u0004החלק ה\u0003שחור שבעין.\u0004 \u0003והקדוש ברוך הוא נותן בו רוח, ונשמה, וקלסתר פנים, וראיית העין, ושמיעת האוזן, ודבור פה, והלוך רגלים, ובינה, והשכל.\u0004","\u0003וכיון שהגיע זמנו להפטר מן העולם, הקדוש ברוך הוא נוטל\u0004 את \u0003חלקו\u0004 שלו, \u0003ו\u0004את חלק אביו ואמו, שהוא גופו הגשמי, \u0003מניח לפניהם\u0004 והריהו נשאר מת. ועל כך \u0003אמר רב פפא, היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים האנשים]\u0006 כפתגם עממי: \u0003פוץ מלחא\u0004 \u0005[השלך המלח]\u0006 המשמר את הבשר ומקיימו, \u0003ושדי בשרא לכלבא\u0004 \u0005[וזרוק הבשר לכלבים],\u0006 שמעתה אין לו עוד כל ערך.","ועוד בענין הלידה, \u0003דרש רב חיננא בר פפא: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \u0003\"עשה גדלות עד אין חקר ונפלאות עד אין מספר\"\u0004 (איוב ט, י) — \u0003בא וראה שלא כמדת\u0004 (דרך) \u0003הקדוש ברוך הוא מדת בשר ודם.\u0004 \u0003מדת בשר ודם, נותן חפץ\u0004 כלשהו \u0003ב\u0004תוך \u0003חמת\u0004 (נאד נוזלים), אפילו אם החמת \u0003צרורה\u0004 (קשורה) \u0003ופיה\u0004 (פתחה) מופנה \u0003למעלה\u0004 — הרי חפץ זה \u0003ספק משתמר\u0004 מפני האבידה, \u0003ספק אין משתמר.\u0004 \u0003ואילו הקדוש ברוך הוא, צר\u0004 את \u0003העובר\u0004 כשהוא נתון \u0003במעי אשה פתוחה, ופיה\u0004 מופנה \u0003למטה, ו\u0004בכל זאת \u0003משתמר\u0004 העובר!","\u0003דבר אחר: אדם נותן חפציו ל\u0004תוך \u0003כף מאזנים\u0004 לשקילה, \u0003כל זמן שמכביד\u0004 החפץ — כף המאזניים \u0003יורד למטה.\u0004 \u0003ואילו הקדוש ברוך הוא, כל זמן ש\u0004הולך ו\u0003מכביד הולד,\u0004 שהולך וגדל — כן \u0003עולה\u0004 הוא \u0003למעלה\u0004 במעי אמו.","ועוד בענייני העובר, דרש ר' י \u0003וסי הגלילי: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \u0003\"אודך (ה')\u0004 \u0003על כי נוראות נפליתי נפלאים מעשיך ונפשי ידעת מאד\"\u0004 (תהלים קלט, יד)? — \u0003בא וראה שלא כמדת\u0004 (דרך) \u0003הקדוש ברוך הוא מדת בשר ודם.\u0004 \u0003מדת בשר ודם, אדם נותן\u0004 (זורע) \u0003זרעונים\u0004 של מינים שונים \u0003בערוגה\u0004 אחת — \u0003כל אחת ואחת\u0004 מהזריעות הללו \u0003עולה ב\u0004התאם ל\u0003מינו\u0004 של הזרע שנזרע. \u0003ואילו הקדוש ברוך הוא צר העובר במעי אשה, וכולם\u0004 (זרע האב וזרע האם) \u0003עולין למין אחד\u0004 הנולד.","\u0003דבר אחר:\u0004 ה\u0003צבע נותן סמנין\u0004 (צמחי צביעה) \u0003ליורה\u0004 (סיר) — \u0003כולן עולין\u0004 (מתמזגים) \u0003ל\u0004כלל \u0003צבע אחד.\u0004 \u0003ואילו הקדוש ברוך הוא צר העובר במעי אשה, כל אחת ואחת עולה למינו.\u0004","ועוד בנפלאות הבורא, \u0003דרש רב יוסף: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \"ואמרת ביום ההוא \u0003אודך ה' כי אנפת בי ישב אפך ותנחמני\"\u0004 (ישעיה יב, א), \u0003במה הכתוב מדבר?\u0004","— \u0003בשני בני אדם שיצאו\u0004 ממקומם \u0003לסחורה.\u0004 \u0003ישב לו קוץ לאחד מהן\u0004 בגופו, וכתוצאה מכך לא יכול היה לצאת, בעוד שחבירו יצא \u0003התחיל\u0004 זה שנתחב בו הקוץ \u0003מחרף ומגדף\u0004 על שאירע לו כך. \u0003לימים שמע שטבעה ספינתו של חבירו בים,\u0004 ונמצא איפוא שבזכות אותו קוץ ניצל ממוות, \u0003התחיל מודה\u0004 (\"ואמרת ביום ההוא אודך ה' \") \u0003ומשבח\u0004 על הצער המועט שנגרם לו על ידי אותו קוץ (\"כי אנפת בי\"). \u0003לכך נאמר: \"ישב אפך ותנחמני\".\u0004","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר'\u0004 \u0003אלעזר: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \"ברוך ה' אלהים אלהי ישראל עושה נפלאות (גדולות) לבדו. \u0003וברוך שם כבודו לעולם\"\u0004 (תהלים עב, יח—יט) — \u0003אפילו בעל\u0004 (זה שנעשה לו) \u0003הנס אינו מכיר בנסו\u0004 (\"עושה נפלאות לבדו\").","ועוד בענייני לידה \u0003דריש\u0004 \u0005[דרש]\u0006 \u0003ר' חנינא בר פפא: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 \u0003\"ארחי ורבעי זרית וכל דרכי הסכנתה\"\u0004 (תהלים קלט, ג)? — \u0003מלמד שלא נוצר אדם מן כל הטפה, אלא\u0004 רק \u0003מן\u0004 החלק \u0003הברור שבה.\u0004 ובענין זה \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005] של\u0006 \u0003ר' ישמעאל: משל לאדם שזורה\u0004 את תבואתו \u0003בבית הגרנות,\u0004 שכך הוא נוהג: \u0003נוטל את האוכל, ומניח\u0004 (משאיר אחריו) \u0003את הפסולת.\u0004 וכך היא גם דרך יצירתו של העובר, שמן הטיפה נלקח רק החלק המועיל שבה.","ודברים אלו הריהם \u0003כ\u0004דבריו של \u0003ר' אבהו,\u0004 שכן \u0003ר' אבהו רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין הכתובים\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בשירת דוד במקום אחד \u0003\"ותזרני חיל\"\u0004 (שמואל ב כב, מ), ולשון \"תזרני\" כתובה בלי האות אל\"ף. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בשירה זו במקום אחר: \u0003\"האל המאזרני חיל\"\u0004 (תהלים יח, לג), הכוללת את האות אל\"ף (\"המאזרני\")? והסבר הדברים, שכך \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, זיריתני\u0004 (מחלק הברור שבטיפת הזרע) \u0003וזרזתני.\u0004","ועוד בענייני הלידה \u0003דרש ר' אבהו: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 בדברי בלעם \u0003\"מי מנה עפר יעקב ומספר את רבע ישראל\"\u0004 (במדבר כג, י)? — \u0003מלמד שהקדוש ברוך הוא יושב וסופר את רביעיותיהם\u0004 (ביאותיהם) \u0003של ישראל\u0004 וממתין \u0003מתי תבא טיפה שהצדיק נוצר הימנה.\u0004","\u0003ו\u0004מוסיפים: \u0003על דבר זה נסמית עינו של בלעם הרשע,\u0004 ש\u0003אמר: מי שהוא טהור וקדוש, ומשרתיו טהורים וקדושים, יציץ בדבר זה?!\u0004 וכעונש לכך \u0003מיד נסמית עינו, דכתיב\u0004 \u0005[שנאמר]\u0006 לאחר מכן \u0003\"נאם הגבר שתם העין\"\u0004 (שם כד, ג).","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הנאמר]\u0006 בלידת יששכר ליעקב ולאה \u0003\"וישכב עמה בלילה הוא\"\u0004 (בראשית ל, טז)? \u0003מלמד שהקדוש ברוך הוא סייע באותו מעשה.\u0004 ומנין אתה למד כן — \u0003ש\u0004כן \u0003נאמר: \"יששכר חמור גרם\"\u0004 (שם מט, יד) — \u0003חמור גרם לו ל\u0004לידת \u0003יששכר,\u0004 שהטה הקדוש ברוך הוא את חמורו של יעקב לכיוון אהלה של לאה, על מנת שיבוא אליה יעקב, ויוולד יששכר.","ובענייני הריון \u0003אמר ר'\u0004 \u0003יצחק, אמר ר'\u0004 \u0003אמי:\u0004 אם בשעת הזיווג ה\u0003אשה\u0004 היא ה\u0003מזרעת תחילה\u0004 — הרי היא \u0003יולדת זכר,\u0004 ואם ה\u0003איש\u0004 הוא ה\u0003מזריע תחילה\u0004 — הרי היא \u0003יולדת נקבה.\u0004 וראיה לדבר, \u0003ש\u0004כן \u0003נאמר: \"אשה כי תזריע וילדה זכר\"\u0004 (ויקרא יג, ב).","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בראשונה היו אומרים: אשה מזרעת תחילה\u0004 — \u0003יולדת זכר, איש מזריע תחלה\u0004 — \u0003יולדת נקבה, ולא פירשו חכמים את הדבר,\u0004 מנין נלמד. \u0003עד שבא ר'\u0004 \u0003צדוק ופירשו: \"אלה בני לאה אשר ילדה ליעקב בפדן ארם ואת דינה בתו\"\u0004 (בראשית מו, טו) — \u0003תלה הזכרים בנקבות\u0004 (\"בני לאה\") \u0003ונקבות בזכרים\u0004 (\"דינה בתו\").","ועוד בענין זה של לידת זכר או נקבה: נאמר \u0003\"ויהיו בני אולם אנשים גבורי חיל דרכי קשת ומרבים בנים ובני בנים\"\u0004 (דברי הימים א ח, מ). ויש לשאול: \u0003וכי בידו של אדם להרבות בנים ובני בנים? אלא מתוך\u0004"],["\u0003שמשהין עצמן בבטן,\u0004 ועוצרים בעדם מלהזריע, \u0003כדי שיזריעו נשותיהן תחלה,\u0004 ועל ידי כך גורמים הם \u0003שיהו בניהם\u0004 הנולדים להם \u0003זכרים\u0004 — \u0003מעלה עליהן הכתוב כאילו הם מרבים בנים ובני בנים.\u0004 \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רב קטינא: יכולני לעשות כל בני\u0004 (ילדי) \u0003זכרים,\u0004 על ידי שישהה עצמו מלהזריע, ותזריע אשתו בתחילה. ומביאים עוד אופן המביא להולדת בן זכר, \u0003אמר רבא: הרוצה לעשות כל בניו\u0004 (ילדיו) \u0003זכרים\u0004 — \u0003יבעול וישנה\u0004 (יבעל שנית).","","","","","\u0003ו\u0004עוד \u0003אמר ר'\u0004 \u0003יצחק, אמר ר'\u0004 \u0003אמי: אין אשה מתעברת אלא\u0004 בביאה שהיתה בזמן ה\u0003סמוך ל\u0004זמן וסתה. ומקור דבריו: \u0003ש\u0004כן \u0003נאמר\u0004 על ידי דוד \u0003\"הן בעוון חוללתי\"\u0004 (תהלים נא, ז). ומשמעו של \"עוון\" זה — שהיתה הביאה ממנו הרתה בו אמו, בסמוך לזמן וסתה (שאז אסורה היא הביאה, ועוון יש בה). שמתוך שהיתה הביאה בזמן זה, הרתה אמו של דוד. \u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 אין האשה מתעברת אלא בביאה שהיתה בזמן ה\u0003סמוך ל\u0004אחר ה\u0003טבילה.\u0004 ומקור לדבריו: \u0003ש\u0004כן \u0003נאמר\u0004 בהמשך אותו כתוב \u0003\"ובחטא יחמתני אמי\".\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה,\u0006 כיצד\u0005]\u0006 \u0003משמע דהאי\u0004 \u0005[ש\u0006לשון \u0005זו]\u0006 \u0003\"חטא\"\u0004 — \u0003לישנא דדכויי\u0004 \u0005[לשון טהרה]\u0006 \u0003הוא? דכתיב\u0004 \u0005[שנאמר]\u0006 בצרעת הבית \u0003\"וחטא את הבית\"\u0004 (ויקרא יד, נב), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]:\u0006 \u0003וידכי ית ביתא\u0004 \u0005[ויטהר את הבית].\u0006 \u0003ואי בעית\u0004 \u0005[ואם תרצה]\u0006 עוד ראיה שמשמעות \"חטא\" הינה טהרה, \u0003אימא מהכא\u0004 \u0005[אמור מכאן,\u0006 ממקרא זה\u0005]\u0006 הנאמר באותו פרק בתהלים (פסוק ט), \u0003\"תחטאני באזוב ואטהר\",\u0004 הרי איפוא ש\"חטא\" משמעו טהרה. \u0003ו\u0004מביאים עוד ממה ש\u0003אמר ר'\u0004 \u0003יצחק, אמר ר'\u0004 \u0003אמי\u0004 בענין לידה: \u0003כיון שבא\u0004 (נולד) \u0003זכר בעולם\u0004 — \u0003בא שלום בעולם.\u0004 ומקור לדברים: \u0003ש\u0004כן \u0003נאמר \"שלחו כר מושל ארץ\"\u0004 (ישעיה טז, א). ו\"כר\" זה הוא לשון מתנה שנותנים לשליט. ובענייננו — שלטון שקט ושלום. ואף המלה \u0003\"זכר\"\u0004 מורה כן, שהרי נשמע בה: \u0003זה כר.\u0004 \u0003ו\u0004עוד ממה ש\u0003אמר ר'\u0004 \u0003יצחק דבי\u0004 \u0005[\u0006חכם \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' אמי\u0004 בענין זה: כיון ש\u0003בא זכר בעולם\u0004 — הריהו \u0003בא\u0004 ו\u0003ככרו\u0004 (מזונותיו) \u0003בידו,\u0004 שכך מורה המלה \u0003\"זכר\"\u0004 — \u0003זה כר, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויכרה להם כרה גדולה\"\u0004 (מלכים ב ו, כג), ומשמעות \"כירה\" — סעודה.","ואילו כשבאה לעולם \u0003נקבה\u0004 — \u0003אין עמה כלום,\u0004 שכך מורה המלה \u0003\"נקבה\"\u0004 בדרך הנוטריקון — \u0003נקייה באה, עד דאמרה מזוני\u0004 \u0005[כל עוד\u0006 שאינה \u0005אומרת,\u0006 מבקשת \u0005מזונות]\u0006 — \u0003לא יהבי\u0004 \u0005[אין נותנים]\u0006 \u0003לה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדברי לבן ליעקב: \u0003\"נקבה שכרך עלי ואתנה\"\u0004 (בראשית ל, כח), ואחז בלשון \"נקבה\", להורות שרק משעה שיעקב ידרוש במפורש את שכרו, יקבלנו.","\u0003שאלו תלמידיו את ר'\u0004 \u0003שמעון בן יוחי: מפני מה אמרה תורה\u0004 כי ה\u0003יולדת מביאה קרבן? אמר להן:\u0004 משום ש\u0003בשעה ש\u0004האשה \u0003כורעת לילד,\u0004 ורבים מכאוביה, מתוך כך הריהי \u0003קופצת ונשבעת שלא תזקק\u0004 עוד \u0003לבעלה,\u0004 ולא תבוא עוד לייסורים שכאלה. \u0003לפיכך אמרה תורה תביא קרבן,\u0004 על שעברה על שבועתה, ושבה ונזקקה לבעלה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על תשובה זו\u0005]\u0006 \u0003רב יוסף: והא\u0004 \u0005[והרי]\u0006 \u0003מזידה היא\u0004 כשנשבעת שבועה זו, \u0003ובחרטה\u0004 (התרת השבועה) \u0003תליא מילתא\u0004 \u0005[תלוי הדבר]\u0006 אם היא שבה ונזקקת לבעלה. ואילו קרבן על שבועת ביטוי אין חייבים עליו אלא אם כן נעלם דבר השבועה מהנשבע, בשעה שעבר על שבועתו. \u0003ועוד\u0004 קשה, שהרי אם משום כך הוא — \u0003קרבן שבועה בעי איתויי\u0004 \u0005[צריכה להביא],\u0006 שהוא כשבה או שעירה, ולא עוף שהוא קרבן היולדת! \u0003ו\u0004עוד שאלו תלמידי ר' שמעון בן יוחאי את רבם בענין ימי טומאה שלאחר לידה: \u0003מפני מה אמרה תורה\u0004 כי מנין ימי הטומאה שלאחר לידת \u0003זכר\u0004 הם \u0003לשבעה\u0004 ימים בלבד, ולאחר מכן הריהי טהורה. \u0003ו\u0004אילו ימי טומאה לאחר לידת \u0003נקבה\u0004 הם \u0003לארבעה עשר\u0004 ימים? והשיב להם: טעם הדבר, שכן בלידת \u0003זכר שהכל שמחים בו\u0004 — הריהי \u0003מתחרטת\u0004 על שנשבעה שלא תזקק ותלד שוב, כבר \u0003לשבעה\u0004 ימים שלאחר הלידה. ואילו לאחר לידת \u0003נקבה שהכל עצבים בה\u0004 — אין היא \u0003מתחרטת\u0004 אלא \u0003לארבעה עשר\u0004 יום לאחר הלידה. \u0003ו\u0004עוד שאלו התלמידים את ר' שמעון בן יוחאי: \u0003מפני מה אמרה תורה מילה לשמונה\u0004 ימים, ולא לפני כן? והשיב להם: כדי \u0003שלא יהו כולם שמחים\u0004 בשמחת ברית המילה, \u0003ו\u0004אילו \u0003אביו ואמו\u0004 יהיו \u0003עצבים,\u0004 שהרי עדיין אסורים הם בתשמיש.","","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר'\u0004 \u0003מאיר אומר: מפני מה אמרה תורה\u0004 שה\u0003נדה\u0004 טמאה \u0003לשבעה\u0004 ימים ואסורה על בעלה? — \u0003מפני ש\u0004אם לא כן היה הדבר, והיתה אשתו מותרת לו תדיר, \u0003רגיל\u0004 היה \u0003בה\u0004 בעלה, \u0003ו\u0004משום כך היה בסופו של דבר \u0003קץ\u0004 (מואס) \u0003בה.\u0004 לכך \u0003אמרה תורה: תהא\u0004 האשה הנדה \u0003טמאה שבעה ימים,\u0004 ואסורה אז על בעלה, \u0003כדי שתהא חביבה על בעלה\u0004 לכשתיטהר מטומאתה \u0003כשעת כניסתה לחופה.\u0004","\u0003שאלו תלמידיו את ר'\u0004 \u0003דוסתאי בר' ינאי: מפני מה\u0004 דרך העולם הוא שה\u0003איש\u0004 הוא ה\u0003מחזר על אשה\u0004 לנושאה, \u0003ואין\u0004 ה\u0003אשה מחזרת על\u0004 ה\u0003איש?\u0004 השיב להם: \u0003משל לאדם שאבד לו אבידה, מי מחזר על מי?\u0004 — \u0003בעל אבידה מחזיר על אבידתו,\u0004 ואף האיש מחזר אחר הצלע שנלקחה ממנו. \u0003ו\u0004עוד שאלוהו התלמידים: \u0003מפני מה\u0004 בשעת התשמיש, ה\u0003איש\u0004 פונות \u0003פניו למטה, ו\u0004אילו ה\u0003אשה\u0004 פונות \u0003פניה למעלה כלפי האיש?\u0004 השיב להם: מפני ש\u0003זה\u0004 (האיש) מפנה פניו \u0003ממקום שנברא\u0004 ממנו, היא האדמה שמתחתיו. \u0003וזו\u0004 (האשה) מפנה פניה \u0003ממקום שנבראת\u0004 ממנו, מן האיש. \u0003ו\u0004עוד שאלוהו: \u0003מפני מה האיש מקבל פיוס\u0004 (קל לרצותו מכעסו), \u0003ואין אשה מקבלת פיוס?\u0004 השיב להם: מפני ש\u0003זה\u0004 (האיש) \u0003מ\u0004טבעו הריהו כטבע ה\u0003מקום שנברא\u0004 ממנו, היא האדמה שנוחה היא להיעבד. \u0003ו\u0004אילו \u0003זו\u0004 (האשה) \u0003מ\u0004טבעה הריהי כטבע ה\u0003מקום שנבראת\u0004 ממנו, הצלע, שקשה היא להיעבד כך.","","","ועוד שאלוהו: \u0003מפני מה אשה קולה ערב, ואין איש קולו ערב?\u0004 השיב להם: מפני ש\u0003זה\u0004 (האיש) \u0003מ\u0004טבעו הריהו כטבע ה\u0003מקום שנברא\u0004 ממנו, היא האדמה שאין היא משמעת קול בשעה שמכים אותה. \u0003ו\u0004אילו \u0003זו\u0004 (האשה) \u0003מ\u0004טבעה הריהי כטבע ה\u0003מקום שנבראת\u0004 ממנו, היא הצלע, שמשמיעה קול רם כאשר מקישים בה. וראיה לדבר, \u0003ש\u0004כן \u0003נאמר\u0004 בשבחיה של הרעיה: \"ענה דודי ואמר לי \u0003כי קולך ערב ומראיך נאוה\"\u0004 (שיר השירים ב, יד).","","\u0003בנות\u0004 ה\u0003כותים\u0004 נחשבות כ\u0003נדות מ\u0004זמן היותן מונחות ב\u0003עריסתן\u0004 (מיטת ילדותן). \u0003והכותים מטמאים\u0004 את המצע עליו הם שוכבים, ואף כמה מצעות, אם שוכבים הם על כמה מצעות זה על גבי זה. ודינו של ה\u0003משכב\u0004 ה\u0003תחתון\u0004 ששוכב עליו הכותי הריהו \u0003כ\u0004דינו של הבגד ה\u0003עליון\u0004 שעל גבי הזב, שזה וזה נחשבים כראשון לטומאה, והריהם מטמאים אוכלים ומשקים, אך לא אדם וכלים. וטעם הדבר שהם מטמאים, \u0003מפני שהן\u0004 הכותים נחשבים כ\u0003בועלי נדות, ו\u0004הסיבה לכך — משום ש \u0003הן\u0004 (נשותיהם) \u0003יושבות\u0004 שבעת ימי נדות \u0003על כל דם ודם,\u0004 ואף על דם שאינו מטמא בטומאת נדה. ועלול הדבר לגרום שבראותן דם טמא (בתוך ישיבתן על דם שאינו טמא) אין הן נוהגות בו כדם מטמא. ומשום כך, הריהן איפוא בגדר נדות, ובעליהם נחשבים כבועלי נדות.","","\u0003ואין\u0004 הלובשים את הבגדים ששכב עליהם הכותי \u0003חייבין\u0004 קרבן \u0003עליהן על ביאת מקדש,\u0004 אם נכנסו לאחר מכן למקדש. \u0003ו\u0004כן אם נגעו הבגדים הללו בתרומה, \u0003אין שורפין עליהם את התרומה,\u0004 וטעם הדבר: \u0003מפני שטומאתן\u0004 של הכותים הריהי מ\u0003ספק.\u0004 שנינו במשנתנו כי בנות הכותים נחשבות כנדות מעריסתן, ודנים בדבר: \u0003היכי דמי\u0004 \u0005[במה המדובר],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר בבנות \u0003דקא חזיין\u0004 \u0005[שהן רואות\u0006 דם\u0005]\u0006 — \u0003אפילו\u0004 בבנות \u0003דידן\u0004 \u0005[שלנו]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 כך הוא הדין, שהן נחשבות כנדות. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר בבנות \u0003דלא קחזיין\u0004 \u0005[שאין הן רואות]\u0006 — בנות \u0003דידהו\u0004 \u0005[שלהם]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תחשבנה כנדות!","","\u0003אמר רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא בר רב הונא אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]\u0006 \u0003בסתמא\u0004 \u0005[בסתם],\u0006 שאין אנו יודעים בהן אם רואות הן, ש\u0003כיון דאיכא מיעוטא דחזיין\u0004 \u0005[שיש מיעוט\u0006 בנות \u0005שרואות]\u0006 — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 בכל בנותיהם שראו. ומסבירים: \u0003ומאן\u0004 \u0005[ומיהו]\u0006 ה\u0003תנא\u0004 שהוא \u0003חייש למיעוטא\u0004 \u0005[חושש למיעוט]\u0006 —"],["\u0003ר' מאיר היא\u0004 שחושש למיעוט. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קטן\u0004 שמת אחיו בלא זרע \u0003וקטנה\u0004 שמת בעלה בלא זרע, \u0003לא חולצין ולא מיבמין,\u0004 שאין הקטן מייבם (נושא) את אלמנת אחיו (ואפילו היתה זו גדולה), ואינה חולצת נעלו כדין מי שאינו מייבם. וכן אם היתה האלמנה קטנה — אינה מתייבמת ואינה חולצת (אפילו לגדול), אלה \u0003דברי ר'\u0004 \u0003מאיר.\u0004","\u0003אמרו לו\u0004 חכמים \u0003לר' מאיר: יפה אמרת\u0004 בהלכה זו \u0003שאין חולצין\u0004 משום ש\u0003\"איש\" כתוב בפרשה\u0004 של מצות ייבום (\"ואם לא יחפוץ האיש לקחת את יבמתו... וחלצה נעלו מעל רגלו\". דברים כה, ז. שם ט), \u0003ומקשינן\u0004 \u0005[ומקישים אנו]\u0006 \u0003אשה\u0004 שנזכרה בפסוק זה \u0003לאיש\u0004 (\"את יבמתו\"), ולכן הקטן אינו חולץ והקטנה אינה נחלצת. \u0003ו\u0004אולם \u0003מה טעם אין מיבמין\u0004 הקטן או הקטנה?","\u0003אמר להן: קטן\u0004 — אינו מייבם את אשת אחיו, משום שיש לחשוש בו \u0003שמא ימצא\u0004 לאחר מכן שהוא \u0003סריס\u0004 שאינו מסוגל להוליד. וה\u0003קטנה\u0004 — אינה מתייבמת, משום שיש לחשוש בה \u0003שמא תמצא\u0004 לבסוף שהיא \u0003אילונית\u0004 שאינה יולדת, \u0003ונמצאו\u0004 איפוא שבמעשה הייבום (ביאה) הריהם \u0003פוגעין ב\u0004איסור \u0003ערוה\u0004 (הבא על אשת אחיו) \u0003שלא במקום מצוה\u0004 (ייבום), שהרי כל עיקרה נועד להעמיד זרע על שם האח שמת.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם סבורים? לדעתם \u0003זיל בתר רובא\u0004 \u0005[לך אחר רוב]\u0006 ה\u0003קטנים, ורוב\u0004 ה\u0003קטנים לאו\u0004 \u0005[לא]\u0006 \u0003סריסים נינהו\u0004 \u0005[הם],\u0006 וכמו כן \u0003זיל בתר רובא\u0004 \u0005[לך אחר רוב]\u0006 ה\u0003קטנות\u0004 — \u0003ורוב\u0004 ה\u0003קטנות לאו\u0004 \u0005[לא]\u0006 \u0003אילונית נינהו\u0004 \u0005[הן].\u0006 הרי שהחושש למיעוט הוא ר' מאיר.","ושואלים על כך: ושמא \u0003אימר\u0004 \u0005[אמור]\u0006 שמה ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' מאיר\u0004 שיש לחשוש למיעוט, הרי זה דווקא ב\u0003מיעוטא דשכיח\u0004 \u0005[מיעוט המצוי],\u0006 וכגון מיעוט זה של סריסים ואיילוניות, \u0003אבל מיעוטא\u0004 \u0005[מיעוט]\u0006 ש\u0003לא שכיח\u0004 \u0005[מצוי],\u0006 וכגון מיעוט בנות קטנות הרואות דם \u0003מי\u0004 \u0005[האם]\u0006 \u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את ר' מאיר שחושש הוא למיעוט שכזה?","ומשיבים: \u0003הא\u0004 \u0005[זה]\u0006 מספר הבנות הקטנות הרואות דם, \u0003נמי מיעוטא דשכיח\u0004 \u0005[גם כן מיעוט המצוי]\u0006 \u0003הוא.\u0004 וראיה לכך, ממה \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יוסי: מעשה\u0004 היה \u0003ב\u0004ישוב \u0003עין בול, והטבילוה\u0004 את התינוקת שנולדה זה עתה וראתה דם, \u0003קודם לאמה\u0004 (שילדתה) שטבלה (כדין כל היולדת נקבה) רק לאחר ארבעה עשר ימי טומאת לידה. \u0003ו\u0004כן \u0003אמר רבי: מעשה\u0004 היה \u0003ב\u0004ישוב \u0003בית שערים, והטבילוה\u0004 את התינוקת שנולדה וראתה דם, \u0003קודם לאמה,\u0004 שטבלה לאחר ארבעה עשר ימים מן הלידה. \u0003ו\u0004כן \u0003אמר רב יוסף: מעשה\u0004 היה \u0003ב\u0004עיר פומבדיתא שבבבל, \u0003והטבילוה קודם לאמה.\u0004 הרי מתוך עדויות אלה עולה שאף שמיעוט הוא שתראינה התינוקות דם, הרי זה מיעוט מצוי.","ושואלים על המסורות שהביאו: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 מדוע נצרכו להעיד כן \u0003ר' יוסי ו\u0004כן \u0003רבי\u0004 — \u0003משום תרומת ארץ ישראל,\u0004 שכן התרחשו מקרים אלה בארץ ישראל, ונגיעת הנדה פוסלת את תרומת ארץ ישראל. \u0003אלא\u0004 עדות זו שאמרה \u0003רב יוסף למה לי,\u0004 לאיזה ענין היא נצרכת, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר שמואל: אין תרומת חוץ לארץ אסורה\u0004 לטמא אותה \u0003אלא\u0004 רק \u0003במי שטומאה יוצאה מגופו,\u0004 וכגון הזב והזבה והנדה, \u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003באכילה\u0004 של התרומה, \u0003אבל בנגיעה\u0004 — \u0003לא.\u0004 וכיון שאין הנגיעה של הנדה פוסלת את תרומת חוצה לארץ, על איזה ענין העיד רב יוסף שתינוקת זו שבפומבדיתא היתה נדה?","\u0003אמר מר זוטרא: לא נצרכה\u0004 עדות רב יוסף \u0003אלא ל\u0004ענין ה\u0003סוכה\u0004 (הסך) \u0003שמן של תרומה\u0004 של חוץ לארץ, שכיון שהסיכה נחשבת כאכילה הריהי אסורה בטמאים אלה. ומנין שלענין תרומה הסיכה הריהי כאכילה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בענין איסור הטמאים לאכול בתרומה \u0003\"ולא יחללו את קדשי בני ישראל את אשר ירימו לה' \"\u0004(ויקרא כב, טו) — \u0003לרבות\u0004 אף \u0003את הסך ואת השותה\u0004 שהוא בכלל איסור זה.","ושואלים: הטמא ה\u0003שותה\u0004 מן התרומה \u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 המלמד שהוא חייב, והרי ה\u0003שתיה בכלל אכילה\u0004 היא? \u0003אלא\u0004 כך יש לגרוס בלשון הברייתא: \u0003לרבות את הסך\u0004 שיהא דינו \u0003כשותה.\u0004 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הבא ראיה שהסיכה הריהי כשתיה, \u0003מהכא\u0004 \u0005[מכאן],\u0006 שכך נאמר: \u0003\"ותבא כמים בקרבו וכשמן בעצמותיו\"\u0004 (תהלים קט, יח), הרי שהושוו השתיה והסיכה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא טעם הטומאה בבנות כותים, שחוששים אנו בהן למיעוט בנות הרואות, בבנות \u0003דידן נמי\u0004 \u0005[שלנו גם כן]\u0006 יהא נוהג הדין הזה, שהרי לשיטת ר' מאיר יש לחשוש למיעוט?","ומשיבים: \u0003אנן, דדרשינן\u0004 \u0005[אנו, שדורשים אנו]\u0006 את האמור במקרא \"ואשה כי תהיה זבה\" (ויקרא טו, יט), ולמדים אנו מדרשת הכתוב שלא נאמר \u0003\"אשה\"\u0004 אלא \u0003\"ואשה\"\u0004 ללמד שלא רק אשה גדולה הריהי בדין נדה, אלא אף התינוקת בכלל זה, \u0003ו\u0004משום כך \u0003כי חזיין, מפרשי להו\u0004 \u0005[כאשר רואות\u0006 התינוקות דם, הרינו \u0005מפרישים אותן\u0006 ונוהגים בהן כנדות\u0005]\u0006 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהן חכמים]\u0006 שתיחשבה נדות. \u0003אינהו\u0004 \u0005[הם,\u0006 הכותים\u0005],\u0006 ש\u0003לא דרשי\u0004 \u0005[דורשים]\u0006 דרשה זו \u0003\"אשה\" \"ואשה\", וכי חזיין, לא מפרשי להו\u0004 \u0005[וכאשר רואות\u0006 הן דם, \u0005אין מפרישים אותן\u0006 כדין הנדה\u0005]\u0006 — \u0003גזרו בהו רבנן\u0004 \u0005[בהן חכמים].\u0006","ומבררים עתה, \u0003מאי\u0004 \u0005[מהי\u0006 דרשה זו\u0005]\u0006 בכתוב \u0003\"אשה\" \"ואשה\"\u0004 שהוזכרה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 ממה שנאמר בכתוב \u0003\"אשה\"\u0004 — \u0003אין לי אלא אשה\u0004 גדולה שנוהגים בה דיני נדה, \u0003תינוקת בת יום אחד ל\u0004ענין דין ה\u0003נדה\u0004 שנוהגת אף בה \u0003מנין? תלמוד לומר: \"ואשה\".\u0004","ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 למדים אנו \u0003כי מרבי קרא\u0004 \u0005[כאשר מרבה הכתוב]\u0006 את התינוקות, אף את התינוקת \u0003בת יום אחד\u0004 הוא \u0003מרבי\u0004 \u0005[מרבה].\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה על כך ממה ששנינו\u0005]:\u0006 נאמר \"ואשה אשר ישכב איש אותה שכבת זרע ורחצו במים וטמאו עד הערב\" (שם פסוק יח). ומהכתוב \u0003\"אשה\"\u0004 — \u0003אין לי אלא אשה\u0004 גדולה שנחשבת ביאתה ביאה, \u0003תינוקת בת שלש שנים ויום אחד לביאה מנין\u0004 לנו שאף ביאתה נחשבת ביאה? \u0003תלמוד לומר: \"ואשה\"!\u0004","\u0003אמר רבא: הלכתא נינהו\u0004 \u0005[הלכות\u0006 למשה מסיני \u0005הן],\u0006 \u0003ואסמכינהו רבנן אקראי\u0004 \u0005[והסמיכון חכמים על מקראות],\u0006 ומבררים: \u0003הי קרא והי הלכתא\u0004 \u0005[מהו המקרא ומהי ההלכה\u0006 למשה מסיני\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שדין הנדות ב\u0003בת יום אחד\u0004 — \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005],\u0006 ואילו דין הביאה ב\u0003בת שלש שנים ויום אחד\u0004 \u0005[מקרא],\u0006 והרי \u0003קרא סתמא כתיב\u0004 \u0005[המקרא בסתם נאמר]!\u0006","\u0003אלא\u0004 דין הביאה ב\u0003בת שלש שנים ויום אחד\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 היא, ודין הנדות ב\u0003בת יום אחד\u0004 — \u0003קרא\u0004 \u0005[מקרא].\u0006 \u0003ומאחר דהלכתא\u0004 \u0005[שהלכה\u0006 למשה מסיני\u0005]\u0006 היא, \u0003קרא\u0004 \u0005[מקרא]\u0006 \u0003למה לי?\u0004"],["ומשיבים: בא כתוב זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003איש מ\u0004להיטמא בשכבת זרע בצבע \u0003אודם.\u0004","ושואלים: \u0003והא דתניא\u0004 \u0005[ו\u0006דרשה \u0005זו ששנויה\u0006 בברייתא\u0005]\u0006 על האמור \"ואשה כי יזוב זוב דמה ימים רבים\" (ויקרא טו, כה): מן האמור בכתוב \u0003\"אשה\"\u0004 — \u0003אין לי\u0004 שתהא בדין הזבה \u0003אלא\u0004 מי שהיא \u0003אשה\u0004 גדולה, ואולם מי שהיא \u0003בת עשרה ימים ל\u0004ענין דין ה\u0003זיבה מנין? תלמוד לומר \"ואשה\",\u0004 שבא הכתוב לרבות אף את זו. ואולם \u0003למה לי\u0004 דרשה זו? \u0003ליגמר\u0004 \u0005[תילמד]\u0006 דינה של בת עשרה ימים שהיא בכלל דין הזיבה \u0003מ\u0004דין התינוקת בת יום אחד שהיא בכלל ה\u0003נדה!\u0004 שהרי אין זיבה אלא לאחר נדה, וכיון שעברו שבעת ימי נדה ושלושה ימים של זיבה על תינוקת זו הרי היא זבה, ונמצא איפוא שבת עשרה ימים הריהי בכלל זיבה!","ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה]\u0006 דרשה זו, שכן מדין התינוקת שהיא נדה בת יום אחד, לא ניתן ללמוד הלכה זו. משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק את הדין \u0003בנדה\u0004 שנוהג בתינוקת בת יום אחד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי הוא דווקא בענין ה\u0003נדה\u0004 — \u0003משום\u0004 שדינה של הנדה חמור, \u0003דכי חזאי חד יומא בעיא למיתב\u0004 \u0005[שכאשר\u0006 היא \u0005רואה יום אחד, צריכה\u0006 היא \u0005לשבת]\u0006 \u0003שבעה\u0004 ימים של נדות. \u0003אבל זבה,\u0004 שדינה קל, \u0003דאי חזאי חד יומא\u0004 \u0005[שאם ראתה זיבה\u0006 \u0005יום אחד]\u0006 — אין היא נחשבת אלא ל\"זבה קטנה\", ו\u0003בשומרת יום כנגד יום\u0004 (ששומרת יום אחד בטהרה כנגד יום הטומאה, שטובלת למחרת היום הטמא, ואם אינה רואה בו דם, הריהי טהורה) \u0003סגי\u0004 \u0005[די]\u0006 \u0003לה, אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 נוהג בקטנה דין זה — לכן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 דרשה זו לדין הזבה.","ושואלים מן הצד האחר: \u0003וליכתוב רחמנא\u0004 \u0005[ותכתוב התורה]\u0006 רק דין זה \u0003בזבה,\u0004 שנוהגת אף בתינוקת בת עשרה ימים, \u0003ולא בעי\u0004 \u0005[צריך]\u0006 כתוב נוסף ללמדנו \u0003בנדה,\u0004 שתינוקת בת יום אחד הריהי בכלל זה, \u0003ואנא ידענא\u0004 \u0005[ואני אדע]\u0006 דין זה בנדה, שהרי \u0003אין\u0004 דין זבה בלא נדה, וכיון שתינוקת בת עשרה ימים הריהי זבה, מובן שתינוקת בת יום אחד הריהי נדה! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, אכן גם כן]\u0006 ניתן ללמוד את דין התינוקת בת יום אחד שראתה דם שהיא נדה מדין התינוקת בת עשרה ימים הזבה, \u0003ואלא קרא\u0004 \u0005[הכתוב]\u0006 \"ואשה\" האמור בדין הנדה \u0003למה לי,\u0004 ומה הוא מלמדנו? \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003איש מאודם.\u0004","ושואלים על כך: \u0003הא מיעטתיה חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005מיעטתו\u0006 התורה \u0005פעם אחת]!\u0006 ומשיבים: \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 איש \u0003מ\u0004טומאת \u0003שכבת זרע\u0004 שצבעה אדום, \u0003וחד\u0004 וכתוב \u0005אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 איש \u0003מ\u0004טומאת \u0003דם\u0004 היוצאת מפי האמה, שאין הוא נטמא בה כזב.","לאחר שנדון דין טומאת הנדה בתינוקת בת יום אחד, דנים בדין הזכר לענין טומאת זיבה: \u0003וכן לענין זכרים,\u0004 שהם נטמאים בראיית זיבה אף בקטנותם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בדין הזב: \u0003\"איש איש\u0004 כי יהיה זב מבשרו זובו טמא הוא\" (ויקרא טו, ב). ודנים בכפל לשון זו, \u0003מה תלמוד לומר\u0004 (איזה לימוד משמיענו) הביטוי \u0003\"איש איש\"? לרבות תינוק בן יום אחד, ש\u0004אף \u0003הוא מטמא בזיבה,\u0004 אלו \u0003דברי ר'\u0004 \u0003יהודה.\u0004","\u0003ר'\u0004 \u0003ישמעאל בנו של ר'\u0004 \u0003יוחנן בן ברוקה אומר: אין צריך\u0004 לדרשה זו כדי להשמיענו דין זה, ש\u0003הרי הוא\u0004 הכתוב \u0003אומר\u0004 בסוף פרשת הטמאים: \"והדוה בנדתה והזב את זובו \u0003לזכר ולנקבה\u0004 ולאיש אשר ישכב עם טמאה\" (שם לג), ומהלשון הכוללת \u0003\"לזכר\"\u0004 — יש ללמוד שאמורים הדברים ב\u0003כל שהוא זכר, בין שהוא גדול בין שהוא קטן.\u0004 וכמו כן מהלשון הכוללת \u0003\"ולנקבה\"\u0004 יש ללמוד שאמורים הדברים ב\u0003כל שהיא נקבה, בין גדולה בין קטנה.\u0004 \u0003אם כן מה תלמוד לומר\u0004 (איזה לימוד משמיענו) הביטוי \u0003\"איש איש\"? דברה תורה כלשון בני אדם,\u0004 ואין הוא מלמד דבר.","ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 למדים אנו \u0003כי מרבי קרא\u0004 \u0005[כאשר מרבה הכתוב]\u0006 את הזכרים התינוקות, אף את התינוק שהוא \u0003בן יום אחד מרבי\u0004 \u0005[מרבה].\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה על כך ממה ששנינו\u0005]\u0006 על האמור בזכרים בטומאת שכבת זרע היוצאת מהם \"ואיש כי תצא ממנו שכבת זרע ורחץ במים את כל בשרו וטמא עד הערב\" (שם טז): מן הלשון \u0003\"איש\" אין לי אלא\u0004 מי שהוא בגדר \u0003איש,\u0004 שהוא גדול, מי שיצאה ממנו שכבת זרע והוא \u0003בן תשע שנים ויום אחד מנין\u0004 שאף הוא בכלל טומאה זו? \u0003תלמוד לומר: \"ואיש\",\u0004 והרי ש\"איש\" אינו מלמד על בן יום אחד!","\u0003אמר רבא: הלכתא נינהו\u0004 \u0005[הלכות\u0006 למשה מסיני \u0005הן],\u0006 \u0003ואסמכינהו רבנן אקראי\u0004 \u0005[והסמיכון חכמים על מקראות], ומבררים:\u0006 \u0003הי הלכתא והי קרא\u0004 \u0005[מהי ההלכה\u0006 למשה מסיני ומהו המקרא\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שדין הזבות ב\u0003בן יום אחד\u0004 — \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005],\u0006 \u0003ו\u0004אילו דין טומאת שכבת זרע ב\u0003בן תשע שנים ויום אחד\u0004 \u0005[מקרא],\u0006 והרי \u0003קרא סתמא כתיב\u0004 \u0005[המקרא בסתם נאמר]\u0006 בלי ציון גיל, ומשמע אפילו בן יומו!","\u0003אלא\u0004 דין שכבת הזרע ב\u0003בן תשע שנים ויום אחד\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 היא, ודין הזיבה ב\u0003בן יום אחד\u0004 — \u0003קרא\u0004 \u0005[מקרא]\u0006 הוא. ושואלים: \u0003וכי מאחר\u0004 שדין שכבת הזרע בבן תשע שנים ויום אחד \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 \u0003היא,\u0004 ואינו נלמד מן הכתוב, אם כן \u0003קרא\u0004 \u0005[הכתוב]\u0006 \u0003למה לי,\u0004 מה הוא משמיענו? ומשיבים: הכתוב בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003אשה מ\u0004טומאת זיבה בצבע \u0003לובן.\u0004","ושואלים: \u0003למה לי למכתב\u0004 \u0005[לכתוב]\u0006 \u0003בזכרים\u0004 ללמד שבכלל הזיבה אף התינוק בן יומו, \u0003ולמה לי למכתב\u0004 \u0005[לכתוב]\u0006 \u0003בנקבות\u0004 דרשה הבאה ללמד שבכלל הנדה אף התינוקת בת יום אחד ובכלל הזיבה אף התינוקת בת עשרה ימים, ואין האחד נלמד מן האחר?","ומשיבים: \u0003צריכי\u0004 \u0005[נצרכות]\u0006 הן שתי הדרשות, משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 לימוד זה רק \u0003בזכרים,\u0004 הייתי אומר כי דין זה נוהג בזכרים בלבד, \u0003משום\u0004 שחמור דינם, \u0003דמטמאו\u0004 \u0005[ש\u0006כן \u0005נטמאים]\u0006 הם בזיבה אף \u0003ב\u0004שלוש \u0003ראיות\u0004 ביום אחד, \u0003כב\u0004 טומאת זיבה בראיית שלוש ראיות בשלושה \u0003ימים\u0004 רצופים. \u0003אבל נקבות דלא מטמאו\u0004 \u0005[ש\u0006כן \u0005אינן נטמאות]\u0006 \u0003ב\u0004שלוש \u0003ראיות\u0004 ביום אחד \u0003כב\u0004 ראיית שלושה \u0003ימים\u0004 — שמא \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 תהיה אף התינוקת בת עשרה ימים בדין הזבה.","\u0003ו\u0004מן הצד האחר, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 לימוד זה רק \u0003בנקבות,\u0004 הייתי אומר כי דין זה נוהג רק בנקבות \u0003משום\u0004 שיש בהן צד חומרה \u0003דקמטמו\u0004 \u0005[ש\u0006כן \u0005הן נטמאות]\u0006 אף בזיבה הבאה \u0003באונס.\u0004 \u0003אבל זכרים דלא מטמאו\u0004 \u0005[ש\u0006כן \u0005אינם נטמאים]\u0006 בזיבה הבאה \u0003באונס\u0004 — \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 יהיו בכלל הזבים אף התינוקות בני יום אחד. ולכן \u0003צריכא\u0004 \u0005[צריכות]\u0006 שתיאמרה שתי הדרשות הללו.","שנינו במשנתנו כי \u0003הכותים מטמאין משכב תחתון כעליון.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הכוונה\u0005]\u0006 בביטוי זה \u0003\"משכב תחתון כעליון\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003עשרה מצעות\u0004 זה על גבי זה \u0003ויתיב עלייהו\u0004 \u0005[וישב עליהם]\u0006 הכותי — \u0003מטמו להו\u0004 \u0005[נטמאו להם]\u0006 כל המצעות בישיבתו זו עליהם, ואף התחתון בכללם — והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא דבר זה, ואין צורך להשמיענו אותו, שכיון שנחשבים הכותים כבועלי נדות ולכך הם מטמאים משכבם, אף המשכב התחתון בכלל זה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003דרס\u0004 (לחץ) \u0003להו\u0004 \u0005[אותם,\u0006 את כל המצעות הללו\u0005]\u0006 בישיבתו עליהם!","\u0003אלא\u0004 כוונת הלשון: \u0003שיהא\u0004 דינו של \u0003תחתונו\u0004 (המצע התחתון, שאינו נוגע בו) \u0003של בועל נדה כ\u0004דינו של \u0003עליונו\u0004 (בגדים שעליו) \u0003של זב,\u0004 ולא כתחתונו של הזב. \u0003מה עליונו של זב\u0004 — אינו אב הטומאה, ו\u0003אינו מטמא אלא אוכלין ומשקין,\u0004 אבל לא אדם וכלים, \u0003אף תחתונו של\u0004 הכותי שגזרו בו שיהא נחשב כ\u0003בועל נדה,\u0004 דינו כראשון לטומאה ו\u0003אינו מטמא אלא אוכלין ומשקין,\u0004 ולא אדם וכלים.","ושואלים: \u0003עליונו של זב מנלן\u0004 \u0005[מנין לנו]\u0006 שאינו מטמא אלא אוכלים ומשקים? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדינו של הזב: \u0003\"וכל הנגע בכל אשר יהיה תחתיו יטמא\"\u0004 (ויקרא טו, י), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"תחתיו\"?\u0004"],["\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבא פסוק זה להשמיענו שמה שמ \u0003תחתיו\u0004 של ה\u0003זב\u0004 טמא — דין זה \u0003מ\u0004הנאמר \u0003\"ואיש אשר יגע במשכבו\"\u0004 (שם ה) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 \u0003אלא\u0004 כוונת הכתוב היא לזה \u0003הנוגע בכל אשר יהיה הזב תחתיו, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 הדבר שהזב תחתיו — זה \u0003עליון\u0004 (מה שעליו, הבגד) \u0003של זב,\u0004 שאף הוא מטמא.","והנאמר בהמשך הפסוק \u0003\"והנושא\u0004 אותם... וטמא עד הערב\" \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר עליו בכתוב ש\u0003יטמא, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — זה ה\u0003נישא\u0004 על הזב, \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור דין זה\u0005]\u0006 שכן בכתוב זה \u0003\"והנשא\" כתיב\u0004 \u0005[נאמר],\u0006 כאומר: אף הנישא על הזב הריהו טמא.","\u0003נתקו\u0004 (הוציאו) \u0003הכתוב\u0004 את דין עליונו של זב \u0003מ\u0004כלל \u0003טומאה חמורה והביאו לידי טומאה קלה, לומר לך שאינו מטמא\u0004 אדם וכלים \u0003אלא אוכלין ומשקין\u0004 בלבד.","ושואלים על כך: \u0003אימר\u0004 \u0005[אמור]\u0006 בדרך אחרת כיצד ניתק עליונו של זב מטומאה חמורה לטומאה קלה, ובאופן זה: \u0003נתקו הכתוב\u0004 את עליונו של זב \u0003מ\u0004כלל ט \u0003ומאה חמורה\u0004 — ש\u0003לא מטמא אדם לטמא בגדים\u0004 שעל אותו אדם, \u0003אבל אדם או בגדים ליטמא\u0004 \u0005[שיטמא]\u0006 עליונו של זב? ומשיבים: אין לומר כן, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"יטמא\"\u0004 — ולשון זו \u0003טומאה קלה משמע.\u0004","שנינו במשנתנו כי הכותים נחשבים כבועלי נדות, ומשום כך הריהם מטמאים משכב תחתון. ומבררים: \u0003ו\u0004עצם דין זה שתחתונו של בועל נדה מטמא משכב תחתון \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בפרשת הנדה \"ואם שכוב ישכב איש אותה \u0003ותהי נדתה עליו\u0004 וטמא שבעת ימים וכל המשכב אשר ישכב עליו יטמא\" (שם כד).","\u0003יכול\u0004 כוונת הכתוב \"ותהי נדתה עליו\" שיחולו עליו דיניה, כגון שאם בא עליה ביום הששי לימי נדתה, והרי היא טובלת למחרת, אף הוא \u0003יעלה\u0004 (יטבול לטהרתו) \u0003לרגלה\u0004 (לסוף טומאתה), למחרת? לכך \u0003תלמוד לומר\u0004 (משמיענו) המשך הכתוב שאינו כן, אלא כל הבועל את הנדה \u0003\"\u0004\u0003יטמא שבעת ימים\",\u0004 ואפילו בא עליה ביום השביעי לנדתה.","\u0003ו\u0004אם כן יש לשאול: \u0003מה תלמוד לומר\u0004 הכתוב \u0003\"ותהי נדתה עליו\"?\u0004 \u0003שיכול\u0004 הייתי לומר ש\u0003לא יטמא\u0004 הבועל נדה \u0003אדם וכלי חרס\u0004 — לכך \u0003תלמוד לומר\u0004 (משמיענו) הכתוב \u0003\"ותהי נדתה עליו\",\u0004 שדינו של הבועל נדה כדין הנדה, ו\u0003מה היא\u0004 הנדה \u0003מטמאה אדם וכלי חרס\u0004 — \u0003אף הוא\u0004 הבועל נדה \u0003מטמא אדם וכלי חרס.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 שווה היא טומאת הבועל נדה לטומאת הנדה עצמה, שמא נאמר כך: \u0003מה היא\u0004 הנדה \u0003עושה משכב ומושב לטמא אדם לטמא בגדים\u0004 שעליו, \u0003אף הוא\u0004 הבועל נדה \u0003עושה משכב ומושב לטמא אדם לטמא בגדים\u0004 שעליו — לכך \u0003תלמוד לומר \"וכל המשכב אשר ישכב עליו יטמא\",\u0004 שאין הבועל נדה מטמא אדם וכלי חרס.","וכך נלמד הדבר מן הכתוב: \u0003ש\u0004הרי \u0003אין תלמוד לומר\u0004 (משמיענו) הפסוק \"\u0003וכל המשכב אשר ישכב עליו יטמא\"\u0004 דבר, שכן כבר נאמר \"ותהי נדתה עליו\" וכמו שהנדה מטמאה משכבה, אף הוא מטמא משכבו. \u0003ו\u0004אם כן \u0003מה תלמוד לומר\u0004 (משמיענו) פסוק זה \u0003\"וכל המשכב אשר\u0004 ישכב עליו יטמא\" — ללמדנו ש\u0003נתקו\u0004 (שהוציאו) \u0003הכתוב\u0004 את הבועל נדה \u0003מ\u0004כלל דין \u0003טומאה חמורה\u0004 כנדה עצמה, \u0003והביאו לידי טומאה קלה, לומר לך שאינו מטמא אלא אוכלין ומשקין.\u0004","\u0003פריך\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אחאי: אימא\u0004 \u0005[אמור]\u0006 אחרת כיצד ניתק דינו של בועל נדה מכלל טומאה חמורה לטומאה קלה, ובאופן זה: \u0003נתקו הכתוב\u0004 את דינו של בועל נדה \u0003מ\u0004כלל \u0003טומאה חמורה\u0004 של טומאת הנדה \u0003והביאו לטומאה קלה\u0004 — ש\u0003לא ליטמא\u0004 \u0005[יטמא]\u0006 בועל הנדה \u0003אדם לטמויי\u0004 \u0005[לטמא]\u0006 \u0003בגדים\u0004 שעל אותו אדם, \u0003אבל אדם ובגדים\u0004 שנגע בהם ישירות \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 בועל נדה? \u0003אמר רב אסי:\u0004 אין לומר כן, משום שלשון זו \u0003\"יטמא\"\u0004 האמורה בכתוב — \u0003טומאה קלה משמע.\u0004","ושואלים עוד: \u0003אימא\u0004 \u0005[אמור]\u0006 כך בפסוק זה: \u0003\"ותהי נדתה עליו\u0004 וטמא שבעת ימים\" — הרי זה \u0003כלל\u0004 (שכל דיני טומאת הנדה חלים בבועל הנדה), \u0003\"וכל המשכב\u0004 אשר ישכב עליו יטמא\" — הרי זה \u0003פרט\u0004 (שרק לענין המשכב מטמא בועל הנדה כנדה). והרי מן המידות שהתורה נדרשת בהן היא שכל שיש בו \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט.\u0004 ואף בענייננו נאמר: בטומאת בועל הנדה \u0003משכב ומושב\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מטמא, ואילו \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא\u0004 מטמא!","\u0003אמר אביי:\u0004 אין לומר כן, משום שהכתוב בפסוק \u0003\"יטמא שבעת ימים\"\u0004 האמור בין \"ותהי נדתה עליו\" שהוא כלל ובין \"וכל המשכב אשר ישכב\" שהוא פרט, \u0003מפסיק הענין,\u0004 ומעתה \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כלל ופרט המרוחקין זה מזה, וכל כלל ופרט המרוחקין זה מזה\u0004 — \u0003אין דנין אותו בכלל ופרט.\u0004","\u0003רבא אמר\u0004 הסבר אחר: \u0003לעולם דנין\u0004 אף בכלל ופרט המרוחקים זה מזה, ואולם לענייננו אין לומר שתהיה טומאת בועל הנדה רק לענין המשכב, משום שהכתוב בפסוק \u0003\"וכל\u0004 המשכב\" — \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 ולמדים ממנו אף לטומאות אחרות של בועל הנדה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על לימוד בועל נדה מהשוואתו לנדה\u0005]\u0006 \u0003ר' יעקב: אימא\u0004 \u0005[אמור]\u0006 מעתה שיהא דינו של הבועל נדה \u0003כהיא,\u0004 כנדה. ו\u0003מה היא\u0004 הנדה — \u0003לא חלקת בה בין מגעה למשכבה,\u0004 לענין \u0003לטמא אדם ולטמא בגדים,\u0004 \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שהרי הן במגעה והן במשכבה נטמאים אלו. \u0003אף הוא\u0004 הבועל נדה — \u0003לא תחלוק בו בין מגעו למשכבו, לטמא אדם ולטמא בגדים לקולא\u0004 \u0005[להקל],\u0006 שהן במשכבו והן במגעו לא יטמא אדם לטמא בגדים!","\u0003אמר רבא:\u0004 אין לומר כן, משום שהלשון \"ותהי נדתה \u0003עליו\"\u0004 האמור בכתוב — \u0003להטעינו\u0004 (להכביד, להחמיר עליו) \u0003משמע.\u0004","שנינו במשנתנו בטעם טומאתם של הכותים \u0003מפני שהן\u0004 נחשבים כ\u0003בועלי נדות\u0004 מפני שנשותיהם נוהגות בעצמן דין נדות על כל דם שהן רואות. ושואלים: \u0003אטו כולהו\u0004 \u0005[האם כולם,\u0006 כל הכותים\u0005]\u0006 \u0003בועלי נדות נינהו\u0004 \u0005[הם],\u0006 והרי אלו שביניהם שאינם נשואים, אינם בכלל זה? \u0003אמר ר'\u0004 \u0003יצחק מגדלאה:\u0004 רק \u0003ב\u0004כותים שלהם יש נשים ה\u0003נשואות\u0004 להם \u0003שנו\u0004 במשנתנו הלכה זו.","\u0003ו\u0004עוד שנינו במשנתנו בטעם היות הכותים נחשבים לבועלי נדות: מפני ש\u0003הן\u0004 (נשותיהם) \u0003יושבות על\u0004 כל \u0003דם\u0004 ודם שהן רואות. ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003מאיר: אם הן\u0004 נשות הכותים היו \u0003יושבות על כל דם ודם\u0004 שהן רואות, שבעה ימים של נדות — \u0003תקנה גדולה היא להן,\u0004 שאין מזה קלקול.","\u0003אלא\u0004 שיש חשש אחר, \u0003ש\u0004אם התחילו למנות שבעה ימי נדות על דם שאינו טמא, כיון ש\u0003רואות\u0004 הן \u0003דם אדום\u0004 שהוא דם טמא, בתוך שבעת הימים הללו — אין הן מתחילות למנות מעתה מנין שבעה ימי נדות, כדין, אלא רואות אותו כדם הבא בתוך ימי שבעת הימים \u0003ומשלימות אותו\u0004 למנין שבעת הימים \u0003לדם\u0004 ה\u0003ירוק.\u0004 ונמצאות שטובלות הן בתוך שבעת ימי נדותן (בשל הדם האדום שראו), ואינן יוצאות מידי טומאתן.","\u0003דבר\u0004 (טעם) \u0003אחר\u0004 מדוע נחשבות הכותיות כטמאות, משום שבאותו \u0003יום שפוסקת בו\u0004 לאחר שראתה זיבה לאחר ימי נדתה, והריהי נחשבת איפוא זבה, היא \u0003סופרתו למנין שבעה\u0004 ימים של זיבה, ואין היא סופרת שבעה ימים שלמים של זיבה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רמי בר חמא: ו\u0004אכן \u0003תספרנו\u0004 לאותו היום, \u0003ואנן נמי ניספריה\u0004 \u0005[ואנו\u0006 בני ישראל \u0005גם כן נספרנו]\u0006 לאותו יום כיום ראשון לשבעת ימי זיבה, \u0003דקיימא לן\u0004 \u0005[ש\u0006הרי \u0005מקובל לנו]\u0006 הכלל ש\u0003מקצת היום\u0004 נחשב \u0003ככולו!\u0004","\u0003אמר רבא\u0004 בתשובה: אין לספור מקצת יום זה של זיבה ככל היום, משום ש\u0003אם כן\u0004 עושים, דין הזב שמתחיל לספור וראה קרי שלמדנו שאינו סותר אלא אותו היום בלבד (לעיל כב,א), ומעתה \u0003שכבת זרע דסתר\u0004 \u0005[שסותר]\u0006 את מנין אותו היום בלבד \u0003בזיבה היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה\u0006 אפשרות\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003מקצת היום\u0004 שלאחר שראה את שכבת הזרע הריהו \u0003ככולו,\u0004 ומדוע יסתור אותו היום?","ודוחים: \u0003אי דחזאי בפלגא דיומא\u0004 \u0005[אם שראה\u0006 הזב את שכבת הזרע \u0005באמצע היום],\u0006 שנותר עוד מקצת היום לפניו — \u0003הכי נמי\u0004 \u0005[אכן כן]\u0006 אין הוא סותר אותו היום, ויעלה לו מקצת היום ככולו. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דחזאי\u0004 \u0005[שראה]\u0006 הזב שכבת זרע ב\u0003סמוך לשקיעת החמה,\u0004 שאין עוד מקצת היום לפניו, שייחשב ככולו.","ושואלים על כך: \u0003וליקום ולימא ליה לקרא\u0004 \u0005[ו\u0006כי נכון הוא \u0005שיעמוד\u0006 חכם וידחוק \u0005ויאמר על הפסוק],\u0006 \"זאת תורת הזב ואשר תצא ממנו שכבת זרע לטמאה בה\" (ויקרא טו, לב) שממנו למדנו כי הזב הרואה שכבת זרע סותר יום אחד: \u0003כי כתיבא\u0004 \u0005[כאשר אמור]\u0006 פסוק זה — דווקא בשראה הזב שכבת זרע ב\u0003סמוך לשקיעת החמה כתיבא\u0004 \u0005[\u0006הוא \u0005שאמור]?\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003על כרחך שבקיה לקרא\u0004 \u0005[הניחו לכתוב]\u0006 והוציאנו ממובנו הפשוט, להעמידו באופן זה דווקא, משום \u0003דאיהו דחיק ומוקי אנפשיה\u0004 \u0005[שהוא דחוק\u0006 ונאלץ \u0005להעמידו בעצמו]\u0006 באופן זה דווקא.","מתוך שנדון עניינו של הזב שראה שכבת זרע הסותר יום אחד ממנין ימי זיבתו מביאים מה ש\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 האשה ה\u0003פולטת שכבת זרע\u0004 לאחר ששימשה עם בעלה \u0003מהו\u0004 דינה לענין זה \u0003שתסתור ב\u0004כך את מנין \u0003זיבה?\u0004 וצדדי השאלה: מן הצד האחד, האם טעם הדין שפליטת שכבת זרע מטמאת כרגיל את האשה הוא משום ש\u0003רואה היתה,\u0004 שראיית שכבת הזרע היא המטמאת, ובדומה לאיש הרואה שכבת זרע, \u0003ו\u0004לכך אף היא \u0003סותרת\u0004 מנין ימי זיבתה."],["\u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר כי טעם הדבר הוא משום ש\u0003נוגעת היתה\u0004 בשכבת הזרע שפלטה — \u0003ולא סתרה\u0004 \u0005[ואינה סותרת]\u0006 את מנין ימי זיבתה בכך, שאף האיש הזב הנוגע בשכבת זרע אינו סותר מניינו.","\u0003אמר רבא\u0004 על בעייתו זו של רמי בר חמא: \u0003לפום חורפא\u0004 — \u0003שבשתא\u0004 \u0005[לפי החריפות — השיבוש],\u0006 שכן אין זו בעיה כלל, שהרי \u0003נהי נמי דסתרה\u0004 \u0005[גם כן\u0006 אם אמנם סותרת] הזבה הפולטת שכבת זרע את מניינה, ברם \u0003כמה תסתור?\u0004 אם \u0003תסתור\u0004 את כל \u0003שבעה\u0004 ימי ספירתה — אין זה נכון, שהרי \u0003דיה\u0004 שיהא דינה לענין הסתירה \u0003כבועלה,\u0004 כלומר, כאיש זב הפולט שכבת זרע שסותר יום אחד בלבד!","ואם נאמר ש\u0003תסתור יום אחד\u0004 בלבד — והרי בטהרת האשה הזבה \"ואם טהרה מזובה וספרה לה שבעת ימים \u0003ואחר תטהר\"\u0004 (ויקרא טו, כח), \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003\"אחר\"\u0004 בא ללמד — \u0003אחר לכולן,\u0004 לכל ימי טהרתה כאחד, שיהיו אלה שבעת ימי טהרה רצופים, \u0003שלא תהא טומאה מפסקת ביניהם!\u0004 הרי שאין כל אופן שבו תסתור האשה הזבה את ימי ספירתה ליום אחד, ואין מקום לבעייתו של רמי בר חמא.","ושואלים לשיטת רבא: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך זו\u0005],\u0006 אף האיש ה\u0003זב\u0004 שראה שכבת זרע \u0003גופיה\u0004 \u0005[עצמו],\u0006 \u0003היכי סתר\u0004 \u0005[כיצד\u0006 הוא \u0005סותר]\u0006 את מנין ימי זיבתו ליום אחד, והרי בטהרת האיש הזב \"וכי יטהר הזב מזובו וספר לו שבעת ימים \u0003לטהרתו\u0004 וכבס בגדיו ורחץ בשרו במים חיים וטהר\" (שם יג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ולימדנו הכתוב \"שבעת ימים לטהרתו\" שיהיו אלה שבעה ימים רצופים, \u0003שלא תהא טומאה מפסקת ביניהן!\u0004","\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 בכוונת דין זה — \u0003שלא תהא טומאת זיבה מפסקת ביניהן, הכא נמי\u0004 \u0005[כך גם כן\u0006 בדין האשה הזבה\u0005]\u0006 דין ימי טהרתה הוא \u0003שלא תהא טומאת זיבה מפסקת ביניהן,\u0004 ואין בכלל זה סתירת יום אחד בגלל פליטת שכבת זרע. ובעיית רמי בר חמא במקומה עומדת.","ועוד שנינו במשנתנו בדין הכותים: \u0003ואין חייבין\u0004 קרבן \u0003עליהן,\u0004 שהלובש בגדיהם ונכנס לבית המקדש אינו כעובר \u0003על\u0004 איסור \u0003ביאת מקדש\u0004 בטומאה, וכן אין שורפים תרומה שנגעה בבגדים אלו, מפני שספק טומאה היא. ובענין זה מסופר כי \u0003רב פפא איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003תואך.\u0004 \u0003אמר: אי איכא צורבא מרבנן הכא, איזיל אקבל אפיה\u0004 \u0005[אם יש תלמיד חכם כאן, אלך אקבל פניו].\u0006 \u0003אמרה ליה ההיא סבתא\u0004 \u0005[לו זקנה אחת]:\u0006 \u0003איכא הכא צורבא מרבנן\u0004 \u0005[יש כאן תלמיד חכם],\u0006 \u0003ורב שמואל שמיה\u0004 \u0005[שמו],\u0006 \u0003ותני מתניתא\u0004 \u0005[ושנה משניות],\u0006 \u0003יהא רעוא דתהוי כוותיה\u0004 \u0005[יהי רצון שתהיה כמותו]!\u0006","\u0003אמר\u0004 רב פפא לעצמו: \u0003מדקמברכי לי בגוויה\u0004 \u0005[מ\u0006תוך \u0005שמברכים אותי בו,\u0006 שאהיה כמוהו\u0005]\u0006 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ירא שמים הוא,\u0004 וראוי הוא שאקבל פניו. \u0003אזל לגביה\u0004 \u0005[הלך אצלו].\u0006 \u0003רמא ליה תורא\u0004 \u0005[השליך לו,\u0006 שחט רב שמואל למענו \u0005שור],\u0006 \u0003רמא ליה מתניתין אהדדי\u0004 \u0005[השליך לו,\u0006 הביא \u0005משניות\u0006 והראה שסותרות \u0005זו את זו]:\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003אין חייבין עליהן על ביאת מקדש, ואין שורפין עליהן את התרומה, מפני שטומאתה\u0004 של תרומה זו שנגעו בה בגדי הכותים הריהי \u0003ספק.\u0004 \u0003אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 כי \u0003מספיקא\u0004 \u0005[מספק]\u0006 טומאה \u0003לא שרפינן\u0004 \u0005[אין שורפים אנו]\u0006 את ה\u0003תרומה.\u0004","\u0003ורמינהי\u0004 \u0005[והשליך]\u0006 כנגד זה ממה ששנינו במשנה במסכת טהרות: \u0003על ששה ספקות\u0004 טומאות \u0003שורפין את התרומה\u0004 אם נגעה התרומה בהן, או שנגע אדם בהן ואחר כך נגע בתרומה, ובכלל אלה \u0003על ספק בגדי עם הארץ,\u0004 שמטמאים במגע ובמשא מספק, שמא ישבה עליהם אשתו הנדה. ואף תרומה שנגעה במשכבו של הכותי, שספק טומאה היא, תישרף!","\u0003אמר רב פפא\u0004 תחילה בלשון בקשה: \u0003יהא רעוא דלתאכיל האי תורא לשלמא\u0004 \u0005[יהי רצון שייאכל שור זה לשלום]\u0006 שהרי לא שחט את השור אלא לכבודי כתלמיד חכם, ואם אכשל בתשובתי, נמצאת הסעודה מקולקלת. והמשיך: \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]\u0006 \u0003בכותי חבר\u0004 (המקפיד על דיני טהרה), שאין חוששים לטומאתו כמו לטומאת עם הארץ, ולכן אין שורפים בגללו את התרומה במקרה זה.","הקשה כנגדו רב שמואל: אם משנתנו עוסקת, כדבריך, בכותי שהוא חבר, וכי \u0003כותי חבר\u0004 — \u0003בועל נדה משוית ליה\u0004 \u0005[עושים אותו]\u0006 כמו ששנינו במשנתנו שנחשבים הם כבועלי נדות?","\u0003שבקיה\u0004 \u0005[עזבו]\u0006 רב פפא, משום שבוש מפניו, \u0003ואתא לקמיה\u0004 \u0005[ובא לפני]\u0006 \u0003רב שימי בר אשי,\u0004 ומסר לו על הדברים שהיו בינו לבין רב שמואל. \u0003אמר ליה\u0004 \u0005[לו\u0006 רב שימי בר אשי לרב פפא\u0005]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא משנית ליה\u0004 \u0005[השבת לו]\u0006 שמשנתנו עוסקת \u0003בכותי שטבל\u0004 במקוה טהרה \u0003ועלה\u0004 מטומאתו (ונטהר), \u0003ו\u0004לאחר מכן \u0003דרס על בגדי חבר,\u0004 שהריהם כמשכבו, \u0003ו\u0004לאחר מכן \u0003אזלו\u0004 \u0005[והלכו]\u0006 אותם \u0003בגדי חבר ונגעו בתרומה.\u0004","ובמקרה זה אין שורפים את התרומה, שכן \u0003דאי\u0004 \u0005[שאם]\u0006 נשרפנה \u0003משום טומאת עם הארץ\u0004 — \u0003הא טביל ליה\u0004 \u0005[הרי הוא טבל],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 נשרפנה \u0003משום בועל נדה\u0004 — הרי כותי זה נתון ב\u0003ספק:\u0004 שמא \u0003בעל\u0004 את אשתו \u0003בקרוב\u0004 (בזמן הסמוך) והרי הוא טמא משום בועל נדה, \u0003ספק לא בעל\u0004 את אשתו \u0003בקרוב\u0004 וכבר עברו ימי טומאתו והועילה לו הטבילה.","\u0003ו\u0004אף \u0003אם תמצי\u0004 (תמצא) \u0003לומר\u0004 ש\u0003בעל בקרוב\u0004 — עדיין ישנו ספק נוסף: \u0003ספק השלימתו\u0004 אשתו את מנין שבעת ימי טומאת נדתה שישבה על ראיית דם \u0003ירוק,\u0004 אף שראתה גם דם אדום המטמא אותה באמת, והרי היא נדה, וסבורה שהיא טהורה וכך גם סבור בעלה, \u0003ספק\u0004 שמא \u0003לא השלימתו\u0004 על ראיית דם ירוק, ואין היא נדה, \u0003ו\u0004נמצא איפוא בדינו של כותי זה \u0003הוי\u0004 \u0005[שהריהו]\u0006 \u0003ספק ספיקא\u0004 \u0005[ספק]\u0006 בועל נדה. \u0003ו\u0004כלל הוא שעל \u0003ספק ספיקא\u0004 \u0005[ספק]\u0006 \u0003לא שרפינן\u0004 \u0005[אין אנו שורפים]\u0006 \u0003תרומה.\u0004","שאלו רב פפא: \u0003ותיפוק ליה\u0004 \u0005[ו\u0006עדיין תצא לו, תיקבע\u0005]\u0006 הלכה במקרה זה, שנטמאו בגדי החבר שדרס עליהם הכותי, \u0003משום\u0004 ההלכה הנוהגת ב\u0003בגדי עם הארץ.\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בגדי עם הארץ\u0004 — נחשבים טמאים בטומאת \u0003מדרס\u0004 הזב, המטמא אדם ובגדים, \u0003לפרושין\u0004 (לחכמים הנזהרים בטהרה), ותישרף איפוא התרומה שנגעה בבגדי החבר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב שימי בר אשי לרב פפא בתשובה: משנתנו עוסקת \u0003בכותי ערום,\u0004 שלא היה לבוש בגדים בשעה שדרס על בגדי החבר.","\u0003בנות\u0004 ה\u0003צדוקין,\u0004 מה דינן לענין הנדה? \u0003בזמן שנהגו ללכת בדרכי\u0004 (במנהגי) \u0003אבותיהן\u0004 הצדוקים — \u0003הרי הן\u0004 נחשבות \u0003כ\u0004בנות \u0003כותיות,\u0004 שנתפרשו דיניהן במשנה הקודמת. ואם \u0003פרשו\u0004 בנות הצדוקים הללו ממנהגי אבותיהן \u0003ללכת בדרכי ישראל\u0004 — \u0003הרי הן\u0004 נחשבות בדינן \u0003כישראלית.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: לעולם\u0004 בסתם \u0003הן\u0004 נחשבות \u0003כישראלית\u0004 כשרה, \u0003עד שיפרשו\u0004 ממנהגי ישראל \u0003ללכת בדרכי אבותיהן\u0004 הצדוקים.","שנינו במשנתנו כי לדעת התנא קמא בזמן שבנות הצדוקים נוהגות בדרכי הצדוקים — הן נחשבות ככותיות, ובזמן שפרשו מדרכי הצדוקים — אין הן נחשבות ככותיות ומעתה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 ב\u0003סתמא\u0004 \u0005[סתם]\u0006 שאין אנו יודעים כיצד נוהגות בנות הצדוקים, \u0003מאי\u0004 \u0005[מה]\u0006 דינן? ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בתחילת משנתנו: \u0003בנות צדוקין, בזמן שנוהגות ללכת בדרכי אבותיהן\u0004 — \u0003הרי הן ככותיות,\u0004 ומכאן נדייק: דווקא בזמן שנוהגות בדרכי אבותיהן — הרי הן ככותיות, \u0003הא סתמא\u0004 \u0005[הרי\u0006 שב\u0005סתם]\u0006 — הן נחשבות \u0003כישראלית.\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003פרשו ללכת בדרכי ישראל\u0004 — \u0003הרי הן כישראלית,\u0004 ומכאן נדייק להיפך: \u0003הא סתמא\u0004 \u0005[הרי\u0006 שב\u0005סתם]\u0006 — הן נחשבות \u0003ככותיות! אלא מהא ליכא למשמע מיניה\u0004 \u0005[מ\u0006דיוק זה אין ללמוד ממנה] פתרון לשאלה.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ר' יוסי אומר: לעולם\u0004 בסתם \u0003הן\u0004 נחשבות \u0003כישראלית עד שיפרשו ללכת בדרכי אבותיהן.\u0004 \u0003מכלל\u0004 הדברים נסיק \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון\u0006 במשנתנו, \u0005סבור]\u0006 כי \u0003סתמא\u0004 \u0005[סתם]\u0006 בנות צדוקים נחשבות \u0003ככותיות.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","ועוד בענין טומאתן של בנות הצדוקים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בצדוקי אחד שספר עם כהן גדול בשוק, ו\u0004בתוך דבריו \u0003נתזה צנורא\u0004 (טיפת רוק) \u0003מפיו ונפלה לכהן גדול על בגדיו, והוריקו\u0004 (נשתנו לרעה) \u0003פניו של כהן גדול,\u0004 שסבור היה שנטמאו בגדיו בכך. \u0003וקדם\u0004 (מיהר) הכהן הגדול ללכת \u0003אצל אשתו\u0004 של הצדוקי לפני שיבוא בעלה, על מנת לברר האם היא נוהגת כדין לענין נדה (ואם כן אין לחשוש שבעלה טמא כבועל נדה).","\u0003אמרה לו: אף על פי שנשי צדוקים הן,\u0004 שאינם נוהגים כפרושים, הרי נשותיהם \u0003מתיראות מן הפרושים, ו\u0004בכל מקרה שרואות הן דם, הרי הן \u0003מראות\u0004 אותו ה\u0003דם לחכמים.\u0004 והתברר איפוא לכהן הגדול, שאין בנות הצדוקים נוהגות כבנות הכותים, ואין לחשוש שנדות הן.","\u0003אמר ר'\u0004 \u0003יוסי: בקיאין\u0004 (מכירים) \u0003אנו בהן\u0004 בנשות הצדוקים \u0003יותר מן הכל,\u0004 שכן בשכנות מקום הן גרות, \u0003ו\u0004מעיד אני בהן ש\u0003הן מראות דם לחכמים.\u0004 \u0003ח\u0004 \u0003וץ מאשה אחת שהיתה בשכונתינו, שלא הראת\u0004 (הראתה) \u0003דם לחכמים,\u0004 ונענשה על כך \u0003ומתה.\u0004","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ו\u0006עדיין \u0005תצא לו,\u0006 לכהן הגדול\u0005]\u0006 שנטמאו בגדיו \u0003משום צנורא\u0004 (טיפת רוק) של \u0003עם הארץ\u0004 המטמאת! \u0003אמר אביי:\u0004 מדובר באותו מקרה \u0003בצדוקי חבר\u0004 המקפיד על הטהרה. \u0003אמר רבא\u0004 בדחיית דברי אביי: וכי \u0003צדוקי חבר בועל נדה משוית ליה\u0004 \u0005[עשית אותו],\u0006 שהרי מלכתחילה לכך חשש הכהן הגדול? \u0003אלא אמר רבא:\u0004"],["אותו הזמן שבו היה מעשה זה, זמן ה\u0003רגל הוה\u0004 \u0005[היה],\u0006 שהיה הדבר באחד משלוש הרגלים, פסח שבועות או סוכות. \u0003ו\u0004הלכה היא ש\u0003טומאת עם הארץ ב\u0004זמן ה\u0003רגל\u0004 — \u0003כטהרה שוינהו רבנן\u0004 \u0005[עשוה חכמים],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויאסף כל איש ישראל אל העיר כאיש אחד חברים\"\u0004 (שופטים כ, יא) ללמדנו שבזמן שנאספים כל ישראל כאחד, כבשלוש רגלים, \u0003הכתוב עשאן\u0004 את \u0003כולן,\u0004 ואף עמי הארץ בכללם, כ\u0003חברים\u0004 המקפידים על הטהרה. ואותו צדוקי, אף שאין לחשוש בו בזמן הרגל לטומאת עם הארץ, יש לחשוש בו שבועל נדה הוא.","\u0003דם\u0004 הנדה או הזיבה של ה\u0003גויה,\u0004 \u0003ו\u0004כן \u0003דם טהרה\u0004 (של ימי הטהרה, הבאים לאחר ימי טומאתה של היולדת) \u0003של\u0004 הישראלית ה\u0003מצורעת, בית שמאי מטהרים, ובית הלל\u0004 חולקים ו\u0003אומרים:\u0004 דם הגויה הריהו מטמא, ומכל מקום, בניגוד לדם הישראלית, דם הגויה אינו מטמא אלא כשהוא לח ולא כשהוא יבש, ו\u0003כרוקה וכמימי רגליה\u0004 המטמאים רק כשהם לחים ולא יבשים.","\u0003דם היולדת\u0004 הנכנסת לימי טהרתה, לאחר שנסתיימו ימי טומאתה (שבעה אם ילדה זכר, ושבועים אם ילדה נקבה), \u0003ש\u0004עדיין \u0003לא טבלה\u0004 בסוף ימי טומאתה, \u0003בית שמאי אומרים:\u0004 אף שלא טבלה, אין דין דמה כדין דם הנדה, ואין הוא מטמא אלא לח ולא יבש, \u0003כ\u0004טומאת \u0003רוקה וכ\u0004טומאת \u0003מימי רגליה.\u0004 \u0003ו\u0004אילו \u0003בית הלל אומרים:\u0004 כיון שלא טבלה הרי דם זה נחשב כדם הנדה, והריהו \u0003מטמא לח ויבש.\u0004","\u0003ומודים\u0004 (ומסכימים הכל) \u0003ב\u0004דין האשה ה\u0003יולדת בזוב\u0004 (כשהיא זבה), שחייבת לאחר ימי טומאת לידתה לספור שבעת ימי זיבה, \u0003שהיא מטמאה\u0004 בזמן זה בדם \u0003לח ויבש.\u0004","שנינו במשנתנו שלדעת בית שמאי דם הגויה אינו מטמא. ושואלים על כך: \u0003ולית להו\u0004 \u0005[ו\u0006כי \u0005אין להם]\u0006 \u0003לבית שמאי\u0004 מה שאמרו על הכתוב \u0003\"דבר אל בני ישראל ואמרת אליהם איש איש כי יהיה זב\"\u0004 (ויקרא טו, ב) — מן התורה רק \u0003בני ישראל מטמאין בזיבה, ואין הגוים מטמאין בזיבה, אבל גזרו\u0004 חכמים \u0003עליהן\u0004 על הגוים \u0003שיהו\u0004 תמיד נחשבים \u0003כזבין לכל דבריהם\u0004 (ענייניהם)?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003לך בית שמאי\u0004 בתשובה: \u0003(\u0004הענין \u0003ההוא בזכרים איתמר\u0004 \u0005[נאמר],\u0006 ולא בנקבות. \u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 נגזור אף \u0003בנקבות) היכי לעביד\u0004 \u0005[איך לעשות,\u0006 לנהוג בטומאה זו\u0005]?\u0006 \u0003ליטמא\u0004 \u0005[שיטמא]\u0006 דם הגויה גם ב\u0003לח ו\u0004גם ב\u0003יבש\u0004 — נמצא ש\u0003עשיתו\u0004 לדם הגויה שטמא מדברי חכמים \u0003כשל\u0004 דם המטמא מן ה\u0003תורה.\u0004 ואם תחלק בדין ותאמר \u0003ליטמי\u0004 \u0005[שיטמא]\u0006 דם הגויה רק ב\u0003לח ולא ליטמי\u0004 \u0005[שיטמא]\u0006 ב\u0003יבש\u0004 — יש לחשוש כי כתוצאה מכך \u0003חלקת\u0004 אף \u0003ב\u0004דין טומאה \u0003של תורה,\u0004 שיבואו לנהוג כן אף בדם הישראלית, אף שהוא טמא מן התורה בלח וביבש.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא טעמם של בית שמאי — \u0003רוקה ומימי רגליה\u0004 של הגויה המטמאים מדברי חכמים בלח ולא ביבש \u0003נמי\u0004 \u0005[גם כן]\u0006 לא יטמאו, שמא יבואו לנהוג כן אף בטומאה שמן התורה! ומשיבים: \u0003כיון דעבדינן היכרא\u0004 \u0005[שעושים אנו היכר]\u0006 \u0003בדמה\u0004 של הגויה, שמטמאה רק ברוקה ומימי רגליה, מעתה \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 לכל שטומאת \u0003רוקה ומימי רגליה\u0004 של הגויה הריהו \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ואין לחשוש שיבואו לנהוג כן אף בטומאה מן התורה.","ושואלים: \u0003ו\u0004מדוע לא יעשו באופן זה: \u0003לעביד היכרא\u0004 \u0005[שיעשו היכר]\u0006 \u0003ברוקה ומימי רגליה,\u0004 שאין הם מטמאים כלל, לא בלח ולא ביבש, \u0003ולטמויי\u0004 \u0005[ושיטמאו]\u0006 \u0003לדמה\u0004 הלח ולא היבש, ומעתה ידעו הכל שטומאת הגויה היא רק מדברי חכמים, ולא יבואו לנהוג כן בטומאה שמן התורה! ומשיבים: ב\u0003רוקה ו\u0004ב\u0003מימי רגליה דשכיחי\u0004 \u0005[שמצויים]\u0006 הם — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 טומאה בגויה, אבל ב\u0003דמה\u0004 ש\u0003לא שכיחא\u0004 \u0005[מצוי]\u0006 הוא כרוקה ומימי רגליה — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006","שנינו במשנתנו דין דם הגויה, שנחלקו בו בית שמאי ובית הלל. ובענין דין טומאתו של הגוי \u0003אמר רבא: זובו\u0004 של הגוי הריהו \u0003טמא\u0004 \u0003אפילו ל\u0004שיטת \u0003בית שמאי\u0004 המטהרים זיבתה של גויה. ואילו \u0003קריו\u0004 (שכבת זרע) של הגוי הריהו \u0003טהור אפילו ל\u0004שיטת \u0003בית הלל\u0004 המטמאים דם נדתה ודם זיבתה של הגויה כשהם לחים.","ומסביר רבא את דבריו אלו: \u0003זובו\u0004 של הגוי הריהו \u0003טמא אפילו ל\u0004שיטת \u0003בית שמאי\u0004 — \u0003דהא איכא למעבד היכרא\u0004 \u0005[שהרי יש,\u0006 ניתן, \u0005לעשות היכר]\u0006 ללמד שטומאה זו מדברי חכמים, ולא יבואו לנהוג כטומאה מן התורה, שכן \u0003בקריו\u0004 אינו מטמא, ומעתה ידעו הכל כי אף טומאת זיבתו של הגוי הריהי מדברי חכמים בלבד.","ובדין \u0003קריו\u0004 שהוא \u0003טהור\u0004 הרי זה \u0003אפילו ל\u0004שיטת \u0003בית הלל\u0004 — שבכך שטיהרוהו \u0003עבוד ביה רבנן היכרא\u0004 \u0005[עשו בו חכמים היכר],\u0006 שידעו שזוהי טומאה רק מדבריהם, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא\u0004 יבואו \u0003לשרוף עליה\u0004 \u0005[עליו,\u0006 על טומאת זיבתו\u0005]\u0006 אם נגעו בה \u0003תרומה וקדשים,\u0004 כדרך ששורפים תרומה וקדשים שנטמאו מן התורה.","ושואלים על הסבר זה: \u0003ולעביד היכרא\u0004 \u0005[ושיעשו\u0006 חכמים \u0005היכר]\u0006 \u0003בזובו\u0004 של הגוי שאין הוא מטמא כלל, ויהיה בכך היכר שאף קריו אף שהוא טמא אין זה אלא מדברי חכמים, \u0003ולטמויי\u0004 \u0005[ושיטמאו]\u0006 \u0003לקריו\u0004 של הגוי? ומשיבים: ב\u0003זובו\u0004 של האיש, ש\u0003לא תלי\u0004 \u0005[תלוי]\u0006 הוא \u0003במעשה\u0004 הנעשה על ידי האדם, והריהו בא מאליו — \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 לטמאו, ואילו \u0003קריו\u0004 של איש \u0003דתלי\u0004 \u0005[שתלוי]\u0006 הוא \u0003במעשה\u0004 הנעשה על ידי האדם — \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003מסייע ליה\u0004 \u0005[לו,\u0006 לרבא\u0005]\u0006 בדבריו אלו, מה ששנינו במשנה במסכת מקואות: \u0003גויה שפלטה\u0004 מתוכה \u0003שכבת זרע\u0004 שהיתה בה מאדם \u0003מישראל\u0004 שבא עליה — \u0003טמאה\u0004 שכבת זרע זו, שכן באה מאדם מישראל. \u0003ו\u0004אילו \u0003בת ישראל שפלטה שכבת זרע מן הגוי\u0004 שבא עליה — \u0003טהורה.\u0004 \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 כוונת הדברים ששכבת זרע של גוי הריהי \u0003טהורה גמורה,\u0004 וכדברי רבא שאין הגוי מטמא בקריו. ודוחים: \u0003לא,\u0004 אין להביא מכאן ראיה לשיטת רבא, שכן אפשר לומר בכוונת המשנה ששכבת הזרע של הגוי הריהי \u0003טהורה\u0004 — \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 ו\u0003טמאה\u0004 — \u0003מדרבנן\u0004 \u0005[מדברי חכמים].\u0006 ואילו שיטת רבא היא ששכבת זרעו של הגוי הריהי טהורה לגמרי, אף מדברי חכמים.","ומביאים עוד ראיה לשיטת רבא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003נמצאת אומר: שכבת זרע של ישראל\u0004 — הריהי \u0003טמאה בכל מקום\u0004 בו היא נמצאת,"],["\u0003ואפילו\u0004 היא נמצאת \u0003במעי גויה,\u0004 שבא עליה הישראל, שאם תיפלט שכבת זרע זו, הריהי מטמאת. \u0003ו\u0004אילו שכבת זרע \u0003של גוי\u0004 — הריהי \u0003טהורה בכל מקום\u0004 בו היא נמצאת, \u0003ואפילו\u0004 היא נמצאת \u0003במעי\u0004 אשה \u0003ישראלית\u0004 שבא עליה הגוי, \u0003חוץ ממי רגלים שבה,\u0004 שאם התערבה שכבת הזרע של הגוי במי רגליו הריהי טמאה בשל מי הרגלים שבה, שגזרו חכמים שיהיו הגוים נחשבים כזבים המטמאים במימי רגליהם. הרי שזרעו של הגוי הריהו טהור, וכשיטת רבא.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בדחיית הראיה: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הכוונה היא ש\u0003טהורה\u0004 שכבת זרעו של גוי \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אבל טמאה\u0004 היא \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 ואולם על כך יש להשיב: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003מי רגליה,\u0004 כלומר, מי רגלי הגוי שבא עליה ונמצאים עתה במעיה \u0003מדאורייתא מי מטמאו\u0004 \u0005[מן התורה האם מטמאים]?\u0006 והרי טומאתם מדברי חכמים, אבל שכבת הזרע של הגוי אינה טמאה. \u0003אלא שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי שכבת זרעו של הגוי \u0003טהורה אפילו מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא, וכשיטת רבא.","ודנים עוד בדברים שהובאו למעלה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שכבת זרע של ישראל\u0004 — הריהי \u0003טמאה בכל מקום\u0004 שבו היא נמצאת, ו\u0003אפילו\u0004 היא נמצאת \u0003במעי\u0004 ה\u0003גויה.\u0004 ומציעים: \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מדברים אלו את השאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב פפא.\u0004 \u0003דבעי\u0004 \u0005[ש\u0006כך \u0005שאל]\u0006 \u0003רב פפא: שכבת זרע של ישראל במעי גויה מהו\u0004 דינה לענין טומאה. ולדברי החכם ששנינו למעלה ודאי ששכבת זרע של ישראל במעי גויה מטמאה.","ודוחים: דינה של שכבת זרעו של ישראל הנתונה במעי הגויה \u0003בתוך שלשה\u0004 ימים מזמן שבא עליה — \u0003לא קמיבעיא ליה\u0004 \u0005[לא נשאלה לו]\u0006 \u0003לרב פפא,\u0004 שכן ברור לו שהיא טמאה. \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 שאלה זו — הרי זה בדין שכבת הזרע ש\u0003לאחר שלשה\u0004 ימים מזמן הביאה \u0003מאי\u0004 \u0005[מה\u0006 דינה], האם היא מטמאה.","ואלו צדדי השאלה: מן הצד האחד יש לומר כי דווקא \u0003ישראל דדייגי\u0004 \u0005[הדואגים\u0006 וחרדים תמיד\u0005]\u0006 \u0003ב\u0004שמירת \u0003מצו‍ת\u0004 התורה וקיומן כראוי — כתוצאה מכך \u0003חביל גופייהו\u0004 \u0005[חם גופם],\u0006 ולכן ממהר הזרע הנתון במעי נשי ישראל \u0003ומסריח\u0004 (מתקלקל) לאחר שלושה ימים, ואינו נחשב עוד כזרע המטמא. ואולם ה\u0003גוים דלא דייגי\u0004 \u0005[שאינם דואגים]\u0006 \u0003ב\u0004שמירת ה\u0003מצו‍ת\u0004 — \u0003לא חביל גופייהו\u0004 \u0005[אין גופם חם],\u0006 \u0003ו\u0004לכן אף \u0003לא מסריח\u0004 הזרע הנתון במעי הגויה לאחר שלושה ימים של ביאה, והריהו מטמא. ומן הצד האחר יש לומר, \u0003או דילמא\u0004 \u0005[שמא]:\u0006 אף הגוים, \u0003כיון דאכלי\u0004 \u0005[שאוכלים]\u0006 הם \u0003שקצים ורמשים\u0004 — כתוצאה מכך \u0003חביל גופייהו\u0004 \u0005[חם גופם],\u0006 \u0003ומסריח\u0004 הזרע הנתון במעי הגויה לאחר שלושה ימים מזמן הביאה. שאלה זו של רב פפא נשארה ללא פתרון, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנתנו שנחלקו בית שמאי ובית הלל בדינו של \u0003דם\u0004 שנראה בימי ה\u0003טהרה של\u0004 היולדת שהיא \u0003מצורעת,\u0004 שלדעת \u0003בית שמאי\u0004 טהור הוא, ולדעת בית הלל מטמא כשהוא לח ואינו מטמא כשהוא יבש. ודנים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בתורה\u0005]\u0006 לשיטת \u0003בית הלל\u0004 זו? \u0003אמר ר'\u0004 \u0003יצחק:\u0004 אמר הכתוב בסוף פרשת הטמאים \"לזכר ולנקבה\" (ויקרא טו, לג), ולמדים אנו מן הלשון \u0003\"לזכר\"\u0004 — \u0003לרבות\u0004 את ה\u0003מצורע למעינותיו\u0004 (הנוזלים המופרשים מגופו, כרוק ומימי רגלים) שאף הם מטמאים, ומן הלשון \u0003\"ולנקבה\"\u0004 — למדים אנו \u0003לרבות מצורעת למעינותיה\u0004 שאף הם טמאים.","ומעתה יש לברר, \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה ב\u0003מעינותיה\u0004 אלה של המצורעת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא ל\u0003שאר מעינותיה\u0004 כגון רוקה ומימי רגליה — והלא דבר זה \u0003מ\u0004דין המצורע ה\u0003זכר נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 \u0003אלא\u0004 יש לומר שהכוונה היא \u0003לדמה\u0004 של המצורעת, ובאה דרשה זו ללמדנו \u0003לטמא דם טהרה שלה.\u0004","\u0003ובית שמאי,\u0004 מה משיבים הם על דברים אלו של בית הלל — הכוונה ב\"מעיינותיה\" של המצורעת היא לשאר מעיינותיה, רוקה ומימי רגליה, ואין הם נלמדים מדין הזכר משום שדין המצורעת ה\u0003נקבה מ\u0004דין המצורע ה\u0003זכר לא אתיא\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 משום \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005להקשות]\u0006 על לימוד המצורעת מן המצורע: \u0003מה ל\u0004מצורע \u0003זכר\u0004 שחמור הוא בדינו, \u0003שכן\u0004 הריהו \u0003טעון\u0004 (חייב) \u0003פריעה ופרימה, ואסור בתשמיש המטה, תאמר ב\u0004מצורעת \u0003נקבה ש\u0004\u0003לא\u0004 חייבת בכל אלו. ולכן נצרכים אנו לדרשה זו במצורעת לשאר מעיינותיה שהם מטמאים. ואין לימוד מן הכתוב לטמא את דמה.","\u0003ובית הלל,\u0004 מה משיבים הם על דברים אלו של בית שמאי — אם אין הנלמד מ\"לנקבה\" אלא לשאר מעיינותיה, אם כן \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 דין זה רק \u0003ב\u0004מצורעת \u0003נקבה ולא בעי\u0004 \u0005[צריך]\u0006 לכותבו אף במצורע \u0003זכר.\u0004 \u0003ואנא אמינא\u0004 \u0005[ואני א ומר]\u0006 שהוא הדין אף בזכר, מקל וחומר זה: \u0003ומה\u0004 המצורעת ה\u0003נקבה\u0004 שקלה היא בדינה, \u0003ש\u0004כן \u0003אינה טעונה\u0004 (חייבת) ב\u0003פריעה ופרימה,\u0004 \u0003ואינה אסורה בתשמיש המטה\u0004 — \u0003רבי רחמנא\u0004 \u0005[ריבתה התורה]\u0006 לטמא אף את \u0003מעינותיה,\u0004 המצורע ה\u0003זכר,\u0004 שחמור הוא שכן חייב הוא בכל אלה — \u0003לא כל שכן\u0004 שמטמא הוא במעיינותיו!","ומעתה נאמר, \u0003אם\u0004 כתוב זה \"לזכר\" \u0003אינו\u0004 נצרך ללמדנו \u0003ענין\u0004 (דבר) \u0003ל\u0004מצורע ה\u0003זכר\u0004 (שנלמדו דין מעיינותיו מקל וחומר זה) — \u0003תנהו ענין ל\u0004מצורעת ה\u0003נקבה.\u0004 \u0003ואם אינו ענין\u0004 במצורעת הנקבה \u0003למעינותיה\u0004 (שכבר נלמדו מ\"לנקבה\") — \u0003תנהו ענין לדמה, לטמא דם טהרה שלה.\u0004","\u0003ובית שמאי\u0004 המטהרים, מה משיבים הם על דברים אלה של בית הלל — לא בא הכתוב \"זכר\" אלא לרבות טומאה למעיינותיו של המצורע הזכר, ואין דינם של אלו נלמד מקל וחומר מן המצורעת הנקבה, משום שדין ה\u0003זכר מ\u0004דין ה\u0003נקבה לא אתיא\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 כיון \u0003דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005להקשות]\u0006 על קל וחומר זה: \u0003מה לנקבה\u0004 — שיש בה צד חומרה \u0003שכן מטמאה\u0004 היא אף \u0003מאונס\u0004 (בטומאת הזיבה), \u0003תאמר בזכר\u0004 ש\u0003לא\u0004 נטמא בזיבה מאונס.","\u0003ובית הלל,\u0004 מה משיבים הם על דברי בית שמאי אלו — אין זו פירכה על קל וחומר זה, משום ש\u0003קיימי\u0004 \u0005[עומדים]\u0006 אנו \u0003ב\u0004דינו של ה\u0003מצורע ופרכי מילי\u0004 \u0005[ומקשים\u0006 על קל וחומר זה מדברי, הלכות\u0005]\u0006 של ה\u0003זב? ובית שמאי,\u0004 מה משיבים הם על דברי בית הלל אלו — לדעתם יש מקום לפירכה זו על הקל וחומר, כיון שמ \u0003שום\u0004 \u0005[שם]\u0006 \u0003טומאה\u0004 המשותף לזה ולמצורע \u0003פרכי\u0004 \u0005[\u0006הם \u0005מקשים].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר מדוע אין בית שמאי מקבלים את דברי בית הלל שמיותרת היא המלה \"לזכר\", \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003לך בית שמאי: האי\u0004 \u0005[זו]\u0006 המלה \u0003\"לזכר\" מיבעי ליה\u0004 \u0005[צריך אותה]\u0006 לדרשה אחרת: \u0003\"לזכר\"\u0004 — \u0003כל שהוא זכר, (האי\u0004 \u0005[זה]\u0006\u0003),\u0004 ש\u0003בין\u0004 שהוא \u0003גדול\u0004 ו\u0003בין\u0004 שהוא \u0003קטן,\u0004 נוהגת טומאת הצרעת בו. \u0003ובית הלל,\u0004 מה משיבים הם על דברי בית שמאי אלו — לדעתם דין זה \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 \u0003מ\u0004הכתוב בסוף פרשת הטמאים \u0003\"זאת תורת הזב\u0004 ואשר תצא ממנו שכבת זרע לטמאה בה\" (ויקרא טו, לב) — \u0003בין\u0004 ב\u0003גדול בין\u0004 ב\u0003קטן.\u0004","ומתוך שהובא דינו של הזב הקטן הנלמד מפסוק זה, מביאים עוד מה ש\u0003אמר רב יוסף, כי פשיט\u0004 \u0005[כאשר פשט,\u0006 פירש\u0005]\u0006 \u0003ר' שמעון בן לקיש ב\u0004דיני ה\u0003זב, בעי הכי\u0004 \u0005[שאל כך]:\u0006 \u0003ראייה ראשונה של זב קטן, מהו\u0004 דינה לענין \u0003שתטמא במגע?\u0004 וצדדי השאלה: מצד אחד, \"זאת תורת הזב ואשר תצא ממנו שכבת זרע\" (שם) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומתוך שהושוו הזיבה לשכבת הזרע, ללמדנו בא הדבר: ש","\u0003כל\u0004 מי \u0003ששכבת זרע שלו מטמא\u0004 — אף \u0003ראייה ראשונה\u0004 של זיבה \u0003שלו מטמאה, ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 הקטן, \u0003כיון\u0004 ש\u0003שכבת זרע שלו לא מטמאה\u0004 — אף \u0003ראייה ראשונה\u0004 של זיבתו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תטמא.\u0004 \u0003או דילמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003כיון\u0004 ש\u0003אילו איהו חזי תרתי\u0004 \u0005[הוא,\u0006 הקטן, \u0005היה רואה שתי\u0006 ראיות של זיבה\u0005]\u0006 — \u0003מצטרפא\u0004 \u0005[מצטרפת]\u0006 ראייתו הראשונה לשניה לטמאו טומאת שבעה כדינו של כל זב הרואה שתי ראיות, הרי שנחשבת היא ראייה ראשונה זו אף שהיא אצל הקטן, ו\u0003מטמיא\u0004 \u0005[מטמאת]\u0006 אף את הקטן, כגדול, בטומאת ערב?","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלתו זו של ר' שמעון בן לקיש ממה ששנינו: \u0003\"זאת תורת הזב\"\u0004 — \u0003בין\u0004 שהוא \u0003גדול בין\u0004 שהוא \u0003קטן.\u0004 ובכלל השוואה זו שבין הגדול לקטן: \u0003מה גדול\u0004 — \u0003ראייה ראשונה שלו מטמא, אף קטן\u0004 — \u0003ראייה ראשונה נמי\u0004 \u0005[גם כן]\u0006 \u0003מטמא.\u0004","ומתוך שנדונה דרשה זו שעל המלה \"לזכר\" המלמדת שבכלל טומאת המצורע אף מעיינותיו (כגון רוקו ומימי רגליו), \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף:\u0004 ברור שראייה ראשונה של זיבה שרואה אדם טהור — אינה מטמאה במשא, אלא במגע בלבד, ורק ראייה שניה של זיבה מטמאת במשא. ואולם \u0003ראייה ראשונה של\u0004 מי שאיננו טהור, וכגון ה\u0003מצורע, מהו\u0004 דינה \u0003שתטמא\u0004 אף \u0003במשא?\u0004 וצדדי השאלה: האם אף \u0003מקום זיבה\u0004 שבאדם כ\u0003מעין הוא\u0004 נחשב, וכיון שמעיינותיו של המצורע מטמאים אף במשא אף הוא בכלל ריבוי זה, \u0003ו\u0004הריהו \u0003מטמא\u0004 במשא. \u0003או דילמא לאו\u0004 \u0005[שמא אין]\u0006 מקום הזיבה שבאדם כ\u0003מעין הוא,\u0004 ולכן אין ראיית הזוב הראשונה של המצורע מטמאת אף במשא?","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו על הפסוק שבראש פרשת הטמאים \"איש איש כי יהיה זב מבשרו \u0003זובו טמא הוא\"\u0004 (שם ב) — \u0003לימד על הזוב שהוא טמא\u0004 ומטמא במשא. ומעתה נדון בדבר: \u0003במאי\u0004 \u0005[במה]\u0006 בדיוק המדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בזב גרידא\u0004 \u0005[סתם]\u0006 שאינו מצורע עוסק הכתוב, ובא להשמיענו כי טיפת הזיבה היוצאת ממנו הריהי מטמאת במשא,"],["והרי אין צורך להשמיענו זאת, שכן אם טיפת זיבה זו \u0003לאחרים\u0004 (כלומר, לאדם שממנו יצאה טיפה זו) \u0003גורם טומאה\u0004 שיטמא במשא, הטיפה כש\u0003לעצמו לא כל שכן\u0004 שהיא מטמאת במשא! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שכוונת הדברים היא \u0003ב\u0004טיפת הזיבה הבאה מן ה\u0003זב\u0004 ה\u0003מצורע,\u0004 וללמדנו שאף זו מטמאת במשא. ונצרך לכך לימוד מיוחד, ואינו נלמד מקל וחומר זה מן הזב עצמו, שהרי אין הזב המצורע מטמא במשא מחמת טיפה זו אלא מחמת צרעתו.","\u0003ומדאיצטריך קרא לרבויי\u0004 \u0005[ומ\u0006תוך \u0005שהוצרך הכתוב לרבות]\u0006 לענין טומאת המשא את הזב המצורע \u0003בראייה שניה,\u0004 שכן עניינו של פסוק זה \"זב מבשרו זובו טמא הוא\" (ויקרא טו, ב) הריהו בראייה שניה (שכן שני לשונות זיבה נאמרו בו: \"זב\" \"זובו\") — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מקום זיבה לאו\u0004 \u0005[לא] כ\u0006\u0003מעין הוא\u0004 נחשב. שהרי אם כמעין הוא נחשב, אף בראייה ראשונה הריהו מטמא.","בדחיית ראיה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה מדסקרתא לרבא: ממאי\u0004 \u0005[ממה]\u0006 מנין לך שעניינו של הפסוק הוא בזב מצורע, \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שהפסוק מדבר \u0003ב\u0004טיפת זיבה הבאה מן ה\u0003זב גרידא\u0004 \u0005[סתם],\u0006 \u0003ודקאמרת\u0004 \u0005[ו\u0006מה \u0005שאמרת]\u0006 שאין צורך ללמדנו שהיא מטמאת במשא, שהרי קל וחומר הוא זה: אם \u0003לאחרים\u0004 (לזב) \u0003גורם\u0004 טיפה זו \u0003טומאה\u0004 שיטמא במשא, הטיפה כש\u0003לעצמו לא כל שכן\u0004 שהיא מטמאת במשא — יש לפרוך קל וחומר זה, שכן \u0003שעיר המשתלח\u0004 ביום הכיפורים \u0003יוכיח, ש\u0004כן הוא השעיר \u0003גורם טומאה לאחרים\u0004 (שהמשלח את השעיר נטמא), \u0003ו\u0004אילו \u0003הוא עצמו\u0004 השעיר \u0003טהור\u0004 (שהרי אין טומאה בבעל חיים החי)!","ולעצם שאלתו של רב יוסף בדין ראייה ראשונה של זיבה במצורע האם מטמאת היא במשא, \u0003אמר אביי: מאי תבעי ליה\u0004 \u0005[מה תישאל לו]\u0006 שאלה זו, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003הוא\u0004 זה ש\u0003אמר\u0004 בדרשת הכתוב \u0003\"זאת תורת הזב\"\u0004 (שם לב) — כל זב ישראל מטמא \u0003בין\u0004 שהוא \u0003גדול בין\u0004 שהוא \u0003קטן, וכיון דנפקא ליה מהתם\u0004 \u0005[שיצא לו משם]\u0006 — \u0003אייתר ליה\u0004 \u0005[נותר לו]\u0006 הכתוב \"והזב את זובו לזכר ולנקבה\" (שם לג) לדרשה, ובאופן זה: \u0003\"לזכר\"\u0004 — לרבות מצורע למעינותיו, שמטמא כזב לכל דבריו, וכיוצא בזה נדרש הכתוב \u0003\"נקבה\"\u0004 — \u0003לרבות\u0004 את ה","\u0003מצורעת למעינותיה, ואקשיה רחמנא\u0004 \u0005[והקישו הכתוב]\u0006 \u0003מצורע לזב גמור,\u0004 שהרי במי שראה שתי ראיות הכתוב מדבר, והריהו זב גמור שמטמא זובו במשא. ומעתה שהוקשו מעינות המצורע לזב גמור, יש איפוא לומר: \u0003מה זב גמור\u0004 — הריהו \u0003מטמא במשא, אף ראייה ראשונה של מצורע\u0004 — הריהי \u0003מטמא במשא.\u0004","ומביאים עוד, \u0003אמר רב הונא: ראייה ראשונה של זב\u0004 — הריהי \u0003מטמאה\u0004 את זה שיצאה ממנו, ואת זה שנגע בה בטומאת ערב, גם אם היתה ראייה זו \u0003באונס.\u0004 ומקורם של דברים: \u0003ש\u0004כן \u0003נאמר\u0004 בדינו של הזב: \u0003\"זאת תורת הזב ואשר תצא ממנו שכבת זרע\u0004 לטמאה בה\" — הקיש הכתוב ראייה ראשונה של זיבה לראיית קרי. ומעתה נאמר: \u0003מה\u0004 ראיית \u0003שכבת זרע\u0004 — הריהי \u0003מטמא\u0004 אף \u0003באונס, אף ראייה ראשונה של זב\u0004 — הריהי \u0003מטמאה\u0004 אף \u0003באונס.\u0004","ודנים בדברי רב הונא אלה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מהמשנה, שכן אמרו בדינו של מי ש\u0003ראה ראייה ראשונה\u0004 של זוב — \u0003בודקין אותו\u0004 אם לא ראה את הזוב מחמת אונסו. \u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שמטרתה של בדיקה זו כדי \u0003ל\u0004טהר אותו מן ה\u0003טומאה,\u0004 שכיון שראה באונס — אינו טמא, ושלא כדברי רב הונא! ודוחים: \u0003לא,\u0004 מטרת הבדיקה \u0003ל\u0004פוטרו מן ה\u0003קרבן\u0004 לאחר שיראה עוד שתי ראיות, שזו כיון שהיתה באונס אינה נחשבת למנין.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו באותה משנה כי \u0003ב\u0004ראייה \u0003שניה\u0004 של הזב שוב \u0003בודקין אותו\u0004 אם ראה כתוצאה מאונס. ויש לברר: \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה ענין\u0005]\u0006 נועדה בדיקה שניה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיא באה כדי \u0003ל\u0004פוטרו מן ה\u0003קרבן\u0004 אם יראה עוד ראייה, \u0003אבל לטומאה\u0004 — \u0003לא,\u0004 שאין מטהרים אותו אף שראייה זו היתה באונס. ואולם אין מקום לפירוש זה, שהרי \u0003אקרי\u0004 \u0005[נקרא]\u0006 \u0003כאן\u0004 בדין הזב \"כי יהיה זב \u0003מבשרו\"\u0004 (ויקרא שם ב) — \u0003ולא\u0004 שיצאה \u0003מחמת אונסו,\u0004 שאם ראה מחמת אונסו — אינו נטמא בה, \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003ל\u0004טהר אותו מן ה\u0003טומאה, ומדסיפא\u0004 \u0005[ומ\u0006תוך \u0005שהסוף]\u0006 של אותה משנה בא \u0003ל\u0004ענין \u0003טומאה\u0004 — נלמד מכאן כי \u0003רישא נמי\u0004 \u0005[תחילתה\u0006 של המשנה \u0005גם כן]\u0006 באה \u0003ל\u0004ענין ה\u0003טומאה!\u0004","ודוחים: \u0003מידי איריא\u0004 \u0005[וכי הדברים שייכים]?\u0006 \u0003הא כדאיתא\u0004 \u0005[זה כפי שיש],\u0006 \u0003והא כדאיתא\u0004 \u0005[וזה כפי שיש].\u0006 שאפשר לומר כי שני חלקי המשנה עוסקים בעניינים שונים, שהבדיקה הראשונה באה לענין קרבן ולא טומאה, ואילו הבדיקה השניה באה לענין טומאה וקרבן.","ומביאים עוד ראיה שלא כדברי רב הונא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו כי \u0003ר' אליעזר אומר\u0004 ש\u0003אף בשלישי\u0004 (ראייה שלישית) \u0003בודקין אותו, מפני הקרבן.\u0004 ונדייק מכאן: זהו טעמו של ר' אליעזר, \u0003מכלל\u0004 \u0005[מכאן]\u0006 נלמד שלדעת \u0003תנא קמא\u0004 \u0005[הראשון]\u0006 — \u0003מפני הטומאה קאמר\u0004 \u0005[ הוא אומר ],\u0006 והרי איפוא למדים אנו כי אם ראה ראייה ראשונה באונס, אין הוא נטמא בה, ושלא כדברי רב הונא!","ודוחים: \u0003לא,\u0004 אין לדייק כן בשיטת תנא קמא, שכן יש לומר כי \u0003דכולי עלמא\u0004 \u0005[\u0006לשיטת \u0005כולם ]\u0006 בודקים אותו \u0003ל\u0004ענין ה\u0003קרבן, ו\u0004אילו \u0003הכא\u0004 \u0005[כאן]\u0006 מחלוקתם \u0003ב\"אתים\" קא מיפלגי\u0004 \u0005[ הם חולקים ],\u0006 האם דורשים להלכה מן הכתוב \"את\" (שבפסוק \"והזב את זובו לזכר ולנקבה\"). שבכך נחלקו: \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא דרשי\u0004 \u0005[אינם דורשים]\u0006 \u0003\"אתים\",\u0004 \u0003ו\u0004אילו \u0003ר' אליעזר דריש\u0004 \u0005[דורש]\u0006 \u0003\"אתים\".\u0004","ומפרטים: \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא דרשי\u0004 \u0005[אינם דורשים]\u0006 \u0003\"אתים\",\u0004 ולכן כך הם דורשים: \u0003\"הזב\"\u0004 — הרי זו ראייה \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003\"זובו\"\u0004 — הרי אלה \u0003תרתי\u0004 \u0005[שתים]\u0006 ראיות, \u0003\"לזכר\"\u0004 — הריהו טמא לענין חיוב קרבן אם היו ראיות אלה שלא באונס. אכן \u0003בשלישי אקשיה רחמנא\u0004 \u0005[הקישו הכתוב]\u0006 \u0003לנקבה.\u0004 ונלמד מכאן שאף אם היתה הראייה השלישית מחמת אונס, דינו כדינה של הזבה, המטמאת אף בראיית אונס.","\u0003ו\u0004אילו \u0003ר' אליעזר דריש\u0004 \u0005[דורש]\u0006 \u0003\"אתים\",\u0004 ולכך נדרש הכתוב באופן זה: \u0003\"הזב\"\u0004 — הרי זו ראייה \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003\"את\"\u0004 — הרי אלה \u0003תרתי\u0004 \u0005[שתי]\u0006 ראיות, \u0003\"זובו\"\u0004 — הרי אלה \u0003תלת\u0004 \u0005[שלוש]\u0006 ראיות. ונצרך הוא בראיות אלה להיבדק אם לא ראה מחמת אונס, שכן אין ראיית אונס מחייבת קרבן. אכן \u0003ברביעי\u0004 (בראייה רביעית) \u0003אקשיה רחמנא\u0004 \u0005[הקישו הכתוב]\u0006 \u0003לנקבה,\u0004 שאף אם ראה ראייה זו באונס הריהי נחשבת כראייה.","ומביאים עוד ראיה שלא כדברי רב הונא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003ר' יצחק אומר: והלא,\u0004 מאחר שכבר הוקשה ראיית זיבה לראיית קרי, נמצא כי ה\u0003זב\u0004 הריהו \u0003בכלל בעל קרי היה, ולמה יצא\u0004 (נכתב בפרשיה נפרדת, בפרשת הזב) — להורות ששונה הוא מדין בעל הקרי, הן לענין שיש \u0003להקל עליו\u0004 יותר מבעל קרי, \u0003ו\u0004לענין שיש \u0003להחמיר עליו\u0004 יותר מבעל קרי. ומפרט: \u0003להקל עליו\u0004 — \u0003שאין\u0004 הזב \u0003מטמא ב\u0004ראיית \u0003אונס,\u0004 ושלא כבעל קרי הנטמא בה. \u0003ולהחמיר עליו\u0004 —"],["\u0003שהוא עושה משכב ומושב,\u0004 כטומאת אב הטומאה, ואילו בעל קרי אינו מטמא כן.","ומעתה יש לשאול בבירור דברי ר' יצחק הללו: \u0003אימת\u0004 \u0005[אימתי]\u0006 נאמרו הדברים הללו, \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהמדובר \u0003בראייה שניה\u0004 של הזיבה — אין לומר כן, שהרי \u0003היכא הוה\u0004 \u0005[איך\u0006 הוא \u0005נהיה]\u0006 \u0003בכלל בעל קרי?\u0004 והרי הוא נעשה זב בשתי ראיות! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שהמדובר \u0003בראייה ראשונה, וקתני\u0004 \u0005[ושנה]\u0006 ר' יצחק כי יש \u0003להקל עליו שאינו מטמא באונס.\u0004 והרי זה איפוא שלא כשיטת רב הונא!","ודוחים את הראיה: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שאמר ר' יצחק את דבריו בראייה ראשונה, אין זה כך, שהרי אמר ר' יצחק כי יש צד \u0003להחמיר עליו שהוא עושה משכב ומושב,\u0004 וכי \u0003בראייה ראשונה בר\u0004 \u0005[בן]\u0006 \u0003משכב ומושב הוא?\u0004","\u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 \u0003ר' יצחק אומר: והלא זב בכלל בעל קרי היה בראייה ראשונה, ולמה יצא\u0004 (נבדל בדינו מבעל קרי) \u0003בראייה שנייה\u0004 — \u0003להקל עליו ולהחמיר עליו, להקל עליו\u0004 — \u0003שאינו מטמא באונס, ולהחמיר עליו\u0004 — \u0003שהוא עושה משכב ומושב.\u0004","ובעניינה של הזיבה \u0003אמר רב הונא:\u0004 ה\u0003זוב\u0004 הריהו \u0003דומה למי בצק\u0004 הנעשה מקמח \u0003של שעורים.\u0004 ובהבדלים שבין הזוב לבין שכבת הזרע: ה\u0003זוב בא מבשר המת\u0004 (חלק גוף שאין בו תחושה), בעוד ש\u0003שכבת זרע בא מבשר החי\u0004 (שיש בו תחושה). ועוד הבחנות: ה\u0003זוב\u0004 — הריהו \u0003דיהה\u0004 (אינו צמיגי ודביק), \u0003ו\u0004במראהו הוא \u0003דומה ללובן ביצה המוזרת\u0004 (בלתי מופרית, שאין אפרוח עתיד לבקוע ממנה). ואילו \u0003שכבת זרע\u0004 — הריהי \u0003קשורה\u0004 (דביקה וצמיגית), \u0003ו\u0004במראה הריהי \u0003דומה ללובן ביצה שאינה מוזרת\u0004 (לא מופרית).","שנינו במשנתנו שנחלקו בית שמאי ובית הלל בדינו של \u0003דם היולדת\u0004 שראתה בימי טהרתה (אחרי שבעה ימים לאחר לידת זכר או שבועיים לאחר לידת נקבה), והריהי בימי טהרה, אלא \u0003שלא טבלה\u0004 כשהסתיימו ימי טומאתה, שלדעת בית שמאי אין דין דם זה כדין דם הנדה, ואין הוא מטמא אלא בלח ולא ביבש. ואילו בית הלל סבורים שכיון שלא טבלה, דם זה אף שהוא בימי טהרה נחשב כדם הנדה, שמטמא בלח וביבש.","ובענין זה עוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו להן בית הלל לבית שמאי:\u0004 וכי \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתם מודים ב\u0004מקרה של אשה \u0003נדה ש\u0004הגיע זמנה לטבול לטהרתה, ו\u0003לא טבלה, וראתה דם, שהיא טמאה\u0004 טומאת נדה לכל דבר? ואם כן אף במקרה זה יש לומר כן. \u0003אמרו להם בית שמאי\u0004 בדחייה: \u0003לא\u0004 תהא מכאן ראיה לנדון שלנו, שכן אף \u0003אם אמרתם\u0004 כך \u0003ב\u0004אשה ה\u0003נדה\u0004 שלא טבלה וראתה דם, שהיא טמאה, שם הדין כן משום \u0003שאפילו טבלה ו\u0004מיד לאחר מכן \u0003ראתה\u0004 שוב הריהי \u0003טמאה.\u0004 אולם האם \u0003תאמרו\u0004 דין זה אף \u0003ביולדת\u0004 שהגיעו ימי טהרתה, \u0003ש\u0004הרי \u0003אם טבלה וראתה\u0004 דם \u0003שהיא טהורה,\u0004 ומעתה, אף שלא טבלה, וראתה, אין היא נחשבת כנדה גמורה לטמא, בלח וביבש.","חזרו בית הלל ו\u0003אמרו להם\u0004 לבית שמאי, כנגד דבריהם אלו: ה\u0003יולדת בזוב\u0004 והיא בימי טהרתה שמנתה שבעת ימי זיבה לאחר שעברו עליה ימי טומאת לידתה, \u0003תוכיח\u0004 שלא כדבריכם. \u0003ש\u0004הרי \u0003אם טבלה\u0004 מזיבתה \u0003וראתה\u0004 דם, \u0003לאחר\u0004 שמנתה כדין הזבה שבעת \u0003ימי ספירה,\u0004 הריהי \u0003טהורה\u0004 שכן היא בתוך ימי טהרתה. ואילו אם \u0003לא טבלה, וראתה\u0004 — הריהי \u0003טמאה,\u0004 ואם כן אף ביולדת שלא טבלה מטומאת לידתה, יש לומר כן, שתהא טמאה כנדה גמורה אם ראתה אף שהיא בימי טהרתה!","\u0003אמרו להם\u0004 בית שמאי: אף במקרה זה שהבאתם \u0003הוא הדין\u0004 שאין היא טמאה בלח וביבש, \u0003והיא התשובה\u0004 (המענה) למה שהבאתם כראיה לשיטתכם.","ודנים עתה בדברים אלה: \u0003למימרא דפליגי\u0004 \u0005[האם לומר\u0006 מתוך כך \u0005שחלוקים]\u0006 בית שמאי ובית הלל בדין היולדת בזוב וספרה שבעת ימי זיבה ולא טבלה, אם מטמאת היא, שלדעת בית שמאי אין היא מטמאת בלח וביבש? \u0003והתנן\u0004 \u0005[והרי שנינו]\u0006 במפורש במשנתנו: \u0003ומודים\u0004 בית שמאי לבית הלל \u0003ביולדת בזוב שהיא מטמאה לח ויבש!\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן מדובר במקרים שונים. \u0003כאן\u0004 בברייתא מדובר \u0003שספרה\u0004 האשה שבעה נקיים לזיבתה, ולכן לשיטת בית שמאי אף שלא טבלה אין היא מטמאת בלח וביבש, ואילו \u0003כאן\u0004 במשנתנו מדובר \u0003שלא ספרה\u0004 עדיין שבעה ימי נקיות לזיבתה, ולכן אף שנכנסה לימי טהרה של לידה, אם ראתה הריהי מטמאת בלח וביבש, ככל נדה.","\u0003והתניא\u0004 \u0005[וכך\u0006 \u0005שנויה\u0006 ברייתא\u0005]\u0006 כדברים האלה, ששנינו בה: ה\u0003יולדת בזוב שספרה\u0004 שבעה נקיים לזיבתה לאחר שהסתיימו ימי טומאת לידתה והחלו ימי טהרת לידתה, \u0003ולא טבלה, וראתה, הלכו בית שמאי לשיטתן\u0004 בדין היולדת הרגילה שעברו עליה ימי טומאתה ולא טבלה וראתה, שאין היא מטמאת בלח וביבש, אף זו שספרה לזיבתה, ולא טבלה וראתה — אינה מטמאת בלח וביבש. \u0003ו\u0004אף \u0003בית הלל\u0004 הלכו במקרה זה \u0003לשיטתן,\u0004 שמטמאה בלח וביבש.","ומתוך שנדון דינו של דם נדות בימי טהרת לידה, מביאים את מה ש\u0003איתמר\u0004 \u0005[נאמר]\u0006 שכך נחלקו חכמים, \u0003רב אמר: מעין\u0004 (מקור) \u0003אחד הוא\u0004 בגוף האשה, שממנו בא דם זה ודם זה, אלא שאת הדם הבא בימי טומאת לידה \u0003התורה טמאתו ו\u0004אילו הדם הבא בימי טהרה \u0003התורה טהרתו.\u0004","\u0003ולוי אמר: שני מעינות\u0004 נפרדים \u0003הם\u0004 בגוף האשה, ומן המקור האחד יוצא הדם הטמא בימי טומאת לידה, ומן המקור האחר יוצא הדם הטהור בימי טהרתה. ואין שני מעיינות אלה משמשים יחד, אלא שבשעה ש\u0003נסתם\u0004 המקור \u0003הטמא\u0004 לאחר ימי טומאת הלידה — \u0003נפתח\u0004 המקור \u0003הטהור,\u0004 ובשעה ש\u0003נסתם\u0004 המקור \u0003הטהור\u0004 לאחר שהסתיימו ימי טהרה (שלושים ושלושה ימים לזכר, שהם ארבעים יום מן הלידה. וששים וששה ימים לנקבה, שהם שמונים יום מן הלידה) — חוזר ו\u0003נפתח\u0004 המקור \u0003הטמא,\u0004 ואם תראה דם — הריהי טמאה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם,\u0006 בין רב ולוי\u0005]?\u0006 ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל במקרה של האשה ה\u0003שופעת\u0004 (הרואה דם ברצף, וללא הפסק) \u0003מתוך שבעה\u0004 ימי טומאה שלאחר לידת זכר \u0003ל\u0004שבעת הימים של \u0003אחר שבעה,\u0004 שהם ימי טהרת לידה לזכר. \u0003ו\u0004השופעת דם \u0003מתוך ארבעה עשר\u0004 ימי טומאה שלאחר לידת נקבה לימי הטהרה של היולדת נקבה של \u0003אחר ארבעה עשר.\u0004 \u0003ו\u0004כן השופעת דם מימי טהרה שהם \u0003מתוך ארבעים\u0004 הימים מלידת הזכר, שבהם הסתיימו ימי טהרה \u0003לאחר ארבעים,\u0004 שכרגיל הרואה בהם דם הריהי ככל אשה הרואה דם. \u0003ו\u0004כן השופעת \u0003מתוך שמנים\u0004 הימים מלידת הנקבה, שבהם הסתיימו ימי טהרתה של היולדת \u0003לאחר שמנים.\u0004","ש\u0003ל\u0004שיטת \u0003רב,\u0004 שמקור אחד הוא לדם הבא בימי טומאה ולדם הבא בימי טהרה — במקרה שב\u0003רישא\u0004 \u0005[התחלה],\u0006 כלומר, בשופעת דם מימי טומאה לימי טהרה, יש לנהוג \u0003לקולא\u0004 \u0005[להקל],\u0006 ולומר: אף שמקור אחד הוא לדם ימי טהרה ולדם ימי הטומאה, ואף ששופעת היא בראיית הדם התורה טיהרה דם זה. \u0003ו\u0004אילו במקרה שב\u0003סיפא\u0004 \u0005[סוף],\u0006 בשופעת דם מימי טהרה לימים שאחריהם — יש לנהוג \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 שהתורה טיהרה את דם ימי הטהרה, וטימאה את שבא לאחריהם.","ואילו \u0003ל\u0004שיטת \u0003לוי\u0004 ששני מקורות שונים הם לדם טהרה ולדם טומאה — במקרה שב\u0003רישא\u0004 \u0005[התחלה]\u0006 בשופעת מימי טומאה לימי טהרה, יש לנהוג \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 ולטמאה, שכן לא התירה התורה בימי טהרה אלא דם הבא ממקור טהור, ואולם דם זה אף שראתה אותו בימי טהרה הריהו בא ברצף מימי טומאתה, ומקורו טמא. \u0003ו\u0004אילו במקרה שב\u0003סיפא\u0004 \u0005[סוף]\u0006 יש לנהוג \u0003לקולא\u0004 \u0005[להקל],\u0006 שאף שראתה את הדם בימים שמעבר לימי טהרה, כיון שלא פסקה — הרי זה דם הבא ממקור טהור, וטהורה היא. ומעתה דנים בשיטותיהם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו במשנתנו: \u0003דם היולדת\u0004 שראתה בימי טהרתה אחר \u0003שלא טבלה\u0004 לאחר ימי טומאתה, \u0003בית שמאי אומרים:\u0004 אין הדם מטמא אלא בלח, \u0003כרוקה וכמימי רגליה, ו\u0004אילו \u0003בית הלל אומרים: מטמא לח ויבש,\u0004 כנדה גמורה.","\u0003קא סלקא דעתך\u0004 \u0005[עולה על דעתך,\u0006 יש להניח\u0005]\u0006 שמדובר בזו שלא שפעה דם, אלא ש\u0003פסקה\u0004 מראיית דם בימי טומאתה, וחזרה וראתה בימי טהרתה. ומעתה יש לדון: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר מעין אחד הוא\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מטמא\u0004 דם זה לשיטת בית הלל \u0003לח ויבש\u0004 כיון שלא טבלה. \u0003אלא ל\u0004שיטת \u0003לוי,\u0004 ש\u0003אמר שני מעינות הן, אמאי\u0004 \u0005[מדוע]\u0006 דם זה \u0003מטמא לח ויבש,\u0004 והרי דם זה הבא בימי טהרה — ממקור אחר הוא בא, והתורה טהרתו?","\u0003אמר לך לוי\u0004 בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן\u0006 במשנתנו \u0005במה אנו עוסקים],\u0006 \u0003בשופעת\u0004 דם מימי טומאתה לימי טהרתה, שכיון שדם אחד הוא זה, הריהי טמאה לשיטת בית הלל, אף שראתה בימי טהרה. ושואלים על כך: \u0003אי\u0004 \u0005[אם]\u0006 המדובר במשנתנו \u0003בשופעת\u0004 דם מימי טומאה לימי טהרה, אם כן \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי\u0004 האומרים שאין דם זה מטמא בלח וביבש? ומשיבים: \u0003קסברי\u0004 \u0005[סבורים הם]\u0006 \u0003בית שמאי\u0004 כי \u0003מעין אחד הוא,\u0004 והתורה טמאה את הדם בזמן שרואה אותו בימי טומאה וטהרתו בזמן שרואה אותו בימי טהרה.","ושואלים לצד האחר, \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003לוי\u0004 הסבור כי שני מעיינות הם, ולשיטתו בית שמאי סבורים שמעיין אחד הוא, \u0003היינו דאיכא\u0004 \u0005[זהו שיש]\u0006 הבדל בדין במשנתנו \u0003בין בית שמאי ובית הלל,\u0004 שכן בית הלל סבורים שאף ששני מעיינות הם, ואולם כיון שלא פסקה מלראות מימי טומאה לימי טהרה, הרי אף דם שראתה בימי טהרה — דם אחד הוא, דם טמא. ואילו בית שמאי סבורים, כאמור, שמעיין אחד הוא, אלא שהתורה טמאה את דם ימי הטומאה וטיהרה את דם ימי הטהרה. \u0003אלא ל\u0004שיטת \u0003רב מאי בינייהו\u0004 \u0005[מה\u0006 יש \u0005ביניהם],\u0006 בין בית שמאי לבית הלל, שאלו מטהרים ואלו מטמאים?","ומסבירים: ההבדל ש\u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הוא באשר למשמעותם של \u0003יומי\u0004 \u0005[הימים]\u0006 \u0003ו\u0004של ה\u0003טבילה\u0004 בתום ימי טומאה, לענין היתרו של הדם בימי טהרה. ובכך נחלקו: \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003ביומי\u0004 \u0005[בימים]\u0006 \u0003תלה רחמנא\u0004 \u0005[הכתוב]\u0006 היתר זה, ומשעה שנכנסו ימי טהרה, כל דם שתראה באותם ימים הריהו טהור אף שלא טבלה בתום ימי טומאה. \u0003ו\u0004אילו \u0003בית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003ביומי\u0004 \u0005[בימים]\u0006 \u0003וטבילה\u0004 תלוי היתר זה. וזו כיון שלא טבלה, אף שהגיעו ימי טהרה, כל דם שתראה הריהו טמא.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו עוד במשנתנו: \u0003ומודים\u0004 בית שמאי לבית הלל \u0003ביולדת בזוב שהיא מטמאה לח ויבש.\u0004 \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך,\u0006 יש להניח\u0005]\u0006 ש\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר באופן ש\u0003פסקה\u0004 האשה מלראות לאחר ימי טומאה, וחזרה וראתה בימי טהרה, וכיון שזבה היא ולא טבלה — מטמאה.","מעתה יש לדון: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר מעין אחד הוא\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מטמא\u0004 דם זה \u0003לח ויבש\u0004 כדין טומאת הנדה, שהרי לא טהרתו תורה לדם זה בימי טהרה. \u0003אלא ל\u0004שיטת \u0003לוי\u0004 ש\u0003אמר שני מעינות הן,\u0004 ודם הבא בימי טהרה — בא ממקור טהור, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מטמא\u0004 דם זה של היולדת בזוב \u0003לח ויבש\u0004 כדין דם הנדה? לא היה לו לטמא אלא בלח, כדין הזבה!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 לוי בתשובה: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אף במקרה זה מדובר \u0003בשופעת\u0004 דם מימי טומאתה לימי טהרתה, ומשום כך הריהי טמאת נדה, שכן דם טמא הוא זה שראתה. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 המדובר \u0003בשופעת,\u0004 \u0003למאי איצטריך\u0004 \u0005[למה נצרך]\u0006 להשמיענו שטמאה היא, והרי פשוט שכך הוא הדין?","ומשיבים: \u0003ל\u0004שיטת \u0003בית שמאי איצטריך\u0004 \u0005[נצרך]\u0006 הדבר להישנות. שכן \u0003אף על גב דקאמרי\u0004 \u0005[אף על פי שאומרים]\u0006 \u0003בית שמאי,\u0004 לשיטת לוי, כי \u0003מעין אחד הוא, וביומי\u0004 \u0005[ובימים]\u0006 בלבד \u0003תלה רחמנא\u0004 \u0005[הכתוב]\u0006 את ימי טהרת הלידה, שכיון שחלפו ימי הטומאה הרי האשה טהורה אף שלא טבלה, ואולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ביולדת גרידתא\u0004 \u0005[בלבד],\u0006 \u0003דשלימו להו יומי\u0004 \u0005[שנשלמו להם הימים,\u0006 ימי טומאה\u0005].\u0006 \u0003אבל יולדת בזוב דבעי\u0004 \u0005[שצריכה]\u0006 \u0003ספירה\u0004 שבעת נקיים על זיבתה — \u0003לא,\u0004 וגם אם ראתה בימי טהרה — הרי היא טמאה טומאת נדה.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: נאמר \"אשה כי תזריע וילדה זכר וטמאה שבעת ימים כימי נדת דותה תטמא\" (ויקרא יב, ב), ומלשונות ייתור שבכתוב דרשו: \u0003\"דו‍תה תטמא\"\u0004 — \u0003לרבות את בועלה,\u0004 שאף בועלה נטמא בטומאת הנדה, ומטמא כמותה.","וריבוי נוסף, \u0003\"דותה תטמא\"\u0004 — \u0003לרבות הלילות\u0004 כימים שבלילות ימי טומאה הריהי מטמאה כבימים. וריבוי נוסף, \u0003\"דו‍תה תטמא\"\u0004 — \u0003לרבות היולדת בזוב שצריכה שתשב שבעה ימים נקיים.\u0004 ומעתה נדון בדבר: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר מעין אחד הוא\u0004 — \u0003משום הכי בעיא\u0004 \u0005[כך צריכה]\u0006 היולדת הזבה לשבת \u0003שבעה ימים נקיים,\u0004"],["\u0003אלא ל\u0004שיטת \u0003לוי\u0004 ש\u0003אמר שני מעינות הן, למה לי\u0004 שתמנה היולדת בזוב \u0003שבעה\u0004 ימים נקיים? \u0003ב\u0004הפסקה של \u0003משהו\u0004 (דבר מועט) \u0003סגיא\u0004 \u0005[די],\u0006 שהרי כיון שיצאה בהפסקה זו מימי טומאה ונסתם המעין הטמא, ומעתה נפתח המעין הטהור והריהי בימי טהרה — די לה שתמתין שבעה ימים, ואפילו אינם נקיים, שהרי כל דם שתראה בימים אלה הוא טהור!","ומשיבים: אכן \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 התנא שבברייתא \u0005אומר]:\u0006 \u0003צריכה שתפסוק משהו\u0004 לאחר ימי טומאה, על מנת לצאת בכך מימי טומאה ולהיכנס לימי טהרה, \u0003ש\u0004בכך יעלו (ייחשבו) \u0003לה\u0004 שבעת הימים הבאים משבעת ימי הטהרה \u0003לשבעה נקיים\u0004 של זבה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו בדין הנשים שדיין שעתן, שאם ראו דם נדות אין הן מטמאות את הטהרות במגען אלא מכאן ולהבא, ובכלל אלו: המעוברת והמניקה. ושנינו בהן כי המעוברת והמניקה שעברו עליהן שלוש עונות (שהן שלוש תקופות של שלושים יום) משעה שהוכר עוברה או משעה שהתחילה — דיין שעתן. ועוד שנינו בהן \u0003ימי עיבורה עולים\u0004 (מצטרפים) \u0003לה לימי מניקותה\u0004 להשלים מנין זה של שלוש עונות. \u0003ו\u0004כן \u0003ימי מניקותה עולים לה לימי עיבורה\u0004 להשלים מנין זה.","ומסבירים: \u0003כיצד, הפסיקה\u0004 האשה מלראות \u0003שתים\u0004 עונות \u0003בימי עיבורה ו\u0004עונה \u0003אחת בימי מניקותה\u0004 (הנקתה), הרי אלו שלוש עונות. וכן אם פסקה מלראות \u0003שתים בימי מניקותה, ואחת בימי עיבורה.\u0004 וכן הוא אם פסקה מלראות עונה \u0003אחת ומחצה בימי עיבורה ו\u0004עונה \u0003אחת ומחצה בימי מניקותה\u0004 — בכל המקרים הללו \u0003עולין לה ל\u0004היחשב כ\u0003שלש עונות\u0004 שלא ראתה בהן, ודיה שעתה, אם ראתה.","ומעתה דנים בדבר: \u0003בשלמא לרב\u0004 ש\u0003אמר מעין אחד הוא\u0004 לדם בימי טומאת לידה ולדם בימי טהרת לידה — \u0003משום הכי בעי\u0004 \u0005[כך צריך]\u0006 \u0003הפסק שלש עונות,\u0004 שלא תראה בהן דם, על מנת שתיחשב כמסולקת דמים. \u0003אלא ללוי\u0004 ש\u0003אמר שני מעינות הן, למה לי הפסק שלש עונות?\u0004 והרי \u0003ב\u0004הפסק \u0003משהו סגי\u0004 \u0005[די],\u0006 שיצאה בהפסק זה מכלל ימי טומאה, ושוב אין זה משנה אם תראה בימי טהרה, שהרי אין זה לשיטת לוי דם הבא ממקור טמא!","ומשיבים: אכן \u0005[כך הוא\u0006 התנא שבברייתא \u0005אומר]:\u0006 \u0003צריכה שתפסוק משהו\u0004 לאחר ימי טומאה, \u0003כדי ש\u0004בכך \u0003יעלו\u0004 (ייחשבו) \u0003לה\u0004 ימי הטהרה \u0003ל\u0004השלמת פרק זמן של \u0003שלש עונות,\u0004 אף אם תראה בהם דם.","ומציעים עוד ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו עוד בדין זה שדיה שעתה: \u0003ו\u0004אף שנחלקו בית שמאי ובית הלל (בתחילת מסכתנו) בדין כל הנשים שראו, שבית שמאי סבורים שדיין שעתן ובית הלל סבורים שמטמאות למפרע מפקידה לפקידה, ואפילו לימים הרבה, \u0003שוין\u0004 הם בדעתם \u0003ב\u0004אשה ה\u0003רואה\u0004 דם ל\u0003אחר דם טוהר\u0004 (בימי טהרה), \u0003ש\u0004אף בית הלל סבורים במקרה זה כי \u0003דיה שעתה.\u0004","ומעתה דנים בדבר, \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003לוי\u0004 ש\u0003אמר שני מעינות הן,\u0004 שאף אם ראתה דם אין זה דם נדות, אלא דם הבא ממקור טהור — הרי זו איפוא בחזקת מסולקת דמים, ו\u0003משום הכי\u0004 \u0005[כך],\u0006 אם ראתה דם דינה הוא ש\u0003דיה שעתה.\u0004 \u0003אלא ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר\u0004 ש\u0003מעין אחד הוא\u0004 לדם הבא בימי טומאה ולדם הבא בימי טהרה, ואם ראתה דם בתוך ימי טהרתה, אף שטהורה היא — אין היא בחזקת מסולקת דמים, ואם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא דינה שאם ראתה לאחר מכן \u0003דיה שעתה? תטמא מעת לעת\u0004 ככל אשה שאינה בחזקת מסולקת דמים!","ומשיבים: מדובר כאן \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שהות\u0004 בין סוף ימי הטהרה וראיית הדם, שאין לומר שתטמא למפרע מעת לעת, שהרי ימי טהרתה הם אלו.","ושואלים: \u0003ו\u0004עדיין מדוע דינה שדיה שעתה, \u0003תטמא\u0004 למפרע את הטהרות שנגעה בהן \u0003מפקידה לפקידה,\u0004 משעת הבדיקה שבדקה ומצאה דם לבין הבדיקה הקודמת לה? ומתרצים: \u0003כיון\u0004 ש\u0003מעת לעת ליכא\u0004 \u0005[אין כאן]\u0006 אפשרות לטמא למפרע (שהרי בכלל ימי טהרה הם), לטמא למפרע \u0003מפקידה לפקידה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים].\u0006","ומציעים עוד ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע], ששנינו בברייתא: ה\u0003יולדת בזוב שספרה\u0004 שבעה נקיים לזיבתה לאחר ימי טומאת לידתה והחלו ימי טהרת לידתה, \u0003ולא טבלה, וראתה, הלכו בית שמאי לשיטתן\u0004 בדין היולדת שעברו עליה ימי טומאתה ולא טבלה וראתה, שאין היא מטמאת בלח וביבש, ואף זו שספרה לזיבתה, וראתה — אינה מטמאת בלח וביבש. \u0003ו\u0004אף \u0003בית הלל\u0004 הלכו במקרה זה \u0003לשיטתן,\u0004 שמטמאה בלח וביבש.","ונדון בדבר: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 ש\u0003אמר מעין אחד הוא,\u0004 ואף הדם שראתה בימי טהרת לידה הריהו דם הבא מאותו מקור, אלא שטיהרתו התורה — \u0003משום הכי\u0004 \u0005[כך],\u0006 אם לא טבלה, אין זה נדון כדם שטיהרתו תורה, ולכן הריהו \u0003מטמא\u0004 לשיטת בית הלל כדם הנדה ב\u0003לח ויבש.\u0004 \u0003אלא ל\u0004שיטת \u0003לוי\u0004 ש\u0003אמר שני מעינות הן,\u0004 והדם הבא בימי טהרת לידה הריהו דם הבא ממקור טהור, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מטמא\u0004 דם זה של היולדת בזוב \u0003לח ויבש,\u0004 והרי ראתה דם זה בימי טהרה?!","ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך לוי\u0004 בתשובה לדבר: \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את שיטתי זו — \u0003כתנא\u0004 של הברייתא שהובאה למעלה כי \u0003שוין\u0004 הם בית שמאי ובית הלל בדין האשה שראתה לאחר דם טוהר, שדיה שעתה. ומוסברת היא ברייתא זו היטב כשיטת לוי, כי שני מעיינות הם, כמבואר למעלה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: מדובר בברייתא זו של היולדת בזוב \u0003בשופעת,\u0004 שכיון שרואה היא דם ברצף מימי טומאתה אל ימי טהרתה, משום כך נחשב הדם שבימי טהרה כדם המטמא. ושואלים על כך: כיצד ניתן להעמיד ברייתא זו בשופעת, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ספרה\u0004 שבעה נקיים\" \u0003קתני\u0004 \u0005[שנינו\u0006 בה\u0005]!\u0006","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא זו \u0003ביולדת נקבה בזוב עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שימי טומאתה של זו הריהם שבועיים. ובאופן זה שב\u0003שבוע קמא\u0004 \u0005[ראשון]\u0006 של ימי טומאתה \u0003פסקה\u0004 מלראות, והרי זה איפוא כספירת שבעת ימי נקיים לזיבתה, ואילו ב\u0003שבוע בתרא\u0004 \u0005[האחרון,\u0006 השני\u0005]\u0006 \u0003לא פסקה,\u0004 שראתה בו דם. ולא טבלה. \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 התנא שבברייתא כי \u0003ימי\u0004 טומאת \u0003לידתה שאין רואה בהן\u0004 — \u0003עולין\u0004 (נחשבים) \u0003לה לספירת זיבתה.\u0004","ובאשר לפסק ההלכה במחלוקת זו שבין רב ולוי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב שמן מ\u0004הישוב \u0003סכרא: אקלע\u0004 \u0005[הזדמן]\u0006 החכם \u0003מר זוטרא לאתרין\u0004 \u0005[למקומנו],\u0006 \u0003ו\u0004כך \u0003דרש: הילכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 של \u0003רב לחומרא\u0004 \u0005[להחמיר],\u0006 כגון באשה השופעת דם מתוך ימי טהרתה לתקופת הימים שאחריהם, ויש לטמאה, כיון שמעיין אחד הוא, שרק בזמן ימי טהרת לידתה נחשב הוא לטהור, ולאחר מכן הריהו מטמא. \u0003והלכתא כוותיה\u0004 \u0005[והלכה כמותו]\u0006 של \u0003לוי לחומרא\u0004 \u0005[להחמיר],\u0006 כגון בשופעת מימי טומאתה לימי טהרתה, שיש לטמאה, כיון ששני מעיינות הם, וכיון שלא נסתם המעיין הטמא — אין המעיין הטהור נפתח, ודם טמא הוא.","ואילו \u0003רב אשי אמר: הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 של \u0003רב, בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר].\u0006 ומוסרים: \u0003דריש\u0004 \u0005[דרש]\u0006 \u0003מרימר: הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 של \u0003רב, בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר].\u0006 \u0003ו\u0004מסכמים: \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 של \u0003רב, בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר].\u0006"],["האשה \u0003ה\u0004מעוברת שהגיעה זמנה ללדת והריהי \u0003מקשה\u0004 (מתקשה) בלידה, ומתוך כך היא רואה דם — הרי זו \u0003נדה.\u0004 האשה ש\u0003קשתה\u0004 בלידה \u0003שלשה ימים\u0004 רצופים, שראתה בהם דם מתוך קושי הלידה, והיו שלושת הימים הללו \u0003בתוך\u0004 תקופת \u0003אחד עשר יום\u0004 (שהם הימים הראויים לזיבה, \"אחד עשר הימים שבין נדה לנדה\"), \u0003ו\u0004לאחר מכן \u0003שפתה\u0004 (נחה) מקישוי הלידה במשך \u0003מעת לעת\u0004 (עשרים וארבע שעות, יממה), מתברר איפוא שהדם שראתה לא מחמת קישוי הלידה בא, אלא דם זיבה הוא, \u0003ו\u0004לכן אם לאחר מכן \u0003ילדה\u0004 — \u0003הרי\u0004 דינה של \u0003זו\u0004 כדין כל ה\u0003יולדת בזוב,\u0004 אלו \u0003דברי ר'\u0004 \u0003אליעזר.\u0004","\u0003ר'\u0004 \u0003יהושע אומר:\u0004 דין זה נוהג רק כאשר שפתה \u0003לילה\u0004 שלם \u0003ו\u0004ב\u0003יום\u0004 שלאחריו, \u0003כ\u0004מו \u0003לילי שבת ו\u0004ב\u0003יומו.\u0004 ומסבירים: זה ששנינו ששפתה האשה — הכוונה היא דווקא \u0003ששפתה מן הצער\u0004 שבלידה, \u0003ולא מן הדם.\u0004 שאף שלא פסק דמה, כיון ששפתה מן הצער, מוכיח הדבר שאין הדם מחמת הלידה, אלא דם זיבה הוא. אבל אם שפתה מן הדם ולא מן הצער — אין זה מוכיח שדם זה הוא דם זיבה.","ומבררים עוד: \u0003כמה היא קישויה,\u0004 מה הוא משך התקופה שלפני הלידה, שבה מוגדר צער הלידה כקישוי, והדם שרואה בו אינו נחשב לדם זיבה? \u0003ר' מאיר אומר: אפילו ארבעים וחמשים יום\u0004 שלפני הלידה, גם אם ראתה בהם בתקופת \"אחד עשר הימים של זיבה\" מתוך צער לידה — אין היא נחשבת ליולדת בזוב. \u0003ר' יהודה אומר: דיה\u0004 שיחול בה דין זה אלא ב\u0003חדשה,\u0004 בחודש שלפני הלידה. \u0003ר' יוסי ור' שמעון אומרים: אין קישוי יותר משתי שבתות\u0004 (שבועות) לפני הלידה. ואם ראתה לפני כן דם אפילו מתוך קושי הלידה — הריהי נחשבת כיולדת בזוב.","שנינו בתחילת משנתנו כי האשה המקשה בלידתה הריהי נדה, ומלשון זו עולה כי הדברים אמורים בכל אשה. ושואלים על כך: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל המקשה נדה היא\u0004 וטמאה, והרי ממשיכה המשנה ואומרת כי המקשה בתקופת אחד עשר הימים של זיבה, אינה נחשבת זבה!","\u0003אמר רב:\u0004 אף המקשה בימי זיבתה, אף שאינה נחשבת זבה, וגם אין דינה כ\"זבה קטנה\" (הצריכה לשמור יום אחד בטהרה כנגד יום טומאה), הריהי \u0003נדה.\u0004 ואולם לא לכל דיני נדה, אלא רק \u0003ליומא\u0004 \u0005[ליום]\u0006 אחד שאסורה באותו היום שראתה בו לשמש עם בעלה, וטובלת בערב, ומותרת לבעלה. \u0003ושמואל אמר:\u0004 גזירת חכמים היא שצריכה היא לשמור יום אחד בטהרה, וטעם הדבר: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תשפה,\u0004 ויתברר איפוא שלא היה זה דם קישוי, וזבה היא.","\u0003ור' יצחק אמר: המקשה\u0004 באחד עשר הימים של זיבה, שראתה בהם דם — \u0003אינה כלום,\u0004 ומותרת לבעלה אף באותו היום. ושואלים על כך: \u0003והקתני\u0004 \u0005[והרי שנינו]\u0006 במשנתנו בלשון כללית כי כל אשה \u0003המקשה\u0004 הריהי \u0003נדה,\u0004 ומשמע שאף הרואה מתוך קישוי בימי זיבתה הריהי נדה!","\u0003אמר רבא:\u0004 כוונת לשון המשנה היא שאם ראתה מתוך קושי לידה \u0003בימי נדה\u0004 — הריהי \u0003נדה,\u0004 אבל אם ראתה מתוך קושי לידה \u0003בימי זיבה\u0004 — הריהי \u0003טהורה.\u0004 וראיה לדבר, \u0003והתניא\u0004 \u0005[ו\u0006אכן שנינו בברייתא\u0005]:\u0006 \u0003המקשה\u0004 בלידתה \u0003בימי נדה\u0004 — הריהי \u0003נדה, בימי זיבה\u0004 — הריהי \u0003טהורה.\u0004","ומפרטים: \u0003כיצד\u0004 הוא הרואה דם בתקופת ימי הזיבה, שלושה ימים רצופים, אם באופן זה ש\u0003קשתה יום אחד\u0004 בצער הלידה, \u0003ו\u0004לאחר מכן \u0003שפתה שנים\u0004 (יומיים) מצער הלידה, אך המשיכה לראות דם. \u0003או שקשתה שנים, ושפתה יום אחד\u0004 מצער הלידה, וראתה בכל שלושת הימים הללו דם. \u0003או ששפתה\u0004 מצער הלידה יום אחד, \u0003וקשתה\u0004 יום אחד בצער הלידה, \u0003וחזרה ושפתה\u0004 יום אחד וראתה בכל שלושת הימים הללו דם — בכל האופנים הללו, כיון שראתה בסוף הימים הללו דם מתוך ששפתה — מוכיח הדבר שלא מחמת הלידה היא שראתה דם, ו\u0003הרי זו\u0004 נחשבת כ\u0003יולדת בזוב.\u0004","\u0003אבל\u0004 אם \u0003שפתה יום אחד וקשתה שנים, או ששפתה שנים וקשתה יום אחד, או שקשתה\u0004 יום אחד \u0003ושפתה\u0004 יום אחד \u0003וחזרה וקשתה\u0004 יום אחד, כיון שראתה בסוף הימים הללו דם מתוך קשי הלידה — מוכיח הדבר שמחמת הלידה ראתה דם, ו\u0003אין\u0004 דינה של \u0003זו\u0004 כ\u0003יולדת בזוב.\u0004 \u0003כללו של דבר:\u0004 אם היתה ראיית דם \u0003קושי\u0004 ב\u0003סמוך ללידה\u0004 — \u0003אין זו יולדת בזוב,\u0004 ואם היתה ראיית דם \u0003שופי\u0004 ב\u0003סמוך ללידה\u0004 — \u0003הרי זו יולדת בזוב.\u0004","\u0003חנניא בן אחי ר'\u0004 \u0003יהושע אומר: ב\u0004\u0003כל\u0004 מקרה \u0003שחל\u0004 ראיית דם מחמת \u0003קישויה ב\u0004יום ה\u0003שלישי שלה\u0004 — אין זו זבה, ו\u0003אפילו כל היום כולו\u0004 היה \u0003בשופי,\u0004 ורק שעה אחת מתוכו היתה מתוך קשי לידה — \u0003אין זו יולדת בזוב,\u0004 שאין ראייה ביום השלישי נחשבת כראייה מן השופי, אלא אם כן היה זה יום שופי שלם.","ושואלים: לשון הכללה זו האמורה בברייתא \u0003\"כללו של דבר\", לאתויי מאי\u0004 \u0005[לרבות מה]\u0006 היא באה? ומשיבים: \u0003לאתויי\u0004 \u0005[לרבות]\u0006 דין זה של \u0003חנניא\u0004 בן אחי ר' יהושע, שצריך שיהיה כל היום השלישי בשופי, כדי שתיחשב הראייה בו כראייה מן השופי, ונטמאת בזיבה.","שנינו במשנתנו שהרואה דם מתוך קשי הלידה בתוך אחד עשר ימי הזיבה, אין דין זבה עליה. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כך \u0005שנו חכמים]\u0006 על האמור בפרשת הזבה \"ואשה כי יזוב זוב דמה ימים רבים\" (ויקרא טו, כה): \u0003\"דמה\"\u0004 — בא למעט שדין זה נוהג דווקא ב\u0003דמה\u0004 הבא \u0003מחמת עצמה, ולא\u0004 בדם הבא \u0003מחמת ולד.\u0004","\u0003ודנים בדרשה זו:\u0004 \u0003אתה אומר\u0004 שבא הכתוב למעט את הרואה דם \u0003מחמת ולד, או אינו אלא\u0004 בא למעט את הרואה דם \u0003מחמת אונס,\u0004 שאינה נחשבת כזבה בכך? ודוחים: אינך יכול לומר כן, משום ש\u0003כשהוא\u0004 הכתוב \u0003אומר \"ואשה כי יזוב זוב דמה\",\u0004 ולשון כוללת זו \"כי יזוב\" באה לרבות — \u0003הרי\u0004 שהזבה, אף אם ראתה דם ב\u0003אונס אמור.\u0004 \u0003הא\u0004 \u0005[הרי,\u0006 אם כן\u0005] ב\u0006\u0003מה אני מקיים\u0004 מה אני למד מהמיעוט \u0003\"דמה\"\u0004 — \u0003דמה\u0004 שבא \u0003מחמת עצמה\u0004 מטמא מחמת זיבה, \u0003ולא\u0004 דם שבא \u0003מחמת ולד.\u0004","\u0003ו\u0004אם תשאל: כיון שיש בכתוב זה ריבוי ויש בו מיעוט, \u0003מה ראית\u0004 (מדוע יש להעדיף) ללמוד ממנו \u0003לטהר את\u0004 הרואה מחמת \u0003הולד ולטמא ב\u0004רואה מחמת \u0003אונס,\u0004 נלמד להיפך, לטהר את הרואה באונס ולטמא את הרואה מחמת ולד! ומסבירים: אלא \u0003מטהר אני ב\u0004רואה דם מחמת ה\u0003ולד\u0004 — \u0003ש\u0004כן \u0003יש טהרה אחריו,\u0004 שהרי לאחר ימי טומאת הלידה יבואו ימי טהרת הלידה, \u0003ומטמא אני ב\u0004רואה דם מחמת \u0003אונס\u0004 — \u0003ש\u0004כן \u0003אין טהרה אחריו.\u0004","ושואלים על כך: \u0003אדרבה\u0004 (להיפך), אפשר לומר: \u0003מטהר אני ב\u0004אשה שראתה דם מחמת \u0003אונס\u0004 — \u0003שכן\u0004 דין הוא שהרואה זיבה ב\u0003אונס בזב טהור\u0004 הוא, ויהא הדין כן אף באשה, ונטהר את הרואה מחמת לידה? ודוחים: \u0003השתא מיהא\u0004 \u0005[עתה על כל פנים]\u0006 \u0003ב\u0004עניינה של \u0003האשה\u0004 הזבה \u0003קיימינן\u0004 \u0005[עומדים אנו],\u0006 \u0003ואונס באשה,\u0004 ולא באיש, \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 שטהור הוא. ומשום כך, עדיף ללמוד מן הכתוב לטמא את האשה הרואה באונס, ולטהר את האשה הרואה מחמת קשי הלידה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לשאלתך זו: \u0003מאי דעתיך\u0004 \u0005[מה דעתך,\u0006 רצונך\u0005]\u0006 בשאלתך זו, \u0003לטהורי\u0004 \u0005[לטהר]\u0006 את האשה הרואה \u0003באונס ולטמויי\u0004 \u0005[ולטמא]\u0006 \u0003ב\u0004אשה הרואה מחמת קשי ה\u0003ולד?\u0004 ואולם הוא עצמו, קשי הלידה, \u0003אין לך אונס גדול מזה!\u0004","ושואלים על דרשה זו: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 דורשים אנו מכתוב זה לענין הזבה, מעתה בדין ה\u0003נדה נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 באופן דומה: נאמר \"ואשה כי תהיה זבה דם יהיה זובה בבשרה שבעת ימים תהיה בנדתה\" (שם יט), ונדרוש: \u0003\"זבה\"\u0004 — שנטמאת בנדה דווקא בדם \u0003זובה\u0004 הבא \u0003מחמת עצמה ולא\u0004 מדם הבא \u0003מחמת ולד?\u0004","\u0003ונדון:\u0004 \u0003אתה אומר\u0004 כי דין זה בא למעט את הרואה דם נדה מחמת קושי ה\u0003ולד, או אינו\u0004 בא למעט \u0003אלא\u0004 את הרואה דם נדה מחמת אונס? אינך יכול לומר כן משום ש\u0003כשהוא\u0004 הכתוב \u0003אומר \"ואשה כי תהיה זבה\"\u0004 — \u0003הרי\u0004 דם הבא מחמת \u0003אונס אמור\u0004 שהוא בכלל טומאת הנדה, אלא \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים,\u0004 איזה מיעוט אני למד מהאמור \u0003\"זבה\"\u0004 שאין היא נדה בו — דווקא דם \u0003זובה\u0004 הבא \u0003מחמת עצמה\u0004 מטמאה בנדה, \u0003ולא\u0004 דם הבא \u0003מחמת ולד.\u0004 ומדוע שנינו בברייתא כי דם קישוי לידה שנראה בימי נדה מטמא בנדה?","\u0003אמר ריש לקיש: אמר קרא\u0004 \u0005[הכתוב]\u0006 בעניינם של ימי טהרת לידה, שאף אם ראתה בהם דם הריהי טהורה: \u0003\"תשב\u0004 על דמי טהרה\" (שם יב, ה), והרי כתוב זה מלמדנו: \u0003יש לך\u0004 באשה \u0003ישיבה אחרת שהיא כזו,\u0004 שאף בה אינה נטמאת בדם שרואה, \u0003ואיזו\u0004 היא \u0003זו\u0004 — \u0003זו\u0004 דם הבא מחמת \u0003קושי\u0004 לידה \u0003ב\u0004אחד עשר \u0003ימי זיבה,\u0004 ולא בנדה. ושואלים: \u0003ואימא\u0004 \u0005[ו\u0006שמא \u0005אמור]\u0006 שאכן יש עוד הרואה דם ואינה נטמאת בו ואולם \u0003זו\u0004 הרואה דם מחמת \u0003קושי\u0004 לידה \u0003בימי נדה,\u0004 ולא בזבה?","\u0003אלא אמר אבוה\u0004 \u0005[אביו]\u0006 של שמואל: אמר קרא \u0005[הכתוב]\u0006 בדין ימי טומאתה של היולדת נקבה \u0003\"וטמאה שבעים כנדתה\"\u0004 (שם ה) — \u0003ולא כזיבתה.\u0004 \u0003מכלל\u0004 \u0005[מכאן]\u0006 שיש אופן שדם הבא בתקופת \u0003זיבתה\u0004 הריהו \u0003טהור, ואיזו\u0004 ראיית דם היא \u0003זו\u0004 שאינה מטמאה בזיבה — \u0003זו\u0004 ראיית דם מחמת \u0003קושי\u0004 לידה \u0003בימי זיבה.\u0004","ושואלים: \u0003והשתא דכתיב\u0004 \u0005[ועכשיו שנאמר]\u0006 לימוד זה שמן הכתוב \u0003\"וטמאה שבעים כנדתה\",\u0004 אם כן הכתוב \u0003\"דמה\"\u0004 שממנו למדנו דבר זה מקודם, \u0003למה לי?\u0004 ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היה בידינו אף את הלימוד מ\u0003\"דמה\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \"וטמאה שבועיים כנדתה\" מלמד כך: \u0003כנדתה ולא כזיבתה, ואפילו\u0004 ראתה דם זיבה \u0003בשופי\u0004 (רגועה מצער הלידה) לא תיטמא בכך כזבה. לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הלימוד הנוסף מהכתוב \"דמה\", שאין דין זה אמור אלא ברואה מחמת קושי לידה בלבד.","לשיטת רב (הנאמרת למעלה) כי האשה הרואה דם מחמת קושי לידה בתקופת אחד עשר ימי הזיבה נוהגת כנדה באותו היום, שאסורה היא לבעלה באותו היום וטובלת בערב, נמסר כי \u0003שילא בר אבינא עבד עובדא כוותיה\u0004 \u0005[עשה מעשה כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003רב,\u0004 שהורה כך הלכה למעשה. ומסופר: \u0003כי קא נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 כשנפטר\u0005]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 \u0003לרב אסי: זיל צנעיה\u0004 \u0005[לך הצנע,\u0006 תעלים הלכה זו\u0005]\u0006 שתאמר לשילא בר אבינא, שאין זו הלכה. \u0003ואי לא ציית\u0004 \u0005[ואם לא יציית,\u0006 יקשיב\u0005]\u0006 שילא בר אבינא לדברים הללו — \u0003גרייה\u0004 \u0005[גררהו,\u0006 מושכהו בדברים\u0005]\u0006 עד שישתכנע שאין זו הלכה. \u0003הוא\u0004 רב אסי \u0003סבר\u0004 \u0005[סבור היה]\u0006 שרב לשון \u0003\"גדייה\"\u0004 \u0005[הכריתהו,\u0006 החרם אותו\u0005] אם לא יציית\u0006 \u0003אמר ליה\u0004 \u0005[לו].\u0006","\u0003בתר דנח נפשיה\u0004 \u0005[אחר שנחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב,\u0004 הלך רב אסי אצל שילא בר אבינא ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הדר\u0004 \u0005[חזור]\u0006 \u0003בך\u0004 מהלכה זו שאתה מורה בה כך למעשה על פי שיטתו של רב, \u0003דהדר ביה\u0004 \u0005[ש\u0006כן \u0005חזר בו]\u0006 \u0003רב\u0004 עצמו מהלכה זו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שילא בר אבינא לרב אסי: לא חזר בו רב, שכן \u0003אם איתא דהדר ביה\u0004 \u0005[יש\u0006 מקום לדבריך \u0005שחזר בו]\u0006 — \u0003לדידי הוה אמר\u0004 \u0005[לי עצמי היה אומר]\u0006 \u0003לי\u0004 שחזר בו, שכן תלמידו אני, ולא היה שולח שליח לומר לי דברים אלו. ולכן \u0003לא ציית\u0004 לו שילא בר אבינא לרב אסי בדבר זה. הלך רב אסי, ו\u0003גדייה\u0004 \u0005[החרים אותו],\u0006 כפי שהיה סבור שכך אמר לו רב לעשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שילא בר אבינא: \u0003ולא מסתפי מר מדליקתא\u0004 \u0005[ו\u0006כי \u0005אין אדוני ירא מתבערה]\u0006 מעונש על שפגעת בי?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אסי בדרך מליצה, ודרש את משמעות שמו כשם של תנא חשוב לציין כעין רמז על שם דומה: \u0003אנא\u0004 \u0005[אני]\u0006 הוא \u0003איסי בן יהודה,\u0004 ש\u0003הוא איסי בן גור אריה,\u0004 ש\u0003הוא איסי בן גמליאל,\u0004 ש\u0003הוא איסי בן מהללאל\u0004 ומורה שם זה ל\u0003אסיתא דנחשא\u0004 \u0005[מדוכת נחושת],\u0006 \u0003דלא שליט ביה רקבא\u0004 \u0005[שאין שולט בה הרקב],\u0006 כלומר, לא אפגע מכל רע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שילא בר אבינא: \u0003ואנא\u0004 \u0005[ואני]\u0006 הוא הנקרא \u0003שילא בר אבינא,\u0004 ומורה שמו של אבי ל\u0003בוכנא דפרזלא, דמתבר אסיתא דנחשא\u0004 \u0005[לבוכנת ברזל, המשבר מדוכת נחושת],\u0006 כלומר, שתוכל זכות אבותי לפגוע אף בך.","ומסופר כי בעקבות הדברים \u0003חלש\u0004 \u0005[חלה]\u0006 \u0003רב אסי,\u0004 והיה מיטלטל ממחלה למחלה, \u0003עיילוה בחמימי אפקוה מקרירי\u0004 \u0005[נכנס לחום\u0006 קדחת \u0005ויצא מצינון],\u0006 \u0003עיילוה בקרירי אפקוה מחמימי\u0004 \u0005[נכנס בצינון ויצא מחום],\u0006 ומתוך כך \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רב אסי.\u0004"],["ומסופר כי מיד לאחר שנפטר רב אסי \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003שילא\u0004 בר אבינא ו\u0003אמר לדביתהו\u0004 \u0005[לאשתו]:\u0006 \u0003צבית\u0004 \u0005[הואילי]\u0006 להכין \u0003לי זוודתא\u0004 \u0005[ציוד,\u0006 תכריכים\u0005]\u0006 לקבורה, שאמות במהרה. וזאת על מנת ש\u0003לא ליזיל\u0004 \u0005[ילך]\u0006 רב אסי \u0003ולימא ליה\u0004 \u0005[ויאמר לו]\u0006 \u0003לרב מילי עילואי\u0004 \u0005[דברים\u0006 של גנות \u0005עלי],\u0006 שלא שמעתי בקולו, וגרמתי בהקפדתי למותו של רב אסי. \u0003צביתה ליה זוודתא\u0004 \u0005[הכינה לו תכריכים],\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003שילא.\u0004 \u0003והובילו לקבורה את מיטותיהם של רב אסי ושל שילא בר אבינא ביחד.\u0004 \u0003חזו\u0004 \u0005[ראו]\u0006 המלווים את הנפטרים לקבורה \u0003דפרחא אסא מהאי פוריא להאי פוריא\u0004 \u0005[שפורח הדס ממיטה זו למיטה זו],\u0006 שכך היה מנהג, להניח הדס על מיטתו של הנפטר. \u0003אמרי\u0004 \u0005[אמרו]\u0006 המלווים זה לזה: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003עבדו רבנן פייסא\u0004 \u0005[עשו החכמים פיוס,\u0006 שלום\u0005]\u0006 ביניהם.","ועוד בדין דם הבא מחמת קושי הלידה, שאינו מטמא בזיבה, אבל מטמא בנדה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 הזבה המונה שבעה נקיים לזיבתה, וראתה דם — הריהי סותרת כל מה שמנתה עד אז, ומתחילה שוב למנות שבעה נקיים. ואולם אשה מעוברת זבה הסופרת שבעה נקיים לזיבתה, וכרעה ללדת, וראתה דם מחמת \u0003קושי\u0004 הלידה \u0003מהו\u0004 דינה לענין זה \u0003שתסתור בזיבה?\u0004","וצדדי השאלה: האם כל \u0003דבר המטמא סותר\u0004 את מנין שבעה נקיים, \u0003והאי נמי\u0004 \u0005[ו\u0006דם \u0005זה גם כן]\u0006 הריהו בגדר זה, שכן \u0003מטמא כימי נדה הוא,\u0004 ועל כן סותרת מניינה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 דווקא \u0003דבר הגורם\u0004 לה להיות זבה, הוא ה\u0003סותר\u0004 את מניינה, \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003גורם\u0004 טומאת זיבה \u0003הוא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 דין הראייה מ\u0003אונס בזיבה יוכיח, שאינו גורם\u0004 זיבה, שהרי אין הרואה מאונס נטמא בזיבה, \u0003ו\u0004בכל זאת הזב המונה לטהרתו וראה באונס הריהו \u0003סותר\u0004 מניינו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בדחיית ראיה זו: \u0003לאיי, האי נמי\u0004 \u0005[באמת, זה\u0006 הרואה באונס לזיבתו \u0005גם כן]\u0006 \u0003גורם הוא\u0004 לזיבתו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת זבים\u0005]:\u0006 מי ש\u0003ראה ראייה ראשונה\u0004 של זיבה — \u0003בודקין אותו\u0004 בשבע בדיקות שונות, כדי לדעת אם ראה ראייה זו מחמת אונס, ואז אינו נטמא בכך. וכן אם ראה ראייה \u0003שניה\u0004 של זיבה — שוב \u0003בודקין אותו\u0004 בבדיקות אלה. ואילו כשראה ראייה \u0003שלישית\u0004 — \u0003אין בודקין אותו,\u0004 שכן אף אם ראה באונס — הריהו נטמא בכך, הרי שראיית אונס בזב הינו גורם לזיבה.","שאלו אביי: \u0003ול\u0004שיטת \u0003ר' אליעזר\u0004 המובאת באותה משנה, ש\u0003אמר\u0004 כי \u0003אף בשלישי בודקין אותו, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003כיון\u0004 שראייה מאונס \u0003לא גרים\u0004 \u0005[אינה גורמת]\u0006 טומאת זב, הוא גם \u0003לא סתר\u0004 \u0005[אינו סותר]\u0006 את מנין הימים שנמנו עד אז? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לר' אליעזר, הכי נמי\u0004 \u0005[כך גם כן]\u0006 שאין ראיית אונס סותרת.","ומביאים ראיה שלא כדברי רבא בהסבר שיטת ר' אליעזר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ששנינו בברייתא כי \u0003ר' אליעזר אומר\u0004 ש\u0003אף בשלישית בודקין אותו\u0004 אם היתה ראייה זו באונס לענין חיוב הקרבן, ואולם \u0003ב\u0004ראייה \u0003רביעית\u0004 שוב \u0003אין בודקין אותו.\u0004 ובטעם דין הראייה הרביעית יש לומר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003ל\u0004ענין \u0003סתירה\u0004 של מנין שבעת ימי נקיותו (שהרי כבר התחייב בטומאת זיבה בבדיקה שלישית). ומכאן שלדעת ר' אליעזר אף ראייה מחמת אונס סותרת את מנין שבעת ימי נקיות הזב.","ודוחים: \u0003לא,\u0004 אין מכאן הוכחה שאפשר לומר שמטרת הבדיקה הרביעית הוא \u0003ל\u0004ענין \u0003טמויה לההיא\u0004 \u0005[לטמא את אותה]\u0006 \u0003טיפה\u0004 של הזב \u0003במשא\u0004 (שתטמא את הנושא אותה), וסבור ר' אליעזר שאין מקום לבדיקה זו, שהרי אף אם ראה באונס, מטמאת הטיפה את הנושא אותה.","ומציעים עוד פתרון לשיטת ר' אליעזר בראייה מחמת אונס, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003ב\u0004ראייה \u0003שלישית, ר'\u0004 \u0003אליעזר אומר\u0004 ש\u0003בודקין אותו,\u0004 ואולם \u0003ב\u0004ראייה \u0003רביעית\u0004 — \u0003אין בודקין אותו,\u0004 וטעם הדבר: עיקרה של הבדיקה \u0003ל\u0004ענין חיובו ב\u0003קרבן\u0004 הוא ש\u0003אמרתי ולא לסתירה,\u0004 וראייה רביעית אינה אלא לענין סתירה. עולה מכאן שראיה זו שבאונס, אף שאינה מחייבת בקרבן, סותרת את מנין שבעת ימי נקיותו של הזב.","ומסכמים: \u0003אלא\u0004 אכן \u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 אמנם \u0003תפשוט\u0004 מכאן שגם ה\u0003דבר שאינו גורם\u0004 לזב להיטמא בו, הריהו \u0003סותר\u0004 את מנין ימי נקיותו. ואולם \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 הוא הדין?","ומציעים פתרון, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' אבין\u0004 מדוע ראיית זיבה סותרת כל מנין שבעת ימי נקיותו של הזב (ושלא כראיית קרי): \u0003מה\u0004 (כשם) ש\u0003גרם לו זובו\u0004 טומאת \u0003שבעה\u0004 ימים, \u0003לפיכך\u0004 הזוב גורם לו גם כן להיות \u0003סותר\u0004 את מנין \u0003שבעה.\u0004 \u0003מה\u0004 (כשם) ש\u0003גרם לו קריו\u0004 טומאת \u0003יום אחד\u0004 בלבד, \u0003לפיכך\u0004 ראיית קרי גם כן גורמת לו להיות \u0003סותר\u0004 \u0003יום אחד\u0004 בלבד.","ויש לברר: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה בזיבה הגורמת לטומאת \u0003שבעה? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא לזוב מתחילתו ש\u0003מטמא שבעה\u0004 ימים — \u0003האי\u0004 \u0005[זה]\u0006 ששונים אנו \"מה גרם לו זובו שבעה\" אינו מדויק (שכן אין זה גרם בלבד) אלא \u0003\"מה זובו טמא שבעה\" מבעי ליה\u0004 \u0005[נצרך לו\u0006 לשנות\u0005],\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא לומר כי דווקא \u0003דבר הגורם\u0004 (כזוב) לטומאה הוא ה\u0003סותר\u0004 מנין שבעת ימי נקיות. מה שאין כן \u0003דבר שאינו גורם\u0004 לטומאת זיבה (כדם קושי) — \u0003אינו סותר\u0004 מנין שבעה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך היא שיטת חכמים.","ולענין הלכה \u0003אמר אביי: נקטינן\u0004 \u0005[אוחזים אנו,\u0006 כך מקובל בידינו\u0005]\u0006 כי \u0003אין\u0004 דם \u0003קושי סותר\u0004 מנין שבעה ימי נקיות \u0003בזיבה,\u0004 וכשיטת חכמים. \u0003ואי משכחת\u0004 \u0005[ואם מוצא אתה]\u0006 \u0003תנא\u0004 ש\u0003אמר\u0004 שדם קושי \u0003סותר\u0004 מנין שבעה בזיבה — דעת התנא \u0003ההוא\u0004 כשיטת \u0003ר' אליעזר היא.\u0004","ועוד בענין סתירת שבעת ימי נקיות של זיבה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מרינוס אומר:\u0004 האשה הזבה הסופרת שבעה ימים לנקיותה, וילדה בתוך כך — \u0003אין\u0004 ה\u0003לידה סותרת ב\u0004מנין שבעת ימי נקיות של \u0003זיבה.\u0004 ומעתה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 \u0003מהו\u0004 הדין לענין \u0003ש\u0004אף \u0003תעלה\u0004 (תיכלל) ימי טומאתה של היולדת בכלל שבעת ימי נקיות של זיבה? \u0003אביי אמר:\u0004 הלידה אמנם \u0003אינה סותרת\u0004 את מנין שבעת ימי זיבה, \u0003ו\u0004אולם \u0003אינה עולה\u0004 למנין שבעת ימי זיבה. ואילו \u0003רבא אמר\u0004 כי הלידה \u0003אינה סותרת ו\u0004אף \u0003עולה\u0004 למנין שבעת ימי זיבה.","ומסבירים, \u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני,\u0006 מה המקור\u0005]\u0006 לשיטתי זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק \"וספרה לה שבעת ימים \u0003ואחר תטהר\"\u0004 (ויקרא טו, כח). ומורה לנו הכתוב \u0003\"אחר\"\u0004 — שיהא זה \u0003אחר\u0004 שספרה הזבה \u0003ל\u0004שבעת ימי הנקיות \u0003כולן,\u0004 וללמדנו \u0003שלא תהא טומאה מפסקת ביניהם.\u0004","ומעתה יש לומר: \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אומר אתה]\u0006 שהלידה \u0003עולה\u0004 לשבעת ימי נקיותה — \u0003היינו\u0004 \u0005[זהו]\u0006 שאמרו ש\u0003לא\u0004 תהא \u0003מפסקת טומאה\u0004 את שבעת ימי הנקיות, ואכן אין טומאת הלידה מפסיקה את שבעת ימי הנקיות. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהלידה \u0003אינה עולה\u0004 — נמצא איפוא ש\u0003אפסיק ליה\u0004 \u0005[הפסיקה לה]\u0006 ה\u0003לידה\u0004 את רצף ימי הנקיות! \u0003ואביי אמר לך\u0004 בדחיית דברי רבא: אין להביא מכאן ראיה, כיון שפירוש הדרשה \"אחר לכולן\" מתייחס רק להפסקה הבאה על ידי טומאת זיבה, וללמדנו \u0003שלא תהא טומאת זיבה מפסקת ביניהם.\u0004","חזר ו\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני,\u0006 מה המקור\u0005]\u0006 לשיטתי זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על הכתוב באותו הפסוק \"ואם טהרה \u0003מזובה\u0004 וספרה לה שבעת ימים ואחר תטהר\", ובא הכתוב \u0003\"מזובה\u0004 וספרה לה\" למעט: נדרשת היא לספור שבעה ימים דווקא מזובה, \u0003ולא מנגעה,\u0004 שאם הצטרעה זבה זו, הריהי סופרת שבעת ימים לזיבתה, אף שטמאה היא בטומאת הצרעת. וכן ממעט הכתוב \u0003\"מזובה\u0004 וספרה לה\" למעט: נדרשת היא לספור שבעה ימים דווקא מזובה, \u0003ולא מלידתה.\u0004 שאין ימי טומאת הלידה סותרים את מניינה. בדחיית דברי רבא, כי מכתוב זה \u0003תני חדא\u0004 \u0005[שנה\u0006 דרשה \u0005אחת],\u0006 \u0003\"מזובה\" ולא מנגעה, ולא תתני\u0004 \u0005[תשנה]\u0006 דרשה נוספת מכתוב זה \"מזובה\" \u0003ולא מלידתה.\u0004","\u0003ורבא\u0004 מה משיב הוא על דברי אביי אלה — \u0003האי מאי\u0004 \u0005[זה מה\u0006 ענינן\u0005]?\u0006 שאין לומר כדברי אביי, שהרי \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אומר אתה]\u0006 את הדרשה \u0003\"מזובה\" ולא מלידתה,\u0004 מבינים אנו מדוע הובאה יחד אתה גם הדרשה \"מזובה\" ולא מנגעה. שכן \u0003איידי דאצטריך ליה\u0004 \u0005[מתוך שהוצרך לו]\u0006 להביא מיעוט זה לענין \u0003לידה, תנא\u0004 \u0005[שנה]\u0006 גם את המיעוט הזה לענין \u0003נגעה, אטו\u0004 \u0005[אגב]\u0006 שהובא המיעוט לענין \u0003לידה.\u0004 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 רק את הדרשה \u0003\"מזובה\" ולא מנגעה,\u0004 ובלא הדרשה \"מזובה ולא מלידתה\" — מה מקום להביא דרשה זו, שהרי \u0003האי\u0004 \u0005[זה]\u0006 \u0003מ\u0004הכתוב \u0003\"וכי יטהר הזב מזובו\"\u0004 (שם יג) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר, ובאופן זה: \u0003\"מזובו\" ולא מנגעו!\u0004","\u0003ואביי,\u0004 מה משיב הוא על דברי רבא אלה — יש צורך בשני הלימודים הללו שבענין הנגע, \u0003חד\u0004 \u0005[אחד]\u0006 \u0003בזב, וחד\u0004 \u0005[ואחד]\u0006 \u0003בזבה.\u0004 \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 הם שייאמרו שניהם, משום \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006"],["\u0003בזב\u0004 בלבד, ולא בזבה — היה מקום לומר שדווקא בזב הקלה התורה, \u0003משום\u0004 שבכלל דינו קל מדין הזבה, שהרי הזב \u0003לא מטמיא ב\u0004ראיית זוב ב\u0003אונס.\u0004 \u0003אבל זבה\u0004 שהחמיר בה הכתוב, \u0003דמטמא\u0004 \u0005[שנטמאת]\u0006 אף \u0003ב\u0004ראיית \u0003אונס\u0004 — \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 נאמרה בה הלכה זו שסופרת שבעה לנגעה. לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 לימוד נוסף לעניינה של הזבה.","\u0003ו\u0004מן הצד האחר, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 הלכה זו \u0003בזבה\u0004 בלבד, ולא בזב — היה מקום שבזבה הקלה התורה, \u0003משום\u0004 שדינה קל מדינו של הזב, שהרי הזבה \u0003לא מטמיא\u0004 \u0005[אינה נטמאת]\u0006 \u0003ב\u0004שלוש \u0003ראיות\u0004 ביום אחד \u0003כ\u0004דרך שהיא נטמאת \u0003ב\u0004ראייה רצופה של שלושה \u0003ימים, אבל זב\u0004 ש\u0003מטמא\u0004 \u0003ב\u0004שלוש \u0003ראיות\u0004 אפילו ביום אחד \u0003כ\u0004דרך שהוא נטמא \u0003ב\u0004ראיית שלושה \u0003ימים —\u0004 \u0003אימא\u0004 \u0005[אומר]\u0006 ש\u0003לא\u0004 נאמרה בו הלכה זו שסופר שבעה ימים לנגעו. לכך \u0003צריכא\u0004 \u0005[צריך]\u0006 לימוד נוסף לזב.","ובהסבר שיטתו \u0003אמר אביי:\u0004 \u0003מנא אמינא לה\u0004 \u0005[מנין אומר אני,\u0006 מה המקור\u0005]\u0006 לשיטתי זו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בטומאת לידה \"כימי נדת \u0003דו‍תה תטמא\"\u0004 (ויקרא יב, ב) בא \u0003לרבות\u0004 שהיולדת מטמאת אף \u0003את בועלה,\u0004 כדרך שמטמאתו הנדה.","ועוד נלמד מהכתוב \u0003\"דו‍תה תטמא\"\u0004 — שאף שנאמר בטומאתה לשון ימים (\"כימי נדת\"), למדים אנו מכאן לרבות אף \u0003את הלילות\u0004 בטומאה זו. ועוד למדים מן הכתוב \u0003\"דו‍תה תטמא\"\u0004 — \u0003לרבות את היולדת בזוב, שצריכה שתשב שבעה נקיים.\u0004","ונברר: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה לומר שצריכים שבעת ימי נקיותה של הזבה להיות \u0003נקיים מ\u0004ימי טומאת \u0003לידה.\u0004 והרי שאין ימי טומאת לידה עולים לימי שבעת ימי נקיות של זיבה, וכשיטתי. ודוחים: \u0003לא,\u0004 אין זו ראיה לשיטת אביי, שהרי אפשר לומר שכוונת דרשה זו שצריכים שבעת ימי הנקיות להיות נקיים \u0003מדם,\u0004 ואין ללמוד מכאן לימי טומאת לידה שלא ראתה בהם דם.","חזר \u0003ואמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני,\u0006 מה המקור\u0005]\u0006 לשיטתי — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 בכתוב בענין טומאת לידה \"כימי נדת דותה תטמא\" השווה הכתוב את דין טומאת הלידה לדין טומאת הנדה, ללמדנו: \u0003כ\u0004דינם של \u0003ימי נדתה, כך\u0004 הוא דינם של \u0003ימי לידתה.\u0004 \u0003מה ימי נדתה\u0004 — \u0003אין ראוין לזיבה\u0004 (שהרי אין זיבה אלא באחד עשר הימים שלאחר שבעת ימי נדה), \u0003ו\u0004נמצא איפוא כי \u0003אין\u0004 אפשרות שתהא \u0003ספירת שבעה\u0004 ימי נקיים של זיבה \u0003עולה מהן\u0004 (מימי נדות). מעתה נלמד כי \u0003אף ימי\u0004 טומאת \u0003לידתה, שאין\u0004 הם \u0003ראוין לזיבה\u0004 (שהרי אין דם לידה מטמא בזיבה), הריהם כימי נדות — \u0003אין ספירת שבעה\u0004 ימי נקיות של זיבה \u0003עולה מהן.\u0004","ושואלים: \u0003ורבא,\u0004 הסבור שימי טומאה עולים לספירת שבעה נקיים של זב, מה הוא משיב על הדברים שבברייתא? — לדעתו \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר\u0004 כי ימי טומאת הלידה לא רק שאינם עולים למנין שבעת ימי נקיים של הזבה, אלא \u0003מסתר נמי סתרה\u0004 \u0005[לסתור גם כן סותרת]\u0006 היא את מנין השבעה.","ודנים עתה בדברי הברייתא המשווה את דינם של ימי טומאה לדינם של ימי נדות, שבאלה ובאלה אין דין זיבה, ותוהים על כך: \u0003וכי דנין\u0004 למדים דינו של דבר ש\u0003אפשר\u0004 הוא שיתרחש במציאות (כלידה, שיכולה היא להתרחש בתוך ספירת שבעה נקיים של זיבה) \u0003מ\u0004דינו של דבר \u0003שאי אפשר\u0004 לו שיתרחש במציאות (כנדה, שהרי אין נדות חלה בימי ספירה זיבות)?","\u0003אמר רב אחדבוי בר אמי:\u0004 ברייתא זו כשיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר\u0004 כי \u0003דנין\u0004 דבר ש\u0003אפשר מ\u0004דבר \u0003שאי אפשר.\u0004 \u0003ורב ששת אמר\u0004 הסבר אחר: אף שכלל הוא שאין למדים דבר שאפשר מדבר שאי אפשר, ואולם בענייננו אין אומרים כן, כיון \u0003שעל כרחך הקישן הכתוב\u0004 לשתי טומאות אלה, של לידה ושל נדה, זו לזו, כאמור בפסוק, ובדבר הנלמד בהיקש למדים גם אפשר משאי אפשר. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך את שני ההסברים הללו, בשינוי שם, \u0003אמר רב אחדבוי בר אמי, אמר רב ששת: ר'\u0004 \u0003אליעזר היא,\u0004 ש\u0003אמר דנין אפשר משאי אפשר, ו\u0004אילו \u0003רב פפא אמר: על כרחך הקישן הכתוב.\u0004","שנינו במשנתנו שאם היולדת \u0003קשתה\u0004 ללדת וראתה דם \u0003שלשה ימים\u0004 בזה אחר זה, בתוך אחד עשר ימי זיבה, ולאחר מכן שפתה (נרגעה ממכאוביה) במשך יממה מאז ראתה דם, וילדה — אין דם זה נחשב כדם קושי (שאינו מטמא בטומאת הזיבה), אלא הריהו כשאר דם זיבה. שכיון ששפתה ודאי אין זה דם קושי. ועוד שנינו כי די שתשפה מן הצער במשך יממה לפני הלידה, כדי שתיחשב זבה בראיית דם, ואין צורך שתשפה אף מן הדם. ולכך, אם שפתה מצער הלידה, יש בדבר כדי ללמד שאין זה דם קושי, ולכך הריהי נעשית זבה.","ובעקבות הדברים הללו \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמי בית המדרש\u0005]\u0006 שאלה זו: האשה ש\u0003שפתה\u0004 גם \u0003מזה\u0004 (מצער הלידה) \u0003ו\u0004גם \u0003מזה\u0004 (מדם) \u0003מהו\u0004 דינה? — נחלקו חכמים בדבר. \u0003רב חסדא אמר:\u0004 מאחר ששפתה מצער הלידה, הרי זה מוכיח שאין זה דם קושי, ולכך הריהי \u0003טמאה\u0004 בזיבה. ואילו \u0003ר' חנינא אמר\u0004 כי מאחר ששפתה גם מן הדם, התברר איפוא כי דם הקושי מחמת הלידה בא, ולכך הריהי \u0003טהורה.\u0004","\u0003אמר ר'\u0004 \u0003חנינא\u0004 בהסבר שיטתו: \u0003משל\u0004 למה הדבר דומה? \u0003למלך שיצא\u0004 מארמונו, \u0003ו\u0004בתחילה \u0003חיילותיו\u0004 מקדימים ויוצאים \u0003לפניו,\u0004 והוא בא אחריהם. ואף שאין המלך מהלך אתם, \u0003בידוע\u0004 הוא \u0003שחיילותיו של מלך הן.\u0004 וכיוצא בדבר בענייננו, שאף ששפתה היולדת מצערה ומדמה — הדם שראתה לפני הלידה, בידוע הוא שדם לידה הוא, וטהורה היא מזיבה.","\u0003ו\u0004אילו \u0003רב חסדא אמר\u0004 כשאף הוא מתייחס בדבריו למשל זה: אכן לפני בואו של המלך יוצאים חיילותיו, ואולם לאחריהם \u0003כל שכן דבעי נפיש\u0004 \u0005[שצריך יותר]\u0006 \u0003חיילות טפי\u0004 \u0005[רבים]\u0006 המלווים את המלך בבואו, ומשלא באו חיילים רבים ונוספים מיד לאחריו, ודאי אינם מחיילותיו. ולענייננו כיון שלאחר שהצטערה וראתה דם, שפתה במשך יממה, אף שלאחר אותו יום ראתה דם הרי זה מלמד שאין הוא קשור ללידה, אלא הריהו כשאר דם זיבה, וטמאה היא.","ומקשים על דברי רב חסדא: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו עוד\u0005]\u0006 ש\u0003ר' יהושע אומר\u0004 בהגדרתה של שפיית יממה זו, שהריהי נחשבת כשפייה רק כאשר היתה מתחילת ה\u0003לילה ו\u0004עד סוף ה\u0003יום\u0004 שלאחריו, והרי זו יממה \u0003כ\u0004דרך שיום השבת הריהו \u0003לילי שבת ויומו.\u0004 וכן שאין השפייה נחשבת כהפסקה אלא כ\u0003ששפתה מן הצער ולא מן הדם.\u0004 ויש לדייק בדברים אלה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 הסיבה\u0005]\u0006 שהריהי טמאה בשפייה זו — משום ששפתה \u0003מן הצער ולא מן הדם, הא\u0004 \u0005[הרי]\u0006 נלמד מכאן שאם שפתה \u0003מזה ומזה\u0004 — הריהי \u0003טהורה,\u0004 וכשיטת ר' חנינא, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב חסדא.\u0004","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003רב חסדא\u0004 שכוונת המשנה: \u0003לא מבעיא\u0004 \u0005[אין צורך]\u0006 להשמיענו בזמן ששפתה \u0003מזה ומזה\u0004 — ש\u0003טמאה\u0004 היא, \u0003דפסקי להו\u0004 \u0005[ש\u0006הרי \u0005פסקו להם,\u0006 שאין נראים כלל\u0005]\u0006 ה\u0003חיילות\u0004 של המלך \u0003לגמרי\u0004 (כדרך משלו של ר' חנינא), שאין לא צער ולא דם. \u0003אבל\u0004 בזמן ששפתה \u0003מן הצער ולא\u0004 שפתה \u0003מן הדם, אימר\u0004 \u0005[אומר,\u0006 יש מקום לומר\u0005]:\u0006 \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003מדם\u0004 היא \u0003לא פסקה\u0004 — \u0003מקושי\u0004 הלידה היא \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא פסקה, והא\u0004 \u0005[וזה]\u0006 שהיא לא חשה בצער — \u0003תונבא בעלמא\u0004 \u0005[טשטוש כללי]\u0006 \u0003הוא דנקט לה\u0004 \u0005[שאחז אותה],\u0006 שכאבי הלידה גרמו לה לחולשה כללית, עד שאין היא חשה בצער הלידה, ותהא טהורה. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 ר' יהושע \u0005משמיע לנו]\u0006 שכיון ששפתה מצער, הרי זה מוכיח שאין זה מכלל דם קושי הלידה, ודם זה מטמאה בזיבה.","ומקשים עתה על דברי ר' חנינא: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 שאם \u0003קשתה שלשה ימים בתוך אחד עשר יום\u0004 של הימים הראויים לזיבה, \u0003ו\u0004לאחר מכן \u0003שפתה מעת לעת וילדה —\u0004 \u0003הרי זו\u0004 נחשבת כ\u0003יולדת בזוב.\u0004","ויש לברר את הדברים הללו: \u0003היכי דמי\u0004 \u0005[איך בדיוק היה הדבר]?\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם תאמר כמו ששנינו]\u0006 ששפתה מצערה, אך המשיכה בראיית דם — \u0003למה לי\u0004 לומר שקשתה \u0003שלש\u0004 (ימים), והרי \u0003בתרי\u0004 \u0005[בשני]\u0006 ימים \u0003בקושי וחד\u0004 \u0005[ו\u0006יום \u0005אחד]\u0006 \u0003בשופי סגי\u0004 \u0005[די],\u0006 שהרי גם ביום שנרגעה מהצער, עדיין רואה היא בו דם!","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אומרת\u0006 המשנה\u0005]:\u0006 \u0003קשתה שלשה\u0004 ימים, \u0003ושפתה מזה ומזה\u0004 (מצערה ומראיית דם), \u0003או שקשתה שנים\u0004 ימים \u0003ושפתה מעת לעת\u0004 מצערה — \u0003הרי זו\u0004 נחשבת \u0003יולדת בזוב,\u0004 שלא כשיטת ר' חנינא, \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 היא על \u0003ר' חנינא!\u0004","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול \u0005לומר לך]\u0006 \u0003ר' חנינא: לא,\u0004 אלא לעולם נלמד בה \u0003כדקתני\u0004 \u0005[כפי שהיא שנויה],\u0006 שראתה דם במשך שלושה ימים בצער, ולאחר מכן שפתה מצערה והמשיכה לראות דם. \u0003ו\u0004אשר לשאלה מה מלמדנו דבר זה — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיעה לנו]\u0006 המשנה \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003מתחיל קישוי ב\u0004תחילתו של היום ה\u0003שלישי, ו\u0004לאחר מכן \u0003שפתה\u0004 מצערה \u0003מעת לעת,\u0004 והמשיכה לראות דם — הריהי \u0003טמאה,\u0004 ובאו הדברים ללמדנו: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטתו של \u0003ר' חנינא\u0004 בן ר' יהושע (בדף הקודם) הסבור כי בכל מקרה של זו שראתה דם שלושה ימים בימי זיבתה, ואולם ביום השלישי חשה בצער לידה (אף לזמן קצר, ואף שחזרה לאחר מכן ולא חשה בקושי הלידה במשך יממה), שאינה נחשבת יולדת בזוב.","עוד שנינו במשנתנו: למשך \u0003כמה\u0004 זמן \u0003היא קשויה\u0004 של היולדת? \u0003ר' מאיר אומר:\u0004 אפילו ארבעים וחמישים יום לפני הלידה. ותוהים על לשון הדברים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאמרת שב\u0003חמשים\u0004 ימים הריהי \u0003מקשיא\u0004 \u0005[מקשה]\u0006 ללדת, שהריהי מקשה אף ב\u0003ארבעים\u0004 ימים \u0003מיבעיא\u0004 \u0005[צריך]\u0006 לומר? \u0003אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאמרו במשנה שקישויה הוא חמישים יום — הרי זה \u0003ל\u0004יולדת ה\u0003חולה,\u0004 ואילו \u0003כאן\u0004 שאמרו שקישויה אפילו ארבעים יום — הרי זה \u0003ל\u0004יולדת ה\u0003בריאה.\u0004","ועוד בדינה של המקשה שאינה נטמאת בזיבה, \u0003אמר ר'\u0004 \u0003לוי: אין הולד\u0004 הנולד בלידה שלאחר הקישוי \u0003מטהר\u0004 את אמו מלהיחשב זבה, \u0003אלא\u0004 רק אם ראתה דם באחד עשר ה\u0003ימים הראויין להיות בהן זבה,\u0004 ולא אם ראתה בימים הראויים לנדות, ובאים לפני אחד עשר ימי הזיבה ולאחריהם. \u0003ו\u0004אילו \u0003רב אמר\u0004 כי \u0003אפילו\u0004 אם ראתה \u0003ב\u0004שבעת ה\u0003ימים ה\u0004באים לאחר אחד עשר ימי הזיבה ו\u0003ראויין לספירת זבה\u0004 ולהיטמא בטומאת נדה — אין היא נטמאת בזיבה. \u0003אומר רב אדא בר אהבה: ולטעמיה\u0004 \u0005[ולטעמו,\u0006 לשיטתו\u0005]\u0006 של \u0003רב,\u0004"]]};
